window.VOCAB = [{"id": "1-1", "list": 1, "number": 1, "english": "business", "phonetic": "/ˈbɪznəs/", "chinese": "n. 公司，生意", "example": "She runs the business by herself. 她自己经营这项生意。", "page": 2}, {"id": "1-2", "list": 1, "number": 2, "english": "design", "phonetic": "/dɪˈzaɪn/", "chinese": "v. 设计", "example": "She wants to design a new park. 她想设计一座新公园。", "page": 2}, {"id": "1-3", "list": 1, "number": 3, "english": "material", "phonetic": "/məˈtɪriəl/", "chinese": "n. 材料；布料", "example": "This soft material is perfect for a scarf. 这种柔软的材料很适合做围巾。", "page": 2}, {"id": "1-4", "list": 1, "number": 4, "english": "sew", "phonetic": "/soʊ/", "chinese": "v. 缝纫", "example": "My mother can sew a dress for me. 我妈妈能为我缝制一条裙子。", "page": 2}, {"id": "1-5", "list": 1, "number": 5, "english": "successful", "phonetic": "/səkˈsesfl/", "chinese": "adj. 成功的", "example": "She gave a successful presentation. 她做了一次成功的演讲。", "page": 2}, {"id": "1-6", "list": 1, "number": 6, "english": "follow", "phonetic": "/ˈfɑːloʊ/", "chinese": "v. 关注（社交媒体）", "example": "Many students follow this science channel. 许多学生关注这科学频道。", "page": 2}, {"id": "1-7", "list": 1, "number": 7, "english": "keyboard", "phonetic": "/ˈkiːbɔːrd/", "chinese": "n. 键盘（乐器）", "example": "He practices on the keyboard every afternoon. 他每天下午练习键盘乐器。", "page": 2}, {"id": "1-8", "list": 1, "number": 8, "english": "Physics", "phonetic": "/ˈfɪzɪks/", "chinese": "n. 物理学", "example": "Physics helps us understand how things work. 物理学帮助我们理解事物的原理。", "page": 2}, {"id": "1-9", "list": 1, "number": 9, "english": "actor", "phonetic": "/ˈæktər/", "chinese": "n. 演员", "example": "The actor prepared for his new role. 这位演员为他的新角色做准备。", "page": 2}, {"id": "1-10", "list": 1, "number": 10, "english": "brother", "phonetic": "/ˈbrʌðər/", "chinese": "n. 兄弟", "example": "My younger brother likes to play soccer. 我的弟弟喜欢踢足球。", "page": 2}, {"id": "1-11", "list": 1, "number": 11, "english": "businessperson", "phonetic": "/ˈbɪznəsmæn/", "chinese": "n. 商人", "example": "I met a friendly businessperson at the store. 我在商店遇到了一位友好的商人。", "page": 3}, {"id": "1-12", "list": 1, "number": 12, "english": "chef", "phonetic": "/ʃef/", "chinese": "n. 厨师", "example": "The chef is cooking our dinner now. 厨师正在为我们做晚餐。", "page": 3}, {"id": "1-13", "list": 1, "number": 13, "english": "doctor", "phonetic": "/ˈdɑːktər/", "chinese": "n. 医生", "example": "The doctor was very kind and patient. 那位医生非常和善且有耐心。", "page": 3}, {"id": "1-14", "list": 1, "number": 14, "english": "engineer", "phonetic": "/ˌendʒɪˈnɪr/", "chinese": "n. 工程师", "example": "An engineer fixed the broken machine. 一位工程师修好了那台坏掉的机器。", "page": 3}, {"id": "1-15", "list": 1, "number": 15, "english": "father", "phonetic": "/ˈfɑːðər/", "chinese": "n. 父亲", "example": "My father reads the newspaper every morning. 我父亲每天早上看报纸。", "page": 3}, {"id": "1-16", "list": 1, "number": 16, "english": "manager", "phonetic": "/ˈmænɪdʒər/", "chinese": "n. 经理", "example": "The store manager welcomed the customers. 商店经理欢迎了顾客们。", "page": 3}, {"id": "1-17", "list": 1, "number": 17, "english": "mother", "phonetic": "/ˈmʌðər/", "chinese": "n. 母亲", "example": "My mother makes the best apple pie. 我母亲做的苹果派最好吃。", "page": 3}, {"id": "1-18", "list": 1, "number": 18, "english": "scientist", "phonetic": "/ˈsaɪəntɪst/", "chinese": "n. 科学家", "example": "The scientist discovered a new plant. 那位科学家发现了一种新植物。", "page": 3}, {"id": "1-19", "list": 1, "number": 19, "english": "sister", "phonetic": "/ˈsɪstər/", "chinese": "n. 姐妹", "example": "My sister and I share a room. 我和我的姐妹共用一个房间。", "page": 3}, {"id": "1-20", "list": 1, "number": 20, "english": "lens", "phonetic": "/lenz/", "chinese": "n. 镜片", "example": "I cleaned the lens of my camera. 我清洗了我的相机镜头。", "page": 3}, {"id": "1-21", "list": 1, "number": 21, "english": "sentence", "phonetic": "/ˈsentəns/", "chinese": "n. 句子", "example": "Please write a complete sentence here. 请在这里写一个完整的句子。", "page": 4}, {"id": "1-22", "list": 1, "number": 22, "english": "fragment", "phonetic": "/ˈfræɡmənt/", "chinese": "n. 片段；不完整句子", "example": "This is a sentence fragment, not a full one. 这是一个句子片段，不是完整的句子。", "page": 4}, {"id": "1-23", "list": 1, "number": 23, "english": "period", "phonetic": "/ˈpɪriəd/", "chinese": "n. 句号", "example": "Don’t forget to put a period at the end. 别忘了在结尾加上句号。", "page": 4}, {"id": "1-24", "list": 1, "number": 24, "english": "punctuation", "phonetic": "/ˌpʌŋktʃuˈeɪʃn/", "chinese": "n. 标点符号", "example": "Good punctuation makes writing clear. 好的标点符号让文章更清晰。", "page": 4}, {"id": "1-25", "list": 1, "number": 25, "english": "paragraph", "phonetic": "/ˈpærəɡræf/", "chinese": "n. 段落", "example": "Each paragraph has one main idea. 每个段落都有一个中心思想。", "page": 4}, {"id": "1-26", "list": 1, "number": 26, "english": "subject", "phonetic": "/ˈsʌbdʒɪkt/", "chinese": "n. 主语", "example": "The subject of the sentence is “Tom”. 这个句子的主语是“汤姆”。", "page": 4}, {"id": "1-27", "list": 1, "number": 27, "english": "verb", "phonetic": "/vɜːrb/", "chinese": "n. 动词", "example": "A verb often shows an action or state. 动词通常表示一个动作或状态。", "page": 4}, {"id": "1-28", "list": 1, "number": 28, "english": "comma", "phonetic": "/ˈkɑːmə/", "chinese": "n. 逗号", "example": "Use a comma when you make a list. 列清单时要用逗号。", "page": 4}, {"id": "1-29", "list": 1, "number": 29, "english": "attend", "phonetic": "/əˈtend/", "chinese": "v. 参加；出席", "example": "I will attend a meeting tomorrow. 我明天要参加一个会议。", "page": 4}, {"id": "1-30", "list": 1, "number": 30, "english": "break", "phonetic": "/breɪk/", "chinese": "n. 休息", "example": "We have a ten-minute break now. 我们现在有十分钟的休息时间。", "page": 4}, {"id": "1-31", "list": 1, "number": 31, "english": "coworker", "phonetic": "/'kəʊˌwɜːkə/", "chinese": "n. 同事", "example": "My coworker sits next to me. 我的同事坐在我旁边。", "page": 5}, {"id": "1-32", "list": 1, "number": 32, "english": "customer", "phonetic": "/ˈkʌstəmər/", "chinese": "n. 顾客", "example": "The customer asked for some help. 那位顾客请求了一些帮助。", "page": 5}, {"id": "1-33", "list": 1, "number": 33, "english": "groceries", "phonetic": "/ˈɡroʊsəriz/", "chinese": "n. 食品杂货", "example": "We bought a lot of groceries. 我们买了很多食品杂货。", "page": 5}, {"id": "1-34", "list": 1, "number": 34, "english": "leader", "phonetic": "/ˈliːdər/", "chinese": "n. 领导者", "example": "A good leader listens to team members. 一个好的领导者会听团队成员的意见。", "page": 5}, {"id": "1-35", "list": 1, "number": 35, "english": "object", "phonetic": "/ˈɑːbdʒekt/", "chinese": "n. 宾语；物体", "example": "The direct object receives the action. 直接宾语接受动作。", "page": 5}, {"id": "1-36", "list": 1, "number": 36, "english": "speed", "phonetic": "/spiːd/", "chinese": "n. 速度", "example": "The car is moving at a very high speed. 汽车正以非常高的速度行驶。", "page": 5}, {"id": "1-37", "list": 1, "number": 37, "english": "strange", "phonetic": "/streɪndʒ/", "chinese": "adj. 奇怪的", "example": "We saw a strange light in the sky. 我们看到天空中有一道奇怪的光。", "page": 5}, {"id": "1-38", "list": 1, "number": 38, "english": "thin", "phonetic": "/θɪn/", "chinese": "adj. 瘦的，薄的，细的", "example": "This paper is too thin for drawing. 这张纸太薄了，不适合画画。", "page": 5}, {"id": "1-39", "list": 1, "number": 39, "english": "technology", "phonetic": "/tekˈnɑːlədʒi/", "chinese": "n. 科技", "example": "Modern technology changes our lives fast. 现代科技迅速地改变着我们的生活。", "page": 5}, {"id": "1-40", "list": 1, "number": 40, "english": "knock", "phonetic": "/nɑːk/", "chinese": "v. 敲，撞", "example": "Please knock on the door before entering. 请在进入前敲门。", "page": 5}, {"id": "1-41", "list": 1, "number": 41, "english": "explore", "phonetic": "/ɪkˈsplɔːr/", "chinese": "v. 探索", "example": "They want to explore the ancient forest. 他们想去探索那片古老的森林。", "page": 6}, {"id": "1-42", "list": 1, "number": 42, "english": "maybe", "phonetic": "/ˈmeɪbi/", "chinese": "adv. 可能", "example": "Maybe we can go swimming tomorrow. 也许我们明天可以去游泳。", "page": 6}, {"id": "1-43", "list": 1, "number": 43, "english": "astronomer", "phonetic": "/əˈstrɑːnəmər/", "chinese": "n. 天文学家", "example": "An astronomer studies stars and planets. 天文学家研究恒星和行星。", "page": 6}, {"id": "1-44", "list": 1, "number": 44, "english": "direction", "phonetic": "/dəˈrekʃn/", "chinese": "n. 方向；指导", "example": "Can you give me directions to the library? 你能告诉我去图书馆的方向吗？", "page": 6}, {"id": "1-45", "list": 1, "number": 45, "english": "professor", "phonetic": "/prəˈfesər/", "chinese": "n. 教授", "example": "The professor gave an interesting lecture. 教授做了一场有趣的讲座。", "page": 6}, {"id": "1-46", "list": 1, "number": 46, "english": "information", "phonetic": "/ˌɪnfərˈmeɪʃn/", "chinese": "n. 信息；资料", "example": "I found useful information in this book. 我在这本书里找到了有用的信息。", "page": 6}, {"id": "1-47", "list": 1, "number": 47, "english": "exactly", "phonetic": "/ɪɡˈzæktli/", "chinese": "adv. 精确地；正是", "example": "That is exactly what I wanted to say. 那正是我想说的话。", "page": 6}, {"id": "1-48", "list": 1, "number": 48, "english": "however", "phonetic": "/haʊˈevər/", "chinese": "adv. 然而；无论如何", "example": "It's raining; however, we still go out. 天在下雨，然而我们仍然出门了。", "page": 6}, {"id": "1-49", "list": 1, "number": 49, "english": "increase", "phonetic": "/ɪnˈkriːs/", "chinese": "v. 增加；增长", "example": "Reading can increase your vocabulary. 阅读可以增加你的词汇量。", "page": 6}, {"id": "2-1", "list": 2, "number": 1, "english": "question", "phonetic": "/ˈkwestʃən/", "chinese": "n. 问题", "example": "I have a question about the homework. 我有一个关于作业的问题。", "page": 7}, {"id": "2-2", "list": 2, "number": 2, "english": "answer", "phonetic": "/ˈænsər/", "chinese": "n./v. 答案；回答", "example": "Please answer the teacher’s question. 请回答老师的问题。", "page": 7}, {"id": "2-3", "list": 2, "number": 3, "english": "student", "phonetic": "/ˈstuːdnt/", "chinese": "n. 学生", "example": "Every student in the class is here. 班上的每个学生都在这里。", "page": 7}, {"id": "2-4", "list": 2, "number": 4, "english": "teacher", "phonetic": "/ˈtiːtʃər/", "chinese": "n. 教师", "example": "Our teacher is very kind and helpful. 我们的老师非常和善且乐于助人。", "page": 7}, {"id": "2-5", "list": 2, "number": 5, "english": "writer", "phonetic": "/ˈraɪtər/", "chinese": "n. 作家", "example": "She wants to become a famous writer. 她想成为一名著名的作家。", "page": 7}, {"id": "2-6", "list": 2, "number": 6, "english": "start", "phonetic": "/stɑːrt/", "chinese": "v. 开始", "example": "Let’s start the game at three o’clock. 我们三点钟开始游戏吧。", "page": 7}, {"id": "2-7", "list": 2, "number": 7, "english": "college", "phonetic": "/ˈkɑːlɪdʒ/", "chinese": "n. 大学", "example": "Her eldest boy is at college. 她的长子在上大学。", "page": 7}, {"id": "2-8", "list": 2, "number": 8, "english": "own", "phonetic": "/oʊn/", "chinese": "adj. 自己的", "example": "He has his own bicycle now. 他现在有了自己的自行车。", "page": 7}, {"id": "2-9", "list": 2, "number": 9, "english": "other", "phonetic": "/ˈʌðər/", "chinese": "adj. 其他的", "example": "Some students are here, but others are not. 一些学生在这里，但其他学生不在。", "page": 7}, {"id": "2-10", "list": 2, "number": 10, "english": "most", "phonetic": "/moʊst/", "chinese": "adj. 大多数的", "example": "Most children love to play outside. 大多数孩子喜欢在外面玩。", "page": 7}, {"id": "2-11", "list": 2, "number": 11, "english": "also", "phonetic": "/ˈɔːlsoʊ/", "chinese": "adv. 也", "example": "I like apples, and I also like bananas. 我喜欢苹果，我也喜欢香蕉。", "page": 8}, {"id": "2-12", "list": 2, "number": 12, "english": "become", "phonetic": "/bɪˈkʌm/", "chinese": "v. 成为", "example": "She hopes to become a scientist. 她希望成为一名科学家。", "page": 8}, {"id": "2-13", "list": 2, "number": 13, "english": "might", "phonetic": "/maɪt/", "chinese": "modal v. 可能", "example": "It might rain later this afternoon. 今天下午晚些时候可能会下雨。", "page": 8}, {"id": "2-14", "list": 2, "number": 14, "english": "each", "phonetic": "/iːtʃ/", "chinese": "adj./pron. 每个", "example": "Each student gets a new book. 每个学生都得到一本新书。", "page": 8}, {"id": "2-15", "list": 2, "number": 15, "english": "both", "phonetic": "/boʊθ/", "chinese": "adj./pron. 两者都", "example": "Both answers are correct. 两个答案都是正确的。", "page": 8}, {"id": "2-16", "list": 2, "number": 16, "english": "such", "phonetic": "/sʌtʃ/", "chinese": "adj. 这样的", "example": "It was such a beautiful day. 那真是美好的一天。", "page": 8}, {"id": "2-17", "list": 2, "number": 17, "english": "already", "phonetic": "/ɔːlˈredi/", "chinese": "adv. 已经", "example": "He has already finished his lunch. 他已经吃完了他的午餐。", "page": 8}, {"id": "2-18", "list": 2, "number": 18, "english": "yet", "phonetic": "/jet/", "chinese": "adv. 还，尚", "example": "My homework is not done yet. 我的作业还没完成。", "page": 8}, {"id": "2-19", "list": 2, "number": 19, "english": "without", "phonetic": "/wɪˈðaʊt/", "chinese": "prep. 没有", "example": "He went to school without breakfast. 他没吃早餐就去上学了。", "page": 8}, {"id": "2-20", "list": 2, "number": 20, "english": "simple", "phonetic": "/ˈsɪmpl/", "chinese": "adj. 简单的", "example": "The instructions are very simple. 说明非常简单。", "page": 8}, {"id": "2-21", "list": 2, "number": 21, "english": "colourful", "phonetic": "/ˈkʌlərfl/", "chinese": "adj. 色彩鲜艳的", "example": "She drew a colourful picture of a garden. 她画了一幅色彩鲜艳的花园图。", "page": 9}, {"id": "2-22", "list": 2, "number": 22, "english": "capital", "phonetic": "/ˈkæpɪtl/", "chinese": "adj. 大写的；(n.) 首都", "example": "Beijing is the capital of China. 北京是中国的首都。", "page": 9}, {"id": "2-23", "list": 2, "number": 23, "english": "alphabet", "phonetic": "/ˈælfəbet/", "chinese": "n. 字母表", "example": "We are learning the English alphabet. 我们正在学习英语字母表。", "page": 9}, {"id": "2-24", "list": 2, "number": 24, "english": "vowel", "phonetic": "/ˈvaʊəl/", "chinese": "n. 元音", "example": "The letter “A” is a vowel. 字母“A”是一个元音。", "page": 9}, {"id": "2-25", "list": 2, "number": 25, "english": "main", "phonetic": "/meɪn/", "chinese": "adj. 主要的", "example": "This is the main street of our town. 这是我们镇上的主街。", "page": 9}, {"id": "2-26", "list": 2, "number": 26, "english": "middle", "phonetic": "/ˈmɪdl/", "chinese": "n. 中间", "example": "My seat is in the middle of the room. 我的座位在房间的中间。", "page": 9}, {"id": "2-27", "list": 2, "number": 27, "english": "practice", "phonetic": "/ˈpræktɪs/", "chinese": "n. 练习", "example": "Daily practice improves your skills. 每日练习能提高你的技能。", "page": 9}, {"id": "2-28", "list": 2, "number": 28, "english": "wrap", "phonetic": "/ræp/", "chinese": "v. 包裹", "example": "Please wrap the gift in red paper. 请用红纸把礼物包起来。", "page": 9}, {"id": "2-29", "list": 2, "number": 29, "english": "reliable", "phonetic": "/rɪˈlaɪəbl/", "chinese": "adj. 可靠的", "example": "My friend is always reliable and helpful. 我的朋友总是可靠且乐于助人。", "page": 9}, {"id": "2-30", "list": 2, "number": 30, "english": "tourist", "phonetic": "/ˈtʊrɪst/", "chinese": "n. 游客", "example": "Many tourists visit this famous museum. 许多游客参观这个著名的博物馆。", "page": 9}, {"id": "2-31", "list": 2, "number": 31, "english": "variety", "phonetic": "/vəˈraɪəti/", "chinese": "n. 多样化；种类", "example": "The shop sells a variety of fruits. 这家商店出售各种各样的水果。", "page": 10}, {"id": "2-32", "list": 2, "number": 32, "english": "preposition", "phonetic": "/ˌprepəˈzɪʃn/", "chinese": "n. 介词", "example": "Words like “in” and “on” are prepositions. “in”和“on”这样的词是介词。", "page": 10}, {"id": "2-33", "list": 2, "number": 33, "english": "lost", "phonetic": "/lɔːst/", "chinese": "adj. 丢失的；消失的", "example": "He found his lost keys under the bed. 他在床下找到了丢失的钥匙。", "page": 10}, {"id": "2-34", "list": 2, "number": 34, "english": "finally", "phonetic": "/ˈfaɪnəli/", "chinese": "adv. 最终", "example": "We finally reached the top of the hill. 我们最终到达了山顶。", "page": 10}, {"id": "2-35", "list": 2, "number": 35, "english": "sink", "phonetic": "/sɪŋk/", "chinese": "v. 沉没", "example": "A heavy stone will sink in water. 一块重石头会在水中下沉。", "page": 10}, {"id": "2-36", "list": 2, "number": 36, "english": "strike", "phonetic": "/straɪk/", "chinese": "v. 袭击", "example": "The lion crouched ready to strike. 狮子蹲身准备袭击。", "page": 10}, {"id": "2-37", "list": 2, "number": 37, "english": "natural", "phonetic": "/ˈnætʃrəl/", "chinese": "adj. 自然的", "example": "We should protect our natural environment. 我们应该保护我们的自然环境。", "page": 10}, {"id": "2-38", "list": 2, "number": 38, "english": "report", "phonetic": "/rɪˈpɔːrt/", "chinese": "v. 报告", "example": "Please report any problems to the teacher. 请向老师报告任何问题。", "page": 10}, {"id": "2-39", "list": 2, "number": 39, "english": "piece", "phonetic": "/piːs/", "chinese": "n. 部分；碎块", "example": "She ate a piece of chocolate cake. 她吃了一块巧克力蛋糕。", "page": 10}, {"id": "2-40", "list": 2, "number": 40, "english": "purpose", "phonetic": "/ˈpɜːrpəs/", "chinese": "n. 目的；目标", "example": "The purpose of this meeting is to plan. 这次会议的目的是制定计划。", "page": 10}, {"id": "2-41", "list": 2, "number": 41, "english": "earthquake", "phonetic": "/ˈɜːrθkweɪk/", "chinese": "n. 地震", "example": "The earthquake made the buildings shake. 地震使建筑物摇晃。", "page": 11}, {"id": "2-42", "list": 2, "number": 42, "english": "desert", "phonetic": "/ˈdezərt/", "chinese": "n. 沙漠", "example": "It rarely rains in the hot desert. 在炎热的沙漠里很少下雨。", "page": 11}, {"id": "2-43", "list": 2, "number": 43, "english": "realize", "phonetic": "/ˈriːəlaɪz/", "chinese": "v. 认识到；实现", "example": "I realize that I made a mistake. 我意识到我犯了一个错误。", "page": 11}, {"id": "2-44", "list": 2, "number": 44, "english": "structure", "phonetic": "/ˈstrʌktʃər/", "chinese": "n. 结构；建筑物", "example": "This old structure is over 500 years old. 这座古老的建筑有500多年的历史了。", "page": 11}, {"id": "2-45", "list": 2, "number": 45, "english": "similar", "phonetic": "/ˈsɪmələr/", "chinese": "adj. 相似的", "example": "Our answers are quite similar. 我们的答案非常相似。", "page": 11}, {"id": "2-46", "list": 2, "number": 46, "english": "island", "phonetic": "/ˈaɪlənd/", "chinese": "n. 岛屿", "example": "They spent a week on a tropical island. 他们在热带岛屿上度过了一周。", "page": 11}, {"id": "2-47", "list": 2, "number": 47, "english": "greedy", "phonetic": "/ˈɡriːdi/", "chinese": "adj. 贪婪的", "example": "The greedy man wanted all the money. 那个贪婪的人想要所有的钱。", "page": 11}, {"id": "3-1", "list": 3, "number": 1, "english": "during", "phonetic": "/ˈdʊrɪŋ/", "chinese": "prep. 在...期间", "example": "We read a book during the quiet afternoon. 我们在安静的下午读了一本书。", "page": 12}, {"id": "3-2", "list": 3, "number": 2, "english": "need", "phonetic": "/niːd/", "chinese": "v. 需要", "example": "Plants need sunlight and water to grow. 植物需要阳光和水才能生长。", "page": 12}, {"id": "3-3", "list": 3, "number": 3, "english": "climate", "phonetic": "/ˈklaɪmət/", "chinese": "n. 气候", "example": "The climate here is warm and sunny. 这里的气候温暖而阳光充足。", "page": 12}, {"id": "3-4", "list": 3, "number": 4, "english": "equator", "phonetic": "/ɪˈkweɪtər/", "chinese": "n. 赤道", "example": "Countries near the equator are very hot. 靠近赤道的国家非常炎热。", "page": 12}, {"id": "3-5", "list": 3, "number": 5, "english": "inch", "phonetic": "/ɪntʃ/", "chinese": "n. 英寸（约2.54厘米）", "example": "The caterpillar grew one inch longer. 毛毛虫长长了一英寸。", "page": 12}, {"id": "3-6", "list": 3, "number": 6, "english": "spin", "phonetic": "/spɪn/", "chinese": "v. 旋转", "example": "The toy top can spin for a long time. 那个玩具陀螺能旋转很长时间。", "page": 12}, {"id": "3-7", "list": 3, "number": 7, "english": "autumn", "phonetic": "/ˈɔːtəm/", "chinese": "n. 秋天", "example": "Leaves turn yellow and red in autumn. 树叶在秋天变成黄色和红色。", "page": 12}, {"id": "3-8", "list": 3, "number": 8, "english": "beach", "phonetic": "/biːtʃ/", "chinese": "n. 海滩", "example": "We built a sandcastle on the beach. 我们在海滩上建了一个沙堡。", "page": 12}, {"id": "3-9", "list": 3, "number": 9, "english": "cloud", "phonetic": "/klaʊd/", "chinese": "n. 云", "example": "A white cloud is in the blue sky. 一朵白云在蓝天中。", "page": 12}, {"id": "3-10", "list": 3, "number": 10, "english": "cloudy", "phonetic": "/ˈklaʊdi/", "chinese": "adj. 多云的", "example": "It was a cloudy day without sunshine. 那是个没有阳光的多云天。", "page": 12}, {"id": "3-11", "list": 3, "number": 11, "english": "cold", "phonetic": "/koʊld/", "chinese": "adj. 寒冷的", "example": "Please wear a coat in cold weather. 请在寒冷的天气里穿上外套。", "page": 13}, {"id": "3-12", "list": 3, "number": 12, "english": "dark", "phonetic": "/dɑːrk/", "chinese": "adj. 黑暗的", "example": "It gets dark early in the winter. 冬天天黑得早。", "page": 13}, {"id": "3-13", "list": 3, "number": 13, "english": "forest", "phonetic": "/ˈfɔːrɪst/", "chinese": "n. 森林", "example": "Many animals live in the forest. 许多动物住在森林里。", "page": 13}, {"id": "3-14", "list": 3, "number": 14, "english": "green", "phonetic": "/ɡriːn/", "chinese": "adj. 绿色的", "example": "Grass is green. 草是绿色的。", "page": 13}, {"id": "3-15", "list": 3, "number": 15, "english": "hot", "phonetic": "/hɑːt/", "chinese": "adj. 炎热的", "example": "Let’s drink some water on a hot day. 让我们在天热的时候喝点水。", "page": 13}, {"id": "3-16", "list": 3, "number": 16, "english": "mountain", "phonetic": "/ˈmaʊntn/", "chinese": "n. 山", "example": "We climbed to the top of the mountain. 我们爬到了山顶。", "page": 13}, {"id": "3-17", "list": 3, "number": 17, "english": "orange", "phonetic": "/ˈɔːrɪndʒ/", "chinese": "adj. 橙色的", "example": "She has an orange backpack for school. 她有一个橙色的书包上学用。", "page": 13}, {"id": "3-18", "list": 3, "number": 18, "english": "park", "phonetic": "/pɑːrk/", "chinese": "n. 公园", "example": "Children often play in the park. 孩子们经常在公园里玩。", "page": 13}, {"id": "3-19", "list": 3, "number": 19, "english": "coat", "phonetic": "/koʊt/", "chinese": "n. 外套", "example": "He put on his warm coat before going out. 他出门前穿上了暖和的外套。", "page": 13}, {"id": "3-20", "list": 3, "number": 20, "english": "interesting", "phonetic": "/ˈɪntrəstɪŋ/", "chinese": "adj. 有趣的", "example": "This is an interesting book about space. 这是一本关于太空的有趣的书。", "page": 13}, {"id": "3-21", "list": 3, "number": 21, "english": "indent", "phonetic": "/ɪnˈdent/", "chinese": "v. 缩进", "example": "Please indent the first line of your paragraph. 请将你段落的第一行缩进。", "page": 14}, {"id": "3-22", "list": 3, "number": 22, "english": "scarf", "phonetic": "/skɑːrf/", "chinese": "n. 围巾", "example": "She wore a red scarf around her neck. 她脖子上围着一条红围巾。", "page": 14}, {"id": "3-23", "list": 3, "number": 23, "english": "document", "phonetic": "/ˈdɑːkjumənt /", "chinese": "n. 文件", "example": "Please send me the document by email. 请通过电子邮件把文件发给我。", "page": 14}, {"id": "3-24", "list": 3, "number": 24, "english": "fax", "phonetic": "/fæks/", "chinese": "n. 传真", "example": "My father sent a fax from his office. 我父亲从他的办公室发了一份传真。", "page": 14}, {"id": "3-25", "list": 3, "number": 25, "english": "software", "phonetic": "/ˈsɔːftwer/", "chinese": "n. 软件", "example": "We use new software for drawing pictures. 我们使用新软件来画画。", "page": 14}, {"id": "3-26", "list": 3, "number": 26, "english": "monument", "phonetic": "/ˈmɑːnjumənt/", "chinese": "n. 纪念碑", "example": "People visit the war monument to remember. 人们参观战争纪念碑以作纪念。", "page": 14}, {"id": "3-27", "list": 3, "number": 27, "english": "pillow", "phonetic": "/ˈpɪloʊ/", "chinese": "n. 枕头", "example": "My pillow is very soft and comfortable. 我的枕头非常柔软舒适。", "page": 14}, {"id": "3-28", "list": 3, "number": 28, "english": "porch", "phonetic": "/pɔːrtʃ/", "chinese": "n. 门廊", "example": "We sit on the porch in the cool evening. 我们在凉爽的傍晚坐在门廊上。", "page": 14}, {"id": "3-29", "list": 3, "number": 29, "english": "concluding", "phonetic": "/kənˈkluːdɪŋ/", "chinese": "adj. 总结的", "example": "This is the concluding chapter of the story. 这是故事的总结性章节。", "page": 14}, {"id": "3-30", "list": 3, "number": 30, "english": "topic", "phonetic": "/ˈtɑːpɪk/", "chinese": "n. 话题", "example": "Our discussion topic today is “friendship”. 我们今天讨论的话题是“友谊”。", "page": 14}, {"id": "3-31", "list": 3, "number": 31, "english": "support", "phonetic": "/səˈpɔːrt/", "chinese": "v. 支撑；支持", "example": "Strong legs support our body weight. 强壮的腿支撑着我们的体重。", "page": 15}, {"id": "3-32", "list": 3, "number": 32, "english": "relax", "phonetic": "/rɪˈlæks/", "chinese": "v. 放松", "example": "I like to relax by listening to music. 我喜欢通过听音乐来放松。", "page": 15}, {"id": "3-33", "list": 3, "number": 33, "english": "comfortable", "phonetic": "/ˈkʌmftəbl/", "chinese": "adj. 舒适的", "example": "These new shoes are very comfortable. 这双新鞋非常舒适。", "page": 15}, {"id": "3-34", "list": 3, "number": 34, "english": "bother", "phonetic": "/ˈbɑːðər/", "chinese": "v. 打扰", "example": "Please do not bother him while he is working. 请不要在他工作时打扰他。", "page": 15}, {"id": "3-35", "list": 3, "number": 35, "english": "suggest", "phonetic": "/səˈdʒest/", "chinese": "v. 建议；提议；暗示", "example": "I suggest we go to the library after school. 我建议我们放学后去图书馆。", "page": 15}, {"id": "3-36", "list": 3, "number": 36, "english": "various", "phonetic": "/ˈveriəs/", "chinese": "adj. 多种多样的", "example": "We saw various animals at the zoo. 我们在动物园看到了各种各样的动物。", "page": 15}, {"id": "3-37", "list": 3, "number": 37, "english": "argue", "phonetic": "/ˈɑːrɡjuː/", "chinese": "v. 辩论，争论", "example": "They sometimes argue about small things. 他们有时会为小事争论。", "page": 15}, {"id": "3-38", "list": 3, "number": 38, "english": "work out", "phonetic": "/ˈwɜːrkaʊt/", "chinese": "v. 找到（解决方法）", "example": "We need to work out this math problem. 我们需要解出这道数学题。", "page": 15}, {"id": "3-39", "list": 3, "number": 39, "english": "tradition", "phonetic": "/trəˈdɪʃn/", "chinese": "n. 传统", "example": "Making dumplings is a family tradition. 包饺子是一项家庭传统。", "page": 15}, {"id": "3-40", "list": 3, "number": 40, "english": "record", "phonetic": "/ˈrekərd/", "chinese": "n. 记录", "example": "She set a new school record for running. 她创下了新的学校跑步记录。", "page": 15}, {"id": "3-41", "list": 3, "number": 41, "english": "unhealthy", "phonetic": "/ʌnˈhelθi/", "chinese": "adj. 不健康的", "example": "Eating too much candy is unhealthy. 吃太多糖果是不健康的。", "page": 16}, {"id": "3-42", "list": 3, "number": 42, "english": "athlete", "phonetic": "/ˈæθliːt/", "chinese": "n. 运动员", "example": "This young athlete trains every day. 这位年轻的运动员每天训练。", "page": 16}, {"id": "3-43", "list": 3, "number": 43, "english": "competition", "phonetic": "/ˌkɑːmpəˈtɪʃn/", "chinese": "n. 竞争；比赛", "example": "She won first prize in the singing competition. 她在歌唱比赛中赢得了一等奖。", "page": 16}, {"id": "3-44", "list": 3, "number": 44, "english": "event", "phonetic": "/ɪˈvent/", "chinese": "n. 事件；活动", "example": "The school sports event is next Friday. 学校运动会是下周五。", "page": 16}, {"id": "3-45", "list": 3, "number": 45, "english": "immigrant", "phonetic": "/ˈɪmɪɡrənt/", "chinese": "n. 移民", "example": "Her grandfather was an immigrant from Europe. 她的祖父是来自欧洲的移民。", "page": 16}, {"id": "3-46", "list": 3, "number": 46, "english": "champion", "phonetic": "/ˈtʃæmpiən/", "chinese": "n. 冠军；拥护者", "example": "The tennis champion received a gold medal. 网球冠军获得了一枚金牌。", "page": 16}, {"id": "3-47", "list": 3, "number": 47, "english": "contestant", "phonetic": "/kənˈtestənt/", "chinese": "n. 参赛者；竞争者", "example": "Each contestant answered three questions. 每位参赛者回答了三个问题。", "page": 16}, {"id": "3-48", "list": 3, "number": 48, "english": "fighter", "phonetic": "/ˈfaɪtər/", "chinese": "n. 战士；拳击手", "example": "The brave fighter protected his country. 勇敢的战士保卫了他的国家。", "page": 16}, {"id": "3-49", "list": 3, "number": 49, "english": "type", "phonetic": "/taɪp/", "chinese": "n. 类型；种类", "example": "What type of fruit do you like best? 你最喜欢哪种类型的水果？", "page": 16}, {"id": "4-1", "list": 4, "number": 1, "english": "rain", "phonetic": "/reɪn/", "chinese": "n. 雨", "example": "The rain is falling heavily. 雨下得很大。", "page": 17}, {"id": "4-2", "list": 4, "number": 2, "english": "rainy", "phonetic": "/ˈreɪni/", "chinese": "adj. 多雨的", "example": "It's a rainy day today. 今天是个多雨的日子。", "page": 17}, {"id": "4-3", "list": 4, "number": 3, "english": "red", "phonetic": "/red/", "chinese": "adj. 红色的", "example": "She wears a red dress. 她穿着一件红色的连衣裙。", "page": 17}, {"id": "4-4", "list": 4, "number": 4, "english": "river", "phonetic": "/ˈrɪvər/", "chinese": "n. 河流", "example": "The river flows to the sea. 这条河流向大海。", "page": 17}, {"id": "4-5", "list": 4, "number": 5, "english": "rock", "phonetic": "/rɑːk/", "chinese": "n. 岩石", "example": "Children climb on the big rock. 孩子们爬到大岩石上。", "page": 17}, {"id": "4-6", "list": 4, "number": 6, "english": "sand", "phonetic": "/sænd/", "chinese": "n. 沙子", "example": "The sand is warm under my feet. 沙子在我脚下很温暖。", "page": 17}, {"id": "4-7", "list": 4, "number": 7, "english": "sea", "phonetic": "/siː/", "chinese": "n. 海洋", "example": "We swim in the sea every summer. 我们每年夏天都在海里游泳。", "page": 17}, {"id": "4-8", "list": 4, "number": 8, "english": "sky", "phonetic": "/skaɪ/", "chinese": "n. 天空", "example": "The sky is clear and blue. 天空晴朗湛蓝。", "page": 17}, {"id": "4-9", "list": 4, "number": 9, "english": "snowy", "phonetic": "/ˈsnoʊi/", "chinese": "adj. 下雪的", "example": "It's a snowy winter day. 这是一个下雪的冬日。", "page": 17}, {"id": "4-10", "list": 4, "number": 10, "english": "spring", "phonetic": "/sprɪŋ/", "chinese": "n. 春天", "example": "Flowers bloom in spring. 春天花朵盛开。", "page": 17}, {"id": "4-11", "list": 4, "number": 11, "english": "storm", "phonetic": "/stɔːrm/", "chinese": "n. 风暴", "example": "The storm caused power outages. 风暴导致停电。", "page": 18}, {"id": "4-12", "list": 4, "number": 12, "english": "stormy", "phonetic": "/ˈstɔːrmi/", "chinese": "adj. 有暴风雨的", "example": "We had a stormy night. 我们度过了一个暴风雨的夜晚。", "page": 18}, {"id": "4-13", "list": 4, "number": 13, "english": "summer", "phonetic": "/ˈsʌmər/", "chinese": "n. 夏天", "example": "Summer is my favorite season. 夏天是我最喜欢的季节。", "page": 18}, {"id": "4-14", "list": 4, "number": 14, "english": "sunny", "phonetic": "/ˈsʌni/", "chinese": "adj. 阳光明媚的", "example": "It's a sunny day for a picnic. 这是一个适合野餐的阳光明媚的日子。", "page": 18}, {"id": "4-15", "list": 4, "number": 15, "english": "temperature", "phonetic": "/ˈtemprətʃər/", "chinese": "n. 温度", "example": "The temperature is rising today. 今天温度在上升。", "page": 18}, {"id": "4-16", "list": 4, "number": 16, "english": "weather", "phonetic": "/ˈweðər/", "chinese": "n. 天气", "example": "The weather forecast predicts rain. 天气预报预测有雨。", "page": 18}, {"id": "4-17", "list": 4, "number": 17, "english": "wet", "phonetic": "/wet/", "chinese": "adj. 潮湿的", "example": "The ground is wet after the rain. 雨后地面是湿的。", "page": 18}, {"id": "4-18", "list": 4, "number": 18, "english": "windy", "phonetic": "/ˈwɪndi/", "chinese": "adj. 有风的", "example": "It's too windy to fly a kite. 风太大不能放风筝。", "page": 18}, {"id": "4-19", "list": 4, "number": 19, "english": "winter", "phonetic": "/ˈwɪntər/", "chinese": "n. 冬天", "example": "Winter brings snow and cold. 冬天带来雪和寒冷。", "page": 18}, {"id": "4-20", "list": 4, "number": 20, "english": "warm", "phonetic": "/wɔ: rm/", "chinese": "adj. 温暖的", "example": "The sun feels warm on my skin. 阳光照在我的皮肤上很温暖。", "page": 18}, {"id": "4-21", "list": 4, "number": 21, "english": "order", "phonetic": "/ˈɔ: rdər/", "chinese": "n. 顺序", "example": "Please line up in order. 请按顺序排队。", "page": 19}, {"id": "4-22", "list": 4, "number": 22, "english": "idea", "phonetic": "/aɪˈdiːə/", "chinese": "n. 想法", "example": "She has a great idea for the project. 她对项目有一个好主意。", "page": 19}, {"id": "4-23", "list": 4, "number": 23, "english": "elevator", "phonetic": "/ˈelɪveɪtər/", "chinese": "n. 电梯", "example": "We take the elevator to the 10th floor. 10 我们乘电梯到 楼。", "page": 19}, {"id": "4-24", "list": 4, "number": 24, "english": "observation deck", "phonetic": "/ˌɑːbzərˈveɪʃən dek/", "chinese": "n. 观景台", "example": "The observation deck offers a great view. 观景台提供了很好的视野。", "page": 19}, {"id": "4-25", "list": 4, "number": 25, "english": "floor", "phonetic": "/flɔːr/", "chinese": "n. 楼层", "example": "My office is on the fifth floor. 我的办公室在五楼。", "page": 19}, {"id": "4-26", "list": 4, "number": 26, "english": "coastline", "phonetic": "/ˈkoʊstlaɪn/", "chinese": "n. 海岸线", "example": "The coastline is beautiful at sunset. 日落时海岸线很美。", "page": 19}, {"id": "4-27", "list": 4, "number": 27, "english": "close to", "phonetic": "/kloʊs tuː/", "chinese": "phr. 靠近", "example": "My house is close to the school. 我的房子靠近学校。", "page": 19}, {"id": "4-28", "list": 4, "number": 28, "english": "landmark", "phonetic": "/ˈlændmɑːrk/", "chinese": "n. 地标", "example": "The Eiffel Tower is a famous landmark. 埃菲尔铁塔是著名的地标。", "page": 19}, {"id": "4-29", "list": 4, "number": 29, "english": "slippery", "phonetic": "/ˈslɪpəri/", "chinese": "adj. 滑的", "example": "The floor is slippery when wet. 地板湿的时候很滑。", "page": 19}, {"id": "4-30", "list": 4, "number": 30, "english": "accident", "phonetic": "/ˈæksɪdənt/", "chinese": "n. 事故", "example": "He had a car accident yesterday. 他昨天发生了车祸。", "page": 19}, {"id": "4-31", "list": 4, "number": 31, "english": "danger", "phonetic": "/ˈdeɪndʒər/", "chinese": "n. 危险", "example": "Swimming here is full of danger. 在这里游泳充满危险。", "page": 20}, {"id": "4-32", "list": 4, "number": 32, "english": "damage", "phonetic": "/ˈdæmɪdʒ/", "chinese": "v. 损坏", "example": "The storm damaged many houses. 风暴损坏了许多房屋。", "page": 20}, {"id": "4-33", "list": 4, "number": 33, "english": "compete", "phonetic": "/kəmˈpiːt/", "chinese": "v. 竞争", "example": "Athletes compete in the Olympics. 运动员在奥运会上竞争。", "page": 20}, {"id": "4-34", "list": 4, "number": 34, "english": "extremely", "phonetic": "/ɪkˈstriːmli/", "chinese": "adv. 非常地", "example": "It's extremely hot today. 今天非常热。", "page": 20}, {"id": "4-35", "list": 4, "number": 35, "english": "fan", "phonetic": "/fæn/", "chinese": "n. 狂热爱好者；粉丝", "example": "She is a big fan of that singer. 她是那位歌手的忠实粉丝。", "page": 20}, {"id": "4-36", "list": 4, "number": 36, "english": "dish", "phonetic": "/dɪʃ/", "chinese": "n. 餐具，菜肴", "example": "This dish is very delicious. 这道菜非常美味。", "page": 20}, {"id": "4-37", "list": 4, "number": 37, "english": "plant", "phonetic": "/plænt/", "chinese": "n. 植物", "example": "I water my plants every day. 我每天给植物浇水。", "page": 20}, {"id": "4-38", "list": 4, "number": 38, "english": "contain", "phonetic": "/kənˈteɪn/", "chinese": "v. 包含，含有", "example": "This box contains old photos. 这个盒子装着旧照片。", "page": 20}, {"id": "4-39", "list": 4, "number": 39, "english": "health", "phonetic": "/helθ/", "chinese": "n. 健康", "example": "Good health is important for happiness. 健康对幸福很重要。", "page": 20}, {"id": "4-40", "list": 4, "number": 40, "english": "breathe", "phonetic": "/briːð/", "chinese": "v. 呼吸", "example": "It's hard to breathe at high altitudes. 在高海拔地区呼吸困难。", "page": 20}, {"id": "4-41", "list": 4, "number": 41, "english": "fit", "phonetic": "/fɪt/", "chinese": "adj. 健康的", "example": "He exercises daily to stay fit. 他每天锻炼以保持健康。", "page": 21}, {"id": "4-42", "list": 4, "number": 42, "english": "hungry", "phonetic": "/'hʌŋgri/", "chinese": "adj. 饥饿的", "example": "I'm hungry after the long walk. 长途步行后我饿了。", "page": 21}, {"id": "4-43", "list": 4, "number": 43, "english": "painful", "phonetic": "/ˈpeɪnfl/", "chinese": "adj. 痛苦的，疼痛的", "example": "The injury is very painful. 这个伤很痛。", "page": 21}, {"id": "4-44", "list": 4, "number": 44, "english": "experience", "phonetic": "/ɪkˈspɪriəns/", "chinese": "n. v. 经验；经历 体验", "example": "Traveling is a great experience. 旅行是一种很好的体验。", "page": 21}, {"id": "4-45", "list": 4, "number": 45, "english": "world", "phonetic": "/wɜːrld/", "chinese": "n. 世界；领域", "example": "She wants to travel around the world. 她想环游世界。", "page": 21}, {"id": "4-46", "list": 4, "number": 46, "english": "measure", "phonetic": "/ˈmeʒər/", "chinese": "v. n. 测量；衡量 措施；度量", "example": "We measure the room's dimensions. 我们测量房间的尺寸。", "page": 21}, {"id": "4-47", "list": 4, "number": 47, "english": "barely", "phonetic": "/ˈberli/", "chinese": "adv. 几乎不；仅仅", "example": "I barely made it to the meeting. 我勉强赶上了会议。", "page": 21}, {"id": "4-48", "list": 4, "number": 48, "english": "pepper", "phonetic": "/ˈpepər/", "chinese": "n. 胡椒；辣椒", "example": "Add some pepper to the soup. 往汤里加些胡椒。", "page": 21}, {"id": "4-49", "list": 4, "number": 49, "english": "unit", "phonetic": "/ˈjuːnɪt/", "chinese": "n. 单元；单位", "example": "We study Unit 5 this week. 我们这周学习第五单元。", "page": 21}, {"id": "4-50", "list": 4, "number": 50, "english": "million", "phonetic": "/ˈmɪljən/", "chinese": "num. 百万", "example": "The company earned millions last year. 公司去年赚了数百万。", "page": 21}, {"id": "5-1", "list": 5, "number": 1, "english": "north", "phonetic": "/nɔːrθ/", "chinese": "n. 北方", "example": "The wind blows from the north. 风从北方吹来。", "page": 22}, {"id": "5-2", "list": 5, "number": 2, "english": "south", "phonetic": "/saʊθ/", "chinese": "n. 南方", "example": "They traveled to the south. 他们去了南方旅行。", "page": 22}, {"id": "5-3", "list": 5, "number": 3, "english": "empty", "phonetic": "/ˈempti/", "chinese": "adj. 空的", "example": "The bottle is empty. 瓶子是空的。", "page": 22}, {"id": "5-4", "list": 5, "number": 4, "english": "earth", "phonetic": "/ɜːrθ/", "chinese": "n. 地球", "example": "The Earth orbits the sun. 地球围绕太阳旋转。", "page": 22}, {"id": "5-5", "list": 5, "number": 5, "english": "usually", "phonetic": "/ˈjuːʒuəli/", "chinese": "adv. 通常", "example": "I usually wake up at 7 AM. 7 我通常早上 点起床。", "page": 22}, {"id": "5-6", "list": 5, "number": 6, "english": "full", "phonetic": "/fʊl/", "chinese": "adj. 满的", "example": "The theater was full. 剧院坐满了人。", "page": 22}, {"id": "5-7", "list": 5, "number": 7, "english": "high", "phonetic": "/haɪ/", "chinese": "adj. 高的", "example": "The mountain is very high. 这座山非常高。", "page": 22}, {"id": "5-8", "list": 5, "number": 8, "english": "inside", "phonetic": "/ɪnˈsaɪd/", "chinese": "adv./prep. 在内部", "example": "Please wait inside. 请在室内等候。", "page": 22}, {"id": "5-9", "list": 5, "number": 9, "english": "around", "phonetic": "/əˈraʊnd/", "chinese": "prep. 大约；围绕", "example": "We walked around the park. 我们在公园周围散步。", "page": 22}, {"id": "5-10", "list": 5, "number": 10, "english": "through", "phonetic": "/θruː/", "chinese": "prep. 穿过", "example": "We drove through the tunnel. 我们开车穿过隧道。", "page": 22}, {"id": "5-11", "list": 5, "number": 11, "english": "among", "phonetic": "/əˈmʌŋ/", "chinese": "prep. 在...之中", "example": "She was among the winners. 她是获奖者之一。", "page": 23}, {"id": "5-12", "list": 5, "number": 12, "english": "several", "phonetic": "/ˈsevrəl/", "chinese": "adj. 几个", "example": "I have several books. 我有几本书。", "page": 23}, {"id": "5-13", "list": 5, "number": 13, "english": "certain", "phonetic": "/ˈsɜːrtn/", "chinese": "adj. 某个；确定的", "example": "I'm certain about my decision. 我对我的决定很确定。", "page": 23}, {"id": "5-14", "list": 5, "number": 14, "english": "especially", "phonetic": "/ɪˈspeʃəli/", "chinese": "adv. 尤其", "example": "I love fruits, especially apples. 我喜欢水果，尤其是苹果。", "page": 23}, {"id": "5-15", "list": 5, "number": 15, "english": "perhaps", "phonetic": "/pərˈhæps/", "chinese": "adv. 或许", "example": "Perhaps we should wait. 或许我们应该等等。", "page": 23}, {"id": "5-16", "list": 5, "number": 16, "english": "rather", "phonetic": "/ˈræðər/", "chinese": "adv. 相当", "example": "It's rather cold today. 今天相当冷。", "page": 23}, {"id": "5-17", "list": 5, "number": 17, "english": "though", "phonetic": "/ðoʊ/", "chinese": "adv./conj. 虽然", "example": "Though it was raining, we went out. 虽然下雨了，我们还是出去了。", "page": 23}, {"id": "5-18", "list": 5, "number": 18, "english": "unless", "phonetic": "/ənˈles/", "chinese": "conj. 除非", "example": "I won't go unless you come. 除非你来，否则我不会去。", "page": 23}, {"id": "5-19", "list": 5, "number": 19, "english": "whether", "phonetic": "/ˈweðər/", "chinese": "conj. 是否", "example": "I don't know whether to go. 我不知道是否要去。", "page": 23}, {"id": "5-20", "list": 5, "number": 20, "english": "contest", "phonetic": "/ˈk : ntest/ ɑ", "chinese": "n. 比赛", "example": "She won the singing contest. 她赢得了歌唱比赛。", "page": 23}, {"id": "5-21", "list": 5, "number": 21, "english": "title", "phonetic": "/ˈtaɪtl/", "chinese": "n. 标题", "example": "What's the title of the book? 这本书的标题是什么？", "page": 24}, {"id": "5-22", "list": 5, "number": 22, "english": "example", "phonetic": "/ɪɡˈzæmpl/", "chinese": "n. 例子", "example": "Can you give me an example? 你能给我举个例子吗？", "page": 24}, {"id": "5-23", "list": 5, "number": 23, "english": "describe", "phonetic": "/dɪˈskraɪb/", "chinese": "v. 描述", "example": "Can you describe the suspect? 你能描述一下嫌疑人吗？", "page": 24}, {"id": "5-24", "list": 5, "number": 24, "english": "spectator", "phonetic": "/ˈspekteɪtər/", "chinese": "n. 观众", "example": "The spectators cheered loudly. 观众们大声欢呼。", "page": 24}, {"id": "5-25", "list": 5, "number": 25, "english": "ceramics", "phonetic": "/səˈræmɪks/", "chinese": "n. 陶瓷制品", "example": "She makes beautiful ceramics. 她制作漂亮的陶瓷制品。", "page": 24}, {"id": "5-26", "list": 5, "number": 26, "english": "calorie", "phonetic": "/ˈkæləri/", "chinese": "n. 卡路里", "example": "This food has 200 calories. 这种食物含有200卡路里。", "page": 24}, {"id": "5-27", "list": 5, "number": 27, "english": "check", "phonetic": "/tʃek/", "chinese": "v. 检查", "example": "Please check your answers. 请检查你的答案。", "page": 24}, {"id": "5-28", "list": 5, "number": 28, "english": "connect", "phonetic": "/kəˈnekt/", "chinese": "v. 连接", "example": "Connect the cable to the computer. 将电缆连接到计算机。", "page": 24}, {"id": "5-29", "list": 5, "number": 29, "english": "explain", "phonetic": "/ɪkˈspleɪn/", "chinese": "v. 解释", "example": "Can you explain this rule? 你能解释一下这个规则吗？", "page": 24}, {"id": "5-30", "list": 5, "number": 30, "english": "summary", "phonetic": "/ˈsʌməri/", "chinese": "n. 总结；摘要", "example": "Write a summary of the article. 写一篇文章的摘要。", "page": 24}, {"id": "5-31", "list": 5, "number": 31, "english": "organized", "phonetic": "/ˈɔːrɡənaɪzd/", "chinese": "adj. 有条理的", "example": "She is very organized. 她非常有条理。", "page": 25}, {"id": "5-32", "list": 5, "number": 32, "english": "patient", "phonetic": "/ˈpeɪʃnt/", "chinese": "adj. 耐心的", "example": "Teachers need to be patient. 老师需要有耐心。", "page": 25}, {"id": "5-33", "list": 5, "number": 33, "english": "due date", "phonetic": "/duː deɪt/", "chinese": "n. 截止日期", "example": "The due date is next Friday. 截止日期是下周五。", "page": 25}, {"id": "5-34", "list": 5, "number": 34, "english": "recipe", "phonetic": "/ˈresəpi/", "chinese": "n. 食谱", "example": "I followed the recipe exactly. 我完全按照食谱做的。", "page": 25}, {"id": "5-35", "list": 5, "number": 35, "english": "sprinkle", "phonetic": "/ˈsprɪŋkl/", "chinese": "v. 撒", "example": "Sprinkle some salt on the food. 在食物上撒些盐。", "page": 25}, {"id": "5-36", "list": 5, "number": 36, "english": "lucky", "phonetic": "/ˈlʌki/", "chinese": "adj. 幸运的", "example": "You're lucky to have such friends. 你有这样的朋友很幸运。", "page": 25}, {"id": "5-37", "list": 5, "number": 37, "english": "history", "phonetic": "/ˈhɪstri/", "chinese": "n. 历史", "example": "I love studying ancient history. 我喜欢研究古代历史。", "page": 25}, {"id": "5-38", "list": 5, "number": 38, "english": "amazing", "phonetic": "/əˈmeɪzɪŋ/", "chinese": "adj. 令人惊异的", "example": "The view was amazing. 景色令人惊叹。", "page": 25}, {"id": "5-39", "list": 5, "number": 39, "english": "decide", "phonetic": "/dɪˈsaɪd/", "chinese": "v. 决定", "example": "We need to decide quickly. 我们需要快速决定。", "page": 25}, {"id": "5-40", "list": 5, "number": 40, "english": "get married", "phonetic": "/ɡet ˈmærid/", "chinese": "结婚", "example": "They plan to get married next year. 他们计划明年结婚。", "page": 25}, {"id": "5-41", "list": 5, "number": 41, "english": "career", "phonetic": "/kəˈrɪr/", "chinese": "n. 职业，生涯", "example": "She has a successful career. 她有一个成功的职业生涯。", "page": 26}, {"id": "5-42", "list": 5, "number": 42, "english": "hurt", "phonetic": "/hɜːrt/", "chinese": "v. 伤害", "example": "Be careful not to hurt yourself. 小心不要伤到自己。", "page": 26}, {"id": "5-43", "list": 5, "number": 43, "english": "moment", "phonetic": "/ˈmoʊmənt/", "chinese": "n. 片刻，瞬间", "example": "Wait a moment, please. 请稍等片刻。", "page": 26}, {"id": "5-44", "list": 5, "number": 44, "english": "university", "phonetic": "/ˌjuːnɪˈvɜːrsəti/", "chinese": "n. 大学", "example": "She studies at the university. 她在大学学习。", "page": 26}, {"id": "5-45", "list": 5, "number": 45, "english": "Egypt", "phonetic": "/ˈiːdʒɪpt/", "chinese": "n. 埃及", "example": "Egypt has ancient pyramids. 埃及有古老的金字塔。", "page": 26}, {"id": "5-46", "list": 5, "number": 46, "english": "bury", "phonetic": "/ˈberi/", "chinese": "v. 埋葬；埋藏", "example": "They bury treasures in the sand. 他们把宝藏埋在沙子里。", "page": 26}, {"id": "5-47", "list": 5, "number": 47, "english": "excavation", "phonetic": "/ˌekskəˈveɪʃən/", "chinese": "n. 挖掘，发掘", "example": "The excavation revealed ancient artifacts. 挖掘揭示了古代文物。", "page": 26}, {"id": "5-48", "list": 5, "number": 48, "english": "push", "phonetic": "/pʊʃ/", "chinese": "v. 推；推动", "example": "Push the door to open it. 推门打开它。", "page": 26}, {"id": "5-49", "list": 5, "number": 49, "english": "actually", "phonetic": "/ˈæktʃuəli/", "chinese": "adv. 实际上；事实上", "example": "Actually, I don't agree. 实际上，我不同意。", "page": 26}, {"id": "6-1", "list": 6, "number": 1, "english": "diamond", "phonetic": "/ˈdaɪəmənd/", "chinese": "n. 菱形；钻石", "example": "She received a diamond ring. 她收到了一枚钻石戒指。", "page": 27}, {"id": "6-2", "list": 6, "number": 2, "english": "festival", "phonetic": "/ˈfestɪvl/", "chinese": "n. 节日", "example": "We celebrate the Spring Festival. 我们庆祝春节。", "page": 27}, {"id": "6-3", "list": 6, "number": 3, "english": "traditional", "phonetic": "/trəˈdɪʃənl/", "chinese": "adj. 传统的", "example": "They wear traditional clothes. 他们穿着传统服装。", "page": 27}, {"id": "6-4", "list": 6, "number": 4, "english": "lifestyle", "phonetic": "/ˈlaɪfstaɪl/", "chinese": "n. 生活方式", "example": "He has a healthy lifestyle. 他有着健康的生活方式。", "page": 27}, {"id": "6-5", "list": 6, "number": 5, "english": "teenager", "phonetic": "/ˈtiːnˌeɪdʒər/", "chinese": "n. 青少年（13-19岁）", "example": "Teenagers like social media. 青少年喜欢社交媒体。", "page": 27}, {"id": "6-6", "list": 6, "number": 6, "english": "busy", "phonetic": "/ˈbɪzi/", "chinese": "adj. 忙碌的", "example": "I am busy with work. 我工作很忙。", "page": 27}, {"id": "6-7", "list": 6, "number": 7, "english": "café", "phonetic": "/kæˈfeɪ/", "chinese": "n. 咖啡馆", "example": "We met at the café. 我们在咖啡馆见面。", "page": 27}, {"id": "6-8", "list": 6, "number": 8, "english": "chat online", "phonetic": "/tʃæt ɒnˈlaɪn/", "chinese": "v. （和朋友）在线聊天", "example": "I chat online with friends. 我和朋友在线聊天。", "page": 27}, {"id": "6-9", "list": 6, "number": 9, "english": "eat out", "phonetic": "/iːt aʊt/", "chinese": "v. 外出就餐", "example": "We eat out on weekends. 我们周末外出就餐。", "page": 27}, {"id": "6-10", "list": 6, "number": 10, "english": "exercise", "phonetic": "/ˈeksəsaɪz/", "chinese": "v. 锻炼", "example": "She exercises every morning. 她每天早上锻炼。", "page": 27}, {"id": "6-11", "list": 6, "number": 11, "english": "go online", "phonetic": "/ɡoʊ ɒnˈlaɪn/", "chinese": "v. 上网", "example": "I go online to study. 我上网学习。", "page": 28}, {"id": "6-12", "list": 6, "number": 12, "english": "cinema", "phonetic": "/ˈsɪnəmə/", "chinese": "n. 电影院", "example": "We went to the cinema. 我们去了电影院。", "page": 28}, {"id": "6-13", "list": 6, "number": 13, "english": "gym", "phonetic": "/dʒɪm/", "chinese": "n. 健身房", "example": "He goes to the gym daily. 他每天去健身房。", "page": 28}, {"id": "6-14", "list": 6, "number": 14, "english": "breakfast", "phonetic": "/ˈbrekfəst/", "chinese": "n. 早餐", "example": "I eat breakfast at 7 AM. 我早上7点吃早餐。", "page": 28}, {"id": "6-15", "list": 6, "number": 15, "english": "dinner", "phonetic": "/ˈdɪnər/", "chinese": "n. 晚餐", "example": "We have dinner together. 我们一起吃晚餐。", "page": 28}, {"id": "6-16", "list": 6, "number": 16, "english": "lunch", "phonetic": "/lʌntʃ/", "chinese": "n. 午餐", "example": "She brings lunch to work. 她带午餐去上班。", "page": 28}, {"id": "6-17", "list": 6, "number": 17, "english": "parents", "phonetic": "/ˈperənts/", "chinese": "n. 父母", "example": "My parents live nearby. 我的父母住在附近。", "page": 28}, {"id": "6-18", "list": 6, "number": 18, "english": "football", "phonetic": "/ˈfʊtbɔ: l/", "chinese": "n. 足球", "example": "He plays football well. 他足球踢得很好。", "page": 28}, {"id": "6-19", "list": 6, "number": 19, "english": "video games", "phonetic": "/ˈvɪdioʊ eɪmz/ ɡ", "chinese": "n. 电子游戏", "example": "Kids love video games. 孩子们喜欢电子游戏。", "page": 28}, {"id": "6-20", "list": 6, "number": 20, "english": "text", "phonetic": "/tekst/", "chinese": "v. 发短信", "example": "I text my friend daily. 我每天给朋友发短信。", "page": 28}, {"id": "6-21", "list": 6, "number": 21, "english": "fair", "phonetic": "/fer/", "chinese": "adj. 公平的", "example": "The game was fair. 这场比赛是公平的。", "page": 29}, {"id": "6-22", "list": 6, "number": 22, "english": "encouraging", "phonetic": "/ɪnˈkɜːrɪdʒɪŋ/", "chinese": "adj. 鼓励的", "example": "His words were encouraging. 他的话很鼓舞人心。", "page": 29}, {"id": "6-23", "list": 6, "number": 23, "english": "quality", "phonetic": "/ˈkwɑːləti/", "chinese": "n. 品质；质量", "example": "This product has good quality. 这个产品质量很好。", "page": 29}, {"id": "6-24", "list": 6, "number": 24, "english": "chili", "phonetic": "/ˈtʃɪli/", "chinese": "n. 辣椒", "example": "I add chili to my food. 我在食物里加辣椒。", "page": 29}, {"id": "6-25", "list": 6, "number": 25, "english": "careful", "phonetic": "/ˈkerfl/", "chinese": "adj. 仔细的；小心的", "example": "Be careful when driving. 开车时要小心。", "page": 29}, {"id": "6-26", "list": 6, "number": 26, "english": "celebrate", "phonetic": "/ˈselɪbreɪt/", "chinese": "v. 庆祝", "example": "We celebrate birthdays. 我们庆祝生日。", "page": 29}, {"id": "6-27", "list": 6, "number": 27, "english": "mudslide", "phonetic": "/ˈmʌdslaɪd/", "chinese": "n. 泥石流", "example": "The mudslide destroyed houses. 泥石流摧毁了房屋。", "page": 29}, {"id": "6-28", "list": 6, "number": 28, "english": "reserve", "phonetic": "/rɪˈzɜːrv/", "chinese": "n. 保护区", "example": "This is a nature reserve. 这是一个自然保护区。", "page": 29}, {"id": "6-29", "list": 6, "number": 29, "english": "conservationist", "phonetic": "/ˌkɑːnsərˈveɪʃənɪst/", "chinese": "n. 环境保护主义者", "example": "She is a conservationist. 她是一名环境保护主义者。", "page": 29}, {"id": "6-30", "list": 6, "number": 30, "english": "veterinary", "phonetic": "/ˈvetərɪneri/", "chinese": "adj. 兽医的", "example": "He works at a veterinary clinic. 他在兽医诊所工作。", "page": 29}, {"id": "6-31", "list": 6, "number": 31, "english": "portable", "phonetic": "/ˈpɔːrtəbl/", "chinese": "adj. 便携的", "example": "This is a portable device. 这是一个便携设备。", "page": 30}, {"id": "6-32", "list": 6, "number": 32, "english": "liver", "phonetic": "/ˈlɪvər/", "chinese": "n. 肝脏", "example": "The liver is important. 肝脏很重要。", "page": 30}, {"id": "6-33", "list": 6, "number": 33, "english": "present", "phonetic": "/ˈpreznt/", "chinese": "n./adj. 现在（的）", "example": "Live in the present moment. 活在当下。", "page": 30}, {"id": "6-34", "list": 6, "number": 34, "english": "negative", "phonetic": "/ˈneɡətɪv/", "chinese": "adj. 否定的；负面的", "example": "Avoid negative thoughts. 避免负面想法。", "page": 30}, {"id": "6-35", "list": 6, "number": 35, "english": "action", "phonetic": "/ˈækʃn/", "chinese": "n. 动作", "example": "Actions speak louder than words. 行动胜于言语。", "page": 30}, {"id": "6-36", "list": 6, "number": 36, "english": "spend", "phonetic": "/spend/", "chinese": "v. 花费", "example": "I spend time reading. 我花时间阅读。", "page": 30}, {"id": "6-37", "list": 6, "number": 37, "english": "free", "phonetic": "/friː/", "chinese": "adj. 免费的", "example": "This app is free. 这个应用是免费的。", "page": 30}, {"id": "6-38", "list": 6, "number": 38, "english": "cost", "phonetic": "/kɒst/", "chinese": "v. 花费", "example": "How much does it cost? 这个多少钱？", "page": 30}, {"id": "6-39", "list": 6, "number": 39, "english": "pay", "phonetic": "/peɪ/", "chinese": "v. 支付", "example": "I pay for my groceries. 我支付我的食品杂货。", "page": 30}, {"id": "6-40", "list": 6, "number": 40, "english": "project", "phonetic": "/ˈprɒdʒekt/", "chinese": "n. 项目", "example": "We completed the project. 我们完成了这个项目。", "page": 30}, {"id": "6-41", "list": 6, "number": 41, "english": "interview", "phonetic": "/ˈɪntəvjuː/", "chinese": "n. 面试；采访", "example": "She has a job interview. 她有一个工作面试。", "page": 31}, {"id": "6-42", "list": 6, "number": 42, "english": "photograph", "phonetic": "/ˈfəʊtəɡrɑːf/", "chinese": "n. 照片", "example": "I took a photograph. 我拍了一张照片。", "page": 31}, {"id": "6-43", "list": 6, "number": 43, "english": "curious", "phonetic": "/ˈkjʊəriəs/", "chinese": "adj. 好奇的；奇特的", "example": "Children are naturally curious. 孩子们天生好奇。", "page": 31}, {"id": "6-44", "list": 6, "number": 44, "english": "image", "phonetic": "/ˈɪmɪdʒ/", "chinese": "n. 图像；印象", "example": "This image is clear. 这张图像很清晰。", "page": 31}, {"id": "6-45", "list": 6, "number": 45, "english": "candle", "phonetic": "/ˈkændl/", "chinese": "n. 蜡烛", "example": "She lit a candle. 她点燃了一支蜡烛。", "page": 31}, {"id": "6-46", "list": 6, "number": 46, "english": "and so on", "phonetic": "/ənd səʊ ɒn/", "chinese": "phr. 等等；诸如此类", "example": "I like apples, oranges, and so on. 我喜欢苹果、橘子等等。", "page": 31}, {"id": "6-47", "list": 6, "number": 47, "english": "enough", "phonetic": "/ɪˈnʌf/", "chinese": "adj. 足够的 adv. 足够地", "example": "We have enough food. 我们有足够的食物。", "page": 31}, {"id": "6-48", "list": 6, "number": 48, "english": "magazine", "phonetic": "/ˈmæɡəziːn/", "chinese": "n. 杂志；弹药库", "example": "I read a fashion magazine. 我读一本时尚杂志。", "page": 31}, {"id": "6-49", "list": 6, "number": 49, "english": "passionate", "phonetic": "/ˈpæʃənət/", "chinese": "adj. 热情的；热烈的", "example": "He is passionate about music. 他对音乐充满热情。", "page": 31}, {"id": "7-1", "list": 7, "number": 1, "english": "form", "phonetic": "/fɔːrm/", "chinese": "n. 形式", "example": "Ice is a solid form of water. 冰是水的固体形式。", "page": 32}, {"id": "7-2", "list": 7, "number": 2, "english": "remote", "phonetic": "/rɪˈmoʊt/", "chinese": "adj. 偏远的", "example": "They live in a remote mountain town. 他们住在一个偏远的山城。", "page": 32}, {"id": "7-3", "list": 7, "number": 3, "english": "stamp", "phonetic": "/stæmp/", "chinese": "n. 邮票", "example": "I need a stamp to send this letter. 我需要一张邮票来寄这封信。", "page": 32}, {"id": "7-4", "list": 7, "number": 4, "english": "biotechnologist", "phonetic": "/ˌbaɪoʊtekˈnɑːlədʒɪst/", "chinese": "n. 生物技术学家", "example": "The biotechnologist works in a lab. 这位生物技术学家在实验室工作。", "page": 32}, {"id": "7-5", "list": 7, "number": 5, "english": "entrepreneur", "phonetic": "/ˌɑːntrəprəˈnɜːr/", "chinese": "n. 企业家", "example": "She is a successful young entrepreneur. 她是一位成功的年轻企业家。", "page": 32}, {"id": "7-6", "list": 7, "number": 6, "english": "routine", "phonetic": "/ruːˈtiːn/", "chinese": "n. 常规", "example": "My morning routine includes exercise. 我的早晨常规包括锻炼。", "page": 32}, {"id": "7-7", "list": 7, "number": 7, "english": "stressful", "phonetic": "/ˈstresfl/", "chinese": "adj. 有压力的", "example": "Exams can be a stressful time. 考试可能是一段有压力的时间。", "page": 32}, {"id": "7-8", "list": 7, "number": 8, "english": "temporary", "phonetic": "/ˈtempəreri/", "chinese": "adj. 临时的", "example": "This is just a temporary solution. 这只是一个临时的解决方案。", "page": 32}, {"id": "7-9", "list": 7, "number": 9, "english": "hurry", "phonetic": "/ˈhɜːri/", "chinese": "v. 匆忙", "example": "We must hurry to catch the bus. 我们必须赶去坐公交车。", "page": 32}, {"id": "7-10", "list": 7, "number": 10, "english": "assignment", "phonetic": "/əˈsaɪnmənt/", "chinese": "n. 作业", "example": "I have a math assignment to finish. 我有一份数学作业要完成。", "page": 32}, {"id": "7-11", "list": 7, "number": 11, "english": "calendar", "phonetic": "/ˈkælɪndər/", "chinese": "n. 日历", "example": "Mark the date on your calendar. 在你的日历上标记这个日期。", "page": 33}, {"id": "7-12", "list": 7, "number": 12, "english": "destination", "phonetic": "/ˌdestɪˈneɪʃn/", "chinese": "n. 目的地", "example": "Our destination is the beach hotel. 我们的目的地是海滩酒店。", "page": 33}, {"id": "7-13", "list": 7, "number": 13, "english": "flow", "phonetic": "/floʊ/", "chinese": "v. 流动", "example": "Rivers flow towards the ocean. 河流向海洋流动。", "page": 33}, {"id": "7-14", "list": 7, "number": 14, "english": "national", "phonetic": "/ˈnæʃnəl/", "chinese": "adj. 国家的", "example": "Today is a national holiday. 今天是一个国家假日。", "page": 33}, {"id": "7-15", "list": 7, "number": 15, "english": "certainly", "phonetic": "/ˈsɜːrtnli/", "chinese": "adv. 当然；肯定", "example": "I will certainly help you later. 我等会儿肯定会帮你。", "page": 33}, {"id": "7-16", "list": 7, "number": 16, "english": "film", "phonetic": "/fɪlm/", "chinese": "n. 电影", "example": "We watched an exciting film. 我们看了一部激动人心的电影。", "page": 33}, {"id": "7-17", "list": 7, "number": 17, "english": "discuss", "phonetic": "/dɪˈskʌs/", "chinese": "v. 讨论", "example": "Let's discuss the plan after class. 让我们课后讨论这个计划。", "page": 33}, {"id": "7-18", "list": 7, "number": 18, "english": "iceberg", "phonetic": "/ˈaɪsbɜːrɡ/", "chinese": "n. 冰山", "example": "We have only seen the tip of the iceberg. 我们只是看到了冰山一角。", "page": 33}, {"id": "7-19", "list": 7, "number": 19, "english": "feel", "phonetic": "/fiːl/", "chinese": "v. 感觉", "example": "I feel happy about the good news. 我对这个好消息感到高兴。", "page": 33}, {"id": "7-20", "list": 7, "number": 20, "english": "energy", "phonetic": "/ˈenərdʒi/", "chinese": "n. 精力", "example": "Children have a lot of energy. 孩子们精力充沛。", "page": 33}, {"id": "7-21", "list": 7, "number": 21, "english": "tired", "phonetic": "/ˈtaɪərd/", "chinese": "adj. 疲倦的", "example": "He felt tired after the long run. 长跑后他感到疲倦。", "page": 34}, {"id": "7-22", "list": 7, "number": 22, "english": "quick", "phonetic": "/kwɪk/", "chinese": "adj. 快速的", "example": "She gave a quick answer. 她给了一个快速的回答。", "page": 34}, {"id": "7-23", "list": 7, "number": 23, "english": "important", "phonetic": "/ɪmˈpɔːrtnt/", "chinese": "adj. 重要的", "example": "Sleep is important for health. 睡眠对健康很重要。", "page": 34}, {"id": "7-24", "list": 7, "number": 24, "english": "healthy", "phonetic": "/ˈhelθi/", "chinese": "adj. 健康的", "example": "Fruits and vegetables are healthy. 水果和蔬菜是健康的。", "page": 34}, {"id": "7-25", "list": 7, "number": 25, "english": "popcorn", "phonetic": "/ˈpɑːpkɔːrn/", "chinese": "n. 爆米花", "example": "This popcorn tastes salty. 这个爆米花尝起来是咸的。", "page": 34}, {"id": "7-26", "list": 7, "number": 26, "english": "same", "phonetic": "/seɪm/", "chinese": "adj. 相同的", "example": "We have the same schoolbag. 我们有相同的书包。", "page": 34}, {"id": "7-27", "list": 7, "number": 27, "english": "different", "phonetic": "/ˈdɪfrənt/", "chinese": "adj. 不同的", "example": "People have different hobbies. 人们有不同的爱好。", "page": 34}, {"id": "7-28", "list": 7, "number": 28, "english": "problem", "phonetic": "/ˈprɑːbləm/", "chinese": "n. 问题", "example": "Can you solve this math problem? 你能解决这道数学题吗？", "page": 34}, {"id": "7-29", "list": 7, "number": 29, "english": "minute", "phonetic": "/ˈmɪnɪt/", "chinese": "n. 分钟", "example": "The bus arrives in five minutes. 公交车五分钟后到达。", "page": 34}, {"id": "7-30", "list": 7, "number": 30, "english": "edit", "phonetic": "/ˈedɪt/", "chinese": "v. 编辑", "example": "We will need to edit this essay later. 我们等下需要编辑这篇论文。", "page": 34}, {"id": "7-31", "list": 7, "number": 31, "english": "although", "phonetic": "/ɔːlˈðoʊ/", "chinese": "conj. 虽然", "example": "Although it rained, we played outside. 虽然下雨了，我们还是在外面玩。", "page": 35}, {"id": "7-32", "list": 7, "number": 32, "english": "except", "phonetic": "/ɪkˈsept/", "chinese": "prep. 除了", "example": "Everyone is here except Tom. 除了汤姆，大家都到了。", "page": 35}, {"id": "7-33", "list": 7, "number": 33, "english": "towards", "phonetic": "/tɔːrdz/", "chinese": "prep. 朝着", "example": "He walked towards the library. 他朝着图书馆走去。", "page": 35}, {"id": "7-34", "list": 7, "number": 34, "english": "stranger", "phonetic": "/ˈstreɪndʒər/", "chinese": "n. 陌生人", "example": "Do not talk to a stranger alone. 不要单独和陌生人说话。", "page": 35}, {"id": "7-35", "list": 7, "number": 35, "english": "dream", "phonetic": "/driːm/", "chinese": "n. 梦想", "example": "Her dream is to become a pilot. 她的梦想是成为一名飞行员。", "page": 35}, {"id": "7-36", "list": 7, "number": 36, "english": "item", "phonetic": "/ˈaɪtəm/", "chinese": "n. 物品，商品", "example": "This item is on sale today. 这件商品今天特价销售。", "page": 35}, {"id": "7-37", "list": 7, "number": 37, "english": "death", "phonetic": "/deθ/", "chinese": "n. 死亡", "example": "The story has a sad death scene. 这个故事有一个悲伤的死亡场景。", "page": 35}, {"id": "7-38", "list": 7, "number": 38, "english": "reach", "phonetic": "/riːtʃ/", "chinese": "v. 到达", "example": "We will reach the town by noon. 我们将在中午前到达小镇。", "page": 35}, {"id": "7-39", "list": 7, "number": 39, "english": "return", "phonetic": "/rɪˈtɜːrn/", "chinese": "v. 返回", "example": "Please return the book tomorrow. 请明天归还这本书。", "page": 35}, {"id": "7-40", "list": 7, "number": 40, "english": "condition", "phonetic": "/kənˈdɪʃn/", "chinese": "n. 状况", "example": "The car is in good condition. 这辆车的车况良好。", "page": 35}, {"id": "7-41", "list": 7, "number": 41, "english": "agree", "phonetic": "/əˈɡriː/", "chinese": "v. 同意", "example": "I agree with your idea. 我同意你的主意。", "page": 36}, {"id": "7-42", "list": 7, "number": 42, "english": "instead", "phonetic": "/ɪnˈsted/", "chinese": "adv. 代替，反而", "example": "Let's watch a movie instead. 我们改看电影吧。", "page": 36}, {"id": "7-43", "list": 7, "number": 43, "english": "robot", "phonetic": "/ˈroʊbɑːt/", "chinese": "n. 机器人", "example": "The robot can clean the floor. 这个机器人可以清洁地板。", "page": 36}, {"id": "7-44", "list": 7, "number": 44, "english": "undersea", "phonetic": "/ˈʌndərsiː/", "chinese": "adj. 海底的", "example": "We saw amazing undersea life. 我们看到了奇妙的海底生物。", "page": 36}, {"id": "7-45", "list": 7, "number": 45, "english": "submarine", "phonetic": "/ˌsʌbməˈriːn/", "chinese": "n. 潜水艇", "example": "The submarine explored the deep sea. 潜水艇探索了深海。", "page": 36}, {"id": "7-46", "list": 7, "number": 46, "english": "explorer", "phonetic": "/ɪkˈsplɔːrər/", "chinese": "n. 探险家", "example": "The explorer discovered a new cave. 探险家发现了一个新洞穴。", "page": 36}, {"id": "7-47", "list": 7, "number": 47, "english": "video", "phonetic": "/ˈvɪdioʊ/", "chinese": "n. 视频；录像", "example": "We made a short video for class. 我们为课堂录制了一个短视频。", "page": 36}, {"id": "7-48", "list": 7, "number": 48, "english": "protection", "phonetic": "/prəˈtekʃn/", "chinese": "n. 保护；防护", "example": "Wear a hat for sun protection. 戴帽子以保护免受阳光照射。", "page": 36}, {"id": "8-1", "list": 8, "number": 1, "english": "whole", "phonetic": "/hoʊl/", "chinese": "adj. 整个的", "example": "The whole class is here. 全班同学都在这儿。", "page": 37}, {"id": "8-2", "list": 8, "number": 2, "english": "recent", "phonetic": "/ˈriːsnt/", "chinese": "adj. 近来的", "example": "Her recent painting is beautiful. 她最近的画很美。", "page": 37}, {"id": "8-3", "list": 8, "number": 3, "english": "suddenly", "phonetic": "/ˈsʌdənli/", "chinese": "adv. 突然", "example": "It started to rain suddenly. 天突然下起雨来。", "page": 37}, {"id": "8-4", "list": 8, "number": 4, "english": "eventually", "phonetic": "/ɪˈventʃuəli/", "chinese": "adv. 最终", "example": "He eventually found his keys. 他最终找到了钥匙。", "page": 37}, {"id": "8-5", "list": 8, "number": 5, "english": "clearly", "phonetic": "/ˈklɪrli/", "chinese": "adv. 清楚地", "example": "Please speak clearly and slowly. 请清晰而缓慢地说。", "page": 37}, {"id": "8-6", "list": 8, "number": 6, "english": "simply", "phonetic": "/ˈsɪmpli/", "chinese": "adv. 简单地；仅仅", "example": "I simply forgot the time. 我仅仅是忘记了时间。", "page": 37}, {"id": "8-7", "list": 8, "number": 7, "english": "according to", "phonetic": "/əˈkɔːrdɪŋ tə/", "chinese": "phr. 根据", "example": "According to the map, we are close. 根据地图，我们很近了。", "page": 37}, {"id": "8-8", "list": 8, "number": 8, "english": "study", "phonetic": "/ˈstʌdi/", "chinese": "v. 学习", "example": "I study English every day. 我每天学习英语。", "page": 37}, {"id": "8-9", "list": 8, "number": 9, "english": "magnificent", "phonetic": "/mæɡˈnɪfɪsnt/", "chinese": "adj. 壮丽的；极好的", "example": "We saw a magnificent sunset. 我们看到了一场壮丽的日落。", "page": 37}, {"id": "8-10", "list": 8, "number": 10, "english": "together", "phonetic": "/təˈɡeðər/", "chinese": "adv. 一起", "example": "Let's work on this together. 让我们一起做这件事吧。", "page": 37}, {"id": "8-11", "list": 8, "number": 11, "english": "building", "phonetic": "/ˈbɪldɪŋ/", "chinese": "n. 建筑物", "example": "That is a very tall building. 那是一栋非常高的建筑。", "page": 38}, {"id": "8-12", "list": 8, "number": 12, "english": "dirty", "phonetic": "/ˈdɜːrti/", "chinese": "adj. 脏的", "example": "Please wash your dirty hands. 请洗洗你的脏手。", "page": 38}, {"id": "8-13", "list": 8, "number": 13, "english": "polluted", "phonetic": "/pəˈluːtɪd/", "chinese": "adj. 被污染的", "example": "The river looks very polluted. 这条河看起来污染严重。", "page": 38}, {"id": "8-14", "list": 8, "number": 14, "english": "waste", "phonetic": "/weɪst/", "chinese": "n. 废弃物", "example": "We should reduce plastic waste. 我们应该减少塑料垃圾。", "page": 38}, {"id": "8-15", "list": 8, "number": 15, "english": "roadworks", "phonetic": "/ˈroʊdwɜːrks/", "chinese": "n. 道路施工", "example": "Roadworks caused a traffic delay. 道路施工造成了交通延误。", "page": 38}, {"id": "8-16", "list": 8, "number": 16, "english": "traffic jam", "phonetic": "/ˈtræfɪk dʒæm/", "chinese": "n. 交通堵塞", "example": "We were stuck in a traffic jam. 我们被困在交通堵塞中。", "page": 38}, {"id": "8-17", "list": 8, "number": 17, "english": "arrive", "phonetic": "/əˈraɪv/", "chinese": "v. 到达", "example": "The train will arrive soon. 火车很快就要到了。", "page": 38}, {"id": "8-18", "list": 8, "number": 18, "english": "directions", "phonetic": "/dəˈrɛkʃənz/", "chinese": "n. 方向；指引", "example": "Can you give me directions? 你能给我指下路吗？", "page": 38}, {"id": "8-19", "list": 8, "number": 19, "english": "admire", "phonetic": "/ədˈmaɪər/", "chinese": "v. 钦佩；欣赏", "example": "I admire her hard work. 我钦佩她的努力工作。", "page": 38}, {"id": "8-20", "list": 8, "number": 20, "english": "space", "phonetic": "/speɪs/", "chinese": "n. 太空", "example": "Rockets travel into space. 火箭飞向太空。", "page": 38}, {"id": "8-21", "list": 8, "number": 21, "english": "well-known", "phonetic": "/ˌwel ˈnoʊn/", "chinese": "adj. 著名的", "example": "He is a well-known writer. 他是一位著名的作家。", "page": 39}, {"id": "8-22", "list": 8, "number": 22, "english": "souvenir", "phonetic": "/ˌsuːvəˈnɪr/", "chinese": "n. 纪念品", "example": "I bought a souvenir from Paris. 我从巴黎买了一件纪念品。", "page": 39}, {"id": "8-23", "list": 8, "number": 23, "english": "amusement park", "phonetic": "/əˈmjuːzmənt pɑːrk/", "chinese": "n. 游乐园", "example": "We rode roller coasters at the amusement park. 我们在游乐园坐了过山车。", "page": 39}, {"id": "8-24", "list": 8, "number": 24, "english": "conference", "phonetic": "/ˈkɑːnfərəns/", "chinese": "n. 会议", "example": "My father attends a business conference. 我父亲参加一个商务会议。", "page": 39}, {"id": "8-25", "list": 8, "number": 25, "english": "individual", "phonetic": "/ˌɪndɪˈvɪdʒuəl/", "chinese": "adj. 个人的", "example": "Each student has individual needs. 每个学生都有个人的需求。", "page": 39}, {"id": "8-26", "list": 8, "number": 26, "english": "jog", "phonetic": "/dʒɑːɡ/", "chinese": "v. 慢跑", "example": "My mother likes to jog in the park. 我妈妈喜欢在公园慢跑。", "page": 39}, {"id": "8-27", "list": 8, "number": 27, "english": "volunteer", "phonetic": "/ˌvɑːlənˈtɪr/", "chinese": "v/n. 志愿；志愿者", "example": "She will volunteer at the library. 她将在图书馆做志愿者。", "page": 39}, {"id": "8-28", "list": 8, "number": 28, "english": "create", "phonetic": "/kriˈeɪt/", "chinese": "v. 创造", "example": "Artists create beautiful paintings. 艺术家创造美丽的画作。", "page": 39}, {"id": "8-29", "list": 8, "number": 29, "english": "afford", "phonetic": "/əˈfɔːrd/", "chinese": "v. 负担得起", "example": "I cannot afford this expensive bike. 我买不起这辆昂贵的自行车。", "page": 39}, {"id": "8-30", "list": 8, "number": 30, "english": "multiply", "phonetic": "/ˈmʌltɪplaɪ/", "chinese": "v. 乘", "example": "We learn to multiply numbers in math. 我们在数学中学乘法。", "page": 39}, {"id": "8-31", "list": 8, "number": 31, "english": "thermometer", "phonetic": "/θərˈmɑːmɪtər/", "chinese": "n. 温度计", "example": "A thermometer measures temperature. 温度计测量温度。", "page": 40}, {"id": "8-32", "list": 8, "number": 32, "english": "battery", "phonetic": "/ˈbætəri/", "chinese": "n. 电池", "example": "The remote control needs a battery. 遥控器需要一节电池。", "page": 40}, {"id": "8-33", "list": 8, "number": 33, "english": "plan", "phonetic": "/plæn/", "chinese": "n. 计划", "example": "We made a plan for the trip. 我们为旅行制定了计划。", "page": 40}, {"id": "8-34", "list": 8, "number": 34, "english": "pull", "phonetic": "/pʊl/", "chinese": "v. 拉", "example": "Please pull the door to open it. 请拉开门。", "page": 40}, {"id": "8-35", "list": 8, "number": 35, "english": "totally", "phonetic": "/ˈtoʊtəli/", "chinese": "adv. 完全地", "example": "I totally agree with you. 我完全同意你。", "page": 40}, {"id": "8-36", "list": 8, "number": 36, "english": "pilot", "phonetic": "/ˈpaɪlət/", "chinese": "n. 飞行员", "example": "The pilot flies the plane safely. 飞行员安全地驾驶飞机。", "page": 40}, {"id": "8-37", "list": 8, "number": 37, "english": "fix", "phonetic": "/fɪks/", "chinese": "v. 修理", "example": "Can you fix my broken watch? 你能修好我的坏手表吗？", "page": 40}, {"id": "8-38", "list": 8, "number": 38, "english": "carry on", "phonetic": "/ˈkæri ɑːn/", "chinese": "v. 继续", "example": "Let's carry on with our game. 让我们继续我们的游戏吧。", "page": 40}, {"id": "8-39", "list": 8, "number": 39, "english": "metal", "phonetic": "/ˈmetl/", "chinese": "n. 金属", "example": "This box is made of metal. 这个盒子是金属做的。", "page": 40}, {"id": "8-40", "list": 8, "number": 40, "english": "stuck", "phonetic": "/stʌk/", "chinese": "adj. 被卡住的；困住的", "example": "The truck was stuck in the mud. 卡车陷在泥里了。", "page": 40}, {"id": "8-41", "list": 8, "number": 41, "english": "crew", "phonetic": "/kruː/", "chinese": "n. 全体船员；机组人员", "example": "The ship's crew worked hard. 船上的船员们工作努力。", "page": 41}, {"id": "8-42", "list": 8, "number": 42, "english": "member", "phonetic": "/ˈmembər/", "chinese": "n. 成员；会员", "example": "She is a member of the reading club. 她是阅读俱乐部的成员。", "page": 41}, {"id": "8-43", "list": 8, "number": 43, "english": "crane", "phonetic": "/kreɪn/", "chinese": "n. 起重机；鹤", "example": "A crane lifted the heavy beam. 起重机吊起了沉重的横梁。", "page": 41}, {"id": "8-44", "list": 8, "number": 44, "english": "lift", "phonetic": "/lɪft/", "chinese": "v. 举起；提升", "example": "Can you lift this heavy box? 你能举起这个重箱子吗？", "page": 41}, {"id": "8-45", "list": 8, "number": 45, "english": "darkness", "phonetic": "/ˈdɑːrknəs/", "chinese": "n. 黑暗", "example": "I saw a light in the darkness. 我在黑暗中看到一盏灯。", "page": 41}, {"id": "8-46", "list": 8, "number": 46, "english": "surface", "phonetic": "/ˈsɜːrfɪs/", "chinese": "n. 表面；外表", "example": "The table has a smooth surface. 这张桌子表面光滑。", "page": 41}, {"id": "8-47", "list": 8, "number": 47, "english": "wire", "phonetic": "/ˈwaɪər/", "chinese": "n. 金属线", "example": "The wire led to a speaker. 这电线连接着扬声器。", "page": 41}, {"id": "9-1", "list": 9, "number": 1, "english": "location", "phonetic": "/loʊˈkeɪʃn/", "chinese": "n. 地点；位置", "example": "This is a perfect location for a picnic. 这是野餐的绝佳地点。", "page": 42}, {"id": "9-2", "list": 9, "number": 2, "english": "map", "phonetic": "/mæp/", "chinese": "n. 地图", "example": "We use a map to find our way. 我们用地图来指路。", "page": 42}, {"id": "9-3", "list": 9, "number": 3, "english": "popular", "phonetic": "/ˈpɑːpjələr/", "chinese": "adj. 受欢迎的", "example": "This song is very popular now. 这首歌现在非常受欢迎。", "page": 42}, {"id": "9-4", "list": 9, "number": 4, "english": "carry", "phonetic": "/ˈkæri/", "chinese": "v. 携带", "example": "You must carry ID at all times. 你必须随身携带身份证件。", "page": 42}, {"id": "9-5", "list": 9, "number": 5, "english": "bank", "phonetic": "/bæŋk/", "chinese": "n. 银行", "example": "My mother works at a bank. 我妈妈在一家银行工作。", "page": 42}, {"id": "9-6", "list": 9, "number": 6, "english": "bridge", "phonetic": "/brɪdʒ/", "chinese": "n. 桥", "example": "We walked across the old bridge. 我们走过了那座古老的桥。", "page": 42}, {"id": "9-7", "list": 9, "number": 7, "english": "campus", "phonetic": "/ˈkæmpəs/", "chinese": "n. 大学校园", "example": "There is a big library on campus. 校园里有一个大图书馆。", "page": 42}, {"id": "9-8", "list": 9, "number": 8, "english": "car park", "phonetic": "/ˈkɑːr pɑːrk/", "chinese": "n. 停车场", "example": "The car park is full of cars. 停车场停满了车。", "page": 42}, {"id": "9-9", "list": 9, "number": 9, "english": "department store", "phonetic": "/dɪˈpɑːrtmənt stɔːr/", "chinese": "n. 百货公司", "example": "We bought clothes at the department store. 我们在百货公司买了衣服。", "page": 42}, {"id": "9-10", "list": 9, "number": 10, "english": "food court", "phonetic": "/ˈfuːd kɔːrt/", "chinese": "n. 美食广场", "example": "Let's have lunch at the food court. 我们在美食广场吃午饭吧。", "page": 42}, {"id": "9-11", "list": 9, "number": 11, "english": "fountain", "phonetic": "/ˈfaʊntn/", "chinese": "n. 喷泉", "example": "The fountain in the park is beautiful. 公园里的喷泉很漂亮。", "page": 43}, {"id": "9-12", "list": 9, "number": 12, "english": "hospital", "phonetic": "/ˈhɑːspɪtl/", "chinese": "n. 医院", "example": "He was taken to the hospital yesterday. 他昨天被送去了医院。", "page": 43}, {"id": "9-13", "list": 9, "number": 13, "english": "library", "phonetic": "/ˈlaɪbreri/", "chinese": "n. 图书馆", "example": "I borrowed two books from the library. 我从图书馆借了两本书。", "page": 43}, {"id": "9-14", "list": 9, "number": 14, "english": "museum", "phonetic": "/mjuˈziːəm/", "chinese": "n. 博物馆", "example": "We saw dinosaur bones in the museum. 我们在博物馆看到了恐龙骨骼。", "page": 43}, {"id": "9-15", "list": 9, "number": 15, "english": "playground", "phonetic": "/ˈpleɪɡraʊnd/", "chinese": "n. 游乐场", "example": "Children are playing on the playground. 孩子们正在游乐场上玩耍。", "page": 43}, {"id": "9-16", "list": 9, "number": 16, "english": "shopping centre", "phonetic": "/ˈʃɑːpɪŋ sentər/", "chinese": "n. 购物中心", "example": "The new shopping centre is very large. 新的购物中心非常大。", "page": 43}, {"id": "9-17", "list": 9, "number": 17, "english": "supermarket", "phonetic": "/ˈsuːpərmɑːrkɪt/", "chinese": "n. 超市", "example": "We buy our groceries at the supermarket. 我们在超市购买食品杂货。", "page": 43}, {"id": "9-18", "list": 9, "number": 18, "english": "nap", "phonetic": "/næp/", "chinese": "n. 小睡", "example": "The baby takes a short nap every afternoon. 宝宝每天下午小睡一会儿。", "page": 43}, {"id": "9-19", "list": 9, "number": 19, "english": "ballroom", "phonetic": "/ˈbɔːlruːm/", "chinese": "n. 舞厅", "example": "They held the party in the grand ballroom. 他们在宏伟的舞厅举行了派对。", "page": 43}, {"id": "9-20", "list": 9, "number": 20, "english": "stadium", "phonetic": "/ˈsteɪdiəm/", "chinese": "n. 体育场", "example": "The football match is at the stadium. 足球比赛在体育场举行。", "page": 43}, {"id": "9-21", "list": 9, "number": 21, "english": "accent", "phonetic": "/ˈæksent/", "chinese": "n. 口音", "example": "He speaks English with an American accent. 他说英语带美国口音。", "page": 44}, {"id": "9-22", "list": 9, "number": 22, "english": "irregular", "phonetic": "/ɪˈreɡjələr/", "chinese": "adj.不规则的", "example": "The verb 'go' has an irregular past tense. 动词 'go' 的过去式不规则。", "page": 44}, {"id": "9-23", "list": 9, "number": 23, "english": "invention", "phonetic": "/ɪnˈvenʃn/", "chinese": "n. 发明", "example": "The light bulb was a great invention. 电灯泡是一项伟大的发明。", "page": 44}, {"id": "9-24", "list": 9, "number": 24, "english": "prize", "phonetic": "/praɪz/", "chinese": "n. 奖品", "example": "She won first prize in the competition. 她在比赛中赢得了一等奖。", "page": 44}, {"id": "9-25", "list": 9, "number": 25, "english": "suffering", "phonetic": "/ˈsʌfərɪŋ/", "chinese": "n. 痛苦", "example": "The medicine reduced his pain and suffering. 药物减轻了他的痛苦。", "page": 44}, {"id": "9-26", "list": 9, "number": 26, "english": "organization", "phonetic": "/ˌɔːrɡənəˈzeɪʃn/", "chinese": "n. 组织", "example": "She works for an international organization. 她为一个国际组织工作。", "page": 44}, {"id": "9-27", "list": 9, "number": 27, "english": "dynamite", "phonetic": "/ˈdaɪnəmaɪt/", "chinese": "n. 炸药", "example": "Workers used dynamite to break the rock. 工人们用炸药炸开岩石。", "page": 44}, {"id": "9-28", "list": 9, "number": 28, "english": "misuse", "phonetic": "/ˌmɪsˈjuːs/", "chinese": "v. 滥用", "example": "It is wrong to misuse other people's trust. 滥用他人的信任是错误的。", "page": 44}, {"id": "9-29", "list": 9, "number": 29, "english": "disappear", "phonetic": "/ˌdɪsəˈpɪr/", "chinese": "v. 消失", "example": "The magician made the coin disappear. 魔术师让硬币消失了。", "page": 44}, {"id": "9-30", "list": 9, "number": 30, "english": "improve", "phonetic": "/ɪmˈpruːv/", "chinese": "v. 改进；改善", "example": "I practice daily to improve my English. 我每天练习以提高英语水平。", "page": 44}, {"id": "9-31", "list": 9, "number": 31, "english": "solve", "phonetic": "/sɑːlv/", "chinese": "v. 解决", "example": "Can you solve this math problem for me? 你能帮我解这道数学题吗？", "page": 45}, {"id": "9-32", "list": 9, "number": 32, "english": "machine", "phonetic": "/məˈʃiːn/", "chinese": "n. 机器", "example": "This machine washes clothes automatically. 这台机器能自动洗衣服。", "page": 45}, {"id": "9-33", "list": 9, "number": 33, "english": "expert", "phonetic": "/ˈekspɜːrt/", "chinese": "n. 专家", "example": "He is an expert on ancient history. 他是古代历史方面的专家。", "page": 45}, {"id": "9-34", "list": 9, "number": 34, "english": "illness", "phonetic": "/ˈɪlnəs/", "chinese": "n. 疾病", "example": "A good rest can help you recover from illness. 好好休息能帮助你从疾病中康复。", "page": 45}, {"id": "9-35", "list": 9, "number": 35, "english": "dangerous", "phonetic": "/ˈdeɪndʒərəs/", "chinese": "adj. 危险的", "example": "Playing with fire is very dangerous. 玩火是非常危险的。", "page": 45}, {"id": "9-36", "list": 9, "number": 36, "english": "touch", "phonetic": "/tʌtʃ/", "chinese": "v. 触摸", "example": "Please do not touch the wet paint. 请不要触摸未干的油漆。", "page": 45}, {"id": "9-37", "list": 9, "number": 37, "english": "list", "phonetic": "/lɪst/", "chinese": "n. 清单", "example": "I made a shopping list before going out. 我出门前列了一张购物清单。", "page": 45}, {"id": "9-38", "list": 9, "number": 38, "english": "ground", "phonetic": "/ɡraʊnd/", "chinese": "n. 地面", "example": "The leaves fell to the ground in autumn. 秋天树叶落到了地上。", "page": 45}, {"id": "9-39", "list": 9, "number": 39, "english": "kill", "phonetic": "/kɪl/", "chinese": "v. 杀死", "example": "Some chemicals can kill harmful insects. 一些化学品可以杀死有害昆虫。", "page": 45}, {"id": "9-40", "list": 9, "number": 40, "english": "germ", "phonetic": "/dʒɜːrm/", "chinese": "n. 细菌", "example": "Washing your hands kills germs. 洗手可以杀死细菌。", "page": 45}, {"id": "9-41", "list": 9, "number": 41, "english": "juice", "phonetic": "/dʒuːs/", "chinese": "n. 果汁", "example": "Would you like a glass of orange juice? 你想来杯橙汁吗？", "page": 46}, {"id": "9-42", "list": 9, "number": 42, "english": "thief", "phonetic": "/θiːf/", "chinese": "n. 小偷；贼", "example": "The police caught the thief last night. 警察昨晚抓住了那个小偷。", "page": 46}, {"id": "9-43", "list": 9, "number": 43, "english": "heat", "phonetic": "/hiːt/", "chinese": "v. 加热", "example": "Please heat the soup in the microwave. 请用微波炉把汤加热一下。", "page": 46}, {"id": "9-44", "list": 9, "number": 44, "english": "better", "phonetic": "/ˈbetər/", "chinese": "adv. 更好地", "example": "You should listen better in class. 你在课堂上应该更好地听讲。", "page": 46}, {"id": "9-45", "list": 9, "number": 45, "english": "cheese", "phonetic": "/tʃiːz/", "chinese": "n. 奶酪", "example": "I like to put cheese on my sandwich. 我喜欢在三明治里放奶酪。", "page": 46}, {"id": "9-46", "list": 9, "number": 46, "english": "case", "phonetic": "/keɪs/", "chinese": "n. 情况；案件", "example": "This is a interesting case for the detective. 这对侦探来说是个有趣的案件。", "page": 46}, {"id": "9-47", "list": 9, "number": 47, "english": "mark", "phonetic": "/mɑːrk/", "chinese": "n. 记号，标志", "example": "He made marks with a pencil. 他用铅笔作了记号。", "page": 46}, {"id": "9-48", "list": 9, "number": 48, "english": "match", "phonetic": "/mætʃ/", "chinese": "n./v. 匹配（物）", "example": "The curtains and carpet are a good match. 窗帘和地毯非常相配。", "page": 46}, {"id": "10-1", "list": 10, "number": 1, "english": "toilets", "phonetic": "/ˈtɔɪlɪts/", "chinese": "n. 卫生间", "example": "The toilets are at the end of the hall. 卫生间在走廊的尽头。", "page": 47}, {"id": "10-2", "list": 10, "number": 2, "english": "train station", "phonetic": "/ˈtreɪn ˈsteɪʃn/", "chinese": "n. 火车站", "example": "We wait for the train at the station. 我们在火车站等火车。", "page": 47}, {"id": "10-3", "list": 10, "number": 3, "english": "cross", "phonetic": "/krɔːs/", "chinese": "v. 穿过", "example": "Look both ways before you cross the street. 过马路前要左右看。", "page": 47}, {"id": "10-4", "list": 10, "number": 4, "english": "path", "phonetic": "/pæθ/", "chinese": "n. 小路", "example": "We walked along a narrow forest path. 我们沿着一条狭窄的林间小路行走。", "page": 47}, {"id": "10-5", "list": 10, "number": 5, "english": "square", "phonetic": "/skwer/", "chinese": "n. 广场", "example": "People gather in the town square. 人们聚集在镇上的广场。", "page": 47}, {"id": "10-6", "list": 10, "number": 6, "english": "sign", "phonetic": "/saɪn/", "chinese": "n. 标志；指示牌", "example": "Follow the road sign to the museum. 跟着路牌去博物馆。", "page": 47}, {"id": "10-7", "list": 10, "number": 7, "english": "corner", "phonetic": "/ˈkɔːrnər/", "chinese": "n. 角落", "example": "The cat is sleeping in the corner. 猫正在角落里睡觉。", "page": 47}, {"id": "10-8", "list": 10, "number": 8, "english": "straight", "phonetic": "/streɪt/", "chinese": "adv. 笔直地", "example": "Go straight for two blocks. 直走两个街区。", "page": 47}, {"id": "10-9", "list": 10, "number": 9, "english": "turn", "phonetic": "/tɜːrn/", "chinese": "v. 转弯", "example": "Turn left at the next traffic light. 在下一个红绿灯处左转。", "page": 47}, {"id": "10-10", "list": 10, "number": 10, "english": "left", "phonetic": "/left/", "chinese": "adj./adv. 左边（的）", "example": "The library is on your left side. 图书馆在你的左边。", "page": 47}, {"id": "10-11", "list": 10, "number": 11, "english": "right", "phonetic": "/raɪt/", "chinese": "adj./adv. 右边（的）", "example": "My house is on the right. 我的房子在右边。", "page": 48}, {"id": "10-12", "list": 10, "number": 12, "english": "miss", "phonetic": "/mɪs/", "chinese": "v. 错过；没找到", "example": "Don't miss the school bus today. 今天别错过校车。", "page": 48}, {"id": "10-13", "list": 10, "number": 13, "english": "email", "phonetic": "/ˈiːmeɪl/", "chinese": "n. 电子邮件", "example": "I'll email the documents to her. 我将用电子邮件把这些文件发送给她。", "page": 48}, {"id": "10-14", "list": 10, "number": 14, "english": "way", "phonetic": "/weɪ/", "chinese": "n. 道路；方式", "example": "Can you show me the way out? 你能给我指一下出去的路吗？", "page": 48}, {"id": "10-15", "list": 10, "number": 15, "english": "toward", "phonetic": "/təˈwɒrd/", "chinese": "prep. 向，朝", "example": "She ran toward the playground. 她朝游乐场跑去。", "page": 48}, {"id": "10-16", "list": 10, "number": 16, "english": "upon", "phonetic": "/əˈpɑːn/", "chinese": "prep. 在...之上", "example": "Once upon a time, there was a king. 很久以前，有一位国王。", "page": 48}, {"id": "10-17", "list": 10, "number": 17, "english": "entrance", "phonetic": "/ˈentrəns/", "chinese": "n. 入口", "example": "The entrance hall is littered with toys. 入口大厅里散落着玩具。", "page": 48}, {"id": "10-18", "list": 10, "number": 18, "english": "particular", "phonetic": "/pərˈtɪkjələr/", "chinese": "adj. 特别的", "example": "I have no particular place to go. 我没有什么特别的地方要去。", "page": 48}, {"id": "10-19", "list": 10, "number": 19, "english": "ago", "phonetic": "/əˈɡoʊ/", "chinese": "adv. 以前；之前", "example": "He left the school five minutes ago. 他五分钟前离开了学校。", "page": 48}, {"id": "10-20", "list": 10, "number": 20, "english": "source", "phonetic": "/sɔːrs/", "chinese": "n. 来源", "example": "Plants are the ultimate source of all foodstuffs. 植物是所有食物的最终来源。", "page": 48}, {"id": "10-21", "list": 10, "number": 21, "english": "complicated", "phonetic": "/ˈkɑːmplɪkeɪtɪd/", "chinese": "adj. 复杂的", "example": "The game rules are complicated. 这个游戏的规则很复杂。", "page": 49}, {"id": "10-22", "list": 10, "number": 22, "english": "notice", "phonetic": "/ˈnoʊtɪs/", "chinese": "v. 注意到", "example": "Did you notice the new painting? 你注意到那幅新画了吗？", "page": 49}, {"id": "10-23", "list": 10, "number": 23, "english": "approximately", "phonetic": "/əˈprɑːksɪmətli/", "chinese": "adv. 大约", "example": "The trip takes approximately two hours. 这次旅行大约需要两小时。", "page": 49}, {"id": "10-24", "list": 10, "number": 24, "english": "extraordinary", "phonetic": "/ɪkˈstrɔːrdəneri/", "chinese": "adj. 非凡的", "example": "She has an extraordinary talent for music. 她拥有非凡的音乐天赋。", "page": 49}, {"id": "10-25", "list": 10, "number": 25, "english": "achievement", "phonetic": "/əˈtʃiːvmənt/", "chinese": "n. 成就", "example": "Winning the race was a great achievement. 赢得比赛是一项伟大的成就。", "page": 49}, {"id": "10-26", "list": 10, "number": 26, "english": "hire", "phonetic": "/ˈhaɪər/", "chinese": "v. 雇佣", "example": "The company will hire three new workers. 公司将雇佣三名新员工。", "page": 49}, {"id": "10-27", "list": 10, "number": 27, "english": "deaf", "phonetic": "/def/", "chinese": "adj. 聋的", "example": "He is deaf and uses sign language. 他耳聋，使用手语。", "page": 49}, {"id": "10-28", "list": 10, "number": 28, "english": "fever", "phonetic": "/ˈfiːvər/", "chinese": "n. 发烧", "example": "He had a high fever last night. 他昨晚发高烧了。", "page": 49}, {"id": "10-29", "list": 10, "number": 29, "english": "graduate", "phonetic": "/ˈɡrædʒueɪt/", "chinese": "v. 毕业", "example": "My sister will graduate from university. 我姐姐将从大学毕业。", "page": 49}, {"id": "10-30", "list": 10, "number": 30, "english": "bloom", "phonetic": "/bluːm/", "chinese": "v. 开花", "example": "Flowers bloom in the spring. 花朵在春天绽放。", "page": 49}, {"id": "10-31", "list": 10, "number": 31, "english": "citizen", "phonetic": "/ˈsɪtɪzn/", "chinese": "n. 公民", "example": "Every citizen has rights and duties. 每个公民都有权利和义务。", "page": 50}, {"id": "10-32", "list": 10, "number": 32, "english": "be supposed to", "phonetic": "/bi səˈpoʊzd tu/", "chinese": "phr. 应该", "example": "You are supposed to finish your homework. 你应该完成你的作业。", "page": 50}, {"id": "10-33", "list": 10, "number": 33, "english": "horrible", "phonetic": "/ˈhɔːrəbl/", "chinese": "adj. 糟糕", "example": "I had a horrible dream last night. 我昨晚做了一个糟糕的梦。", "page": 50}, {"id": "10-34", "list": 10, "number": 34, "english": "catch", "phonetic": "/kætʃ/", "chinese": "v. 抓住", "example": "The cat tried to catch the mouse. 猫试图抓住老鼠。", "page": 50}, {"id": "10-35", "list": 10, "number": 35, "english": "vehicle", "phonetic": "/ˈviːəkl/", "chinese": "n. 车辆", "example": "Bicycles and cars are both vehicles. 自行车和汽车都是车辆。", "page": 50}, {"id": "10-36", "list": 10, "number": 36, "english": "step", "phonetic": "/step/", "chinese": "n. 脚步", "example": "He took a big step forward. 他向前迈了一大步。", "page": 50}, {"id": "10-37", "list": 10, "number": 37, "english": "alone", "phonetic": "/əˈloʊn/", "chinese": "adv. 独自地", "example": "She likes to read alone in her room. 她喜欢独自在房间里看书。", "page": 50}, {"id": "10-38", "list": 10, "number": 38, "english": "importantly", "phonetic": "/ɪmˈpɔːrtntli/", "chinese": "adv. 重要的是；重大地", "example": "Most importantly, you must be safe. 最重要的是，你必须安全。", "page": 50}, {"id": "10-39", "list": 10, "number": 39, "english": "compare", "phonetic": "/kəmˈper/", "chinese": "v. 比较，对比", "example": "Let's compare these two pictures. 让我们比较一下这两张图片。", "page": 50}, {"id": "10-40", "list": 10, "number": 40, "english": "possible", "phonetic": "/ˈpɑːsəbl/", "chinese": "adj. 可能的", "example": "It is possible to finish today. 今天有可能完成。", "page": 50}, {"id": "10-41", "list": 10, "number": 41, "english": "investigator", "phonetic": "/ɪnˈvestɪɡeɪtər/", "chinese": "n. 调查员；侦探", "example": "The investigator searched for clues. 调查员在寻找线索。", "page": 51}, {"id": "10-42", "list": 10, "number": 42, "english": "crime", "phonetic": "/kraɪm/", "chinese": "n. 犯罪，罪行", "example": "Stealing is a crime. 偷窃是犯罪。", "page": 51}, {"id": "10-43", "list": 10, "number": 43, "english": "outside", "phonetic": "/ˌaʊtˈsaɪd/", "chinese": "adv. 在外面", "example": "The children are playing outside. 孩子们正在外面玩。", "page": 51}, {"id": "10-44", "list": 10, "number": 44, "english": "probably", "phonetic": "/ˈprɑːbəbli/", "chinese": "adv. 很可能，大概", "example": "She will probably arrive at six. 她很可能会在六点到。", "page": 51}, {"id": "10-45", "list": 10, "number": 45, "english": "clue", "phonetic": "/kluː/", "chinese": "n. 线索；提示", "example": "The detective found an important clue. 侦探发现了一条重要线索。", "page": 51}, {"id": "10-46", "list": 10, "number": 46, "english": "body", "phonetic": "/ˈbɑːdi/", "chinese": "n. 身体", "example": "We need to exercise our body. 我们需要锻炼我们的身体。", "page": 51}, {"id": "10-47", "list": 10, "number": 47, "english": "fingerprint", "phonetic": "/ˈfɪŋɡərprɪnt/", "chinese": "n. 指纹", "example": "The police found a fingerprint on the glass. 警察在玻璃上发现了一个指纹。", "page": 51}, {"id": "11-1", "list": 11, "number": 1, "english": "crash", "phonetic": "/kræʃ/", "chinese": "v. （系统）崩溃；（车辆）撞毁", "example": "The computer crashed this morning. 今天早上电脑崩溃了。", "page": 52}, {"id": "11-2", "list": 11, "number": 2, "english": "yell", "phonetic": "/jel/", "chinese": "v. 大喊", "example": "Please don't yell in the library. 请不要在图书馆大喊。", "page": 52}, {"id": "11-3", "list": 11, "number": 3, "english": "determination", "phonetic": "/dɪˌtɜːrmɪˈneɪʃn/", "chinese": "n. 决心", "example": "Her determination helped her succeed. 她的决心帮助她取得了成功。", "page": 52}, {"id": "11-4", "list": 11, "number": 4, "english": "journal", "phonetic": "/ˈdʒɜːrnl/", "chinese": "n. 日记；刊物", "example": "I write in my journal every night. 我每晚都写日记。", "page": 52}, {"id": "11-5", "list": 11, "number": 5, "english": "fluency", "phonetic": "/ˈfluːənsi/", "chinese": "n. 流利度", "example": "She speaks French with great fluency. 她法语说得非常流利。", "page": 52}, {"id": "11-6", "list": 11, "number": 6, "english": "oxygen", "phonetic": "/ˈɑːksɪdʒən/", "chinese": "n. 氧气", "example": "We need oxygen to breathe. 我们需要氧气来呼吸。", "page": 52}, {"id": "11-7", "list": 11, "number": 7, "english": "medication", "phonetic": "/ˌmedɪˈkeɪʃn/", "chinese": "n. 药物", "example": "He takes medication for his headache. 他吃药治疗头痛。", "page": 52}, {"id": "11-8", "list": 11, "number": 8, "english": "emperor", "phonetic": "/ˈempərər/", "chinese": "n. 皇帝", "example": "The emperor lived in a large palace. 皇帝住在一座巨大的宫殿里。", "page": 52}, {"id": "11-9", "list": 11, "number": 9, "english": "goddess", "phonetic": "/ˈɡɑːdəs/", "chinese": "n. 女神", "example": "Athena was a goddess of wisdom. 雅典娜是智慧女神。", "page": 52}, {"id": "11-10", "list": 11, "number": 10, "english": "lava", "phonetic": "/ˈlɑːvə/", "chinese": "n. 熔岩", "example": "Hot lava flowed from the volcano. 炽热的熔岩从火山流出。", "page": 52}, {"id": "11-11", "list": 11, "number": 11, "english": "stripe", "phonetic": "/straɪp/", "chinese": "n. 条纹", "example": "The tiger has black stripes. 老虎有黑色的条纹。", "page": 53}, {"id": "11-12", "list": 11, "number": 12, "english": "mine", "phonetic": "/maɪn/", "chinese": "v/n. 开采；矿", "example": "They mine for gold in the mountains. 他们在山里开采黄金。", "page": 53}, {"id": "11-13", "list": 11, "number": 13, "english": "bark", "phonetic": "/bɑːrk/", "chinese": "v. （狗）吠叫", "example": "The dog barks at strangers. 这只狗对着陌生人叫。", "page": 53}, {"id": "11-14", "list": 11, "number": 14, "english": "circumstance", "phonetic": "/ˈsɜːrkəmstæns/", "chinese": "n. 环境；情况", "example": "It depends on the special circumstance. 这取决于特殊情况。", "page": 53}, {"id": "11-15", "list": 11, "number": 15, "english": "coach", "phonetic": "/koʊtʃ/", "chinese": "n. 教练", "example": "Our football coach is very strict. 我们的足球教练非常严格。", "page": 53}, {"id": "11-16", "list": 11, "number": 16, "english": "recently", "phonetic": "/ˈriːsntli/", "chinese": "adv. 最近", "example": "She moved to a new city recently. 她最近搬到了一个新城市。", "page": 53}, {"id": "11-17", "list": 11, "number": 17, "english": "immediately", "phonetic": "/ɪˈmiːdiətli/", "chinese": "adv. 立即", "example": "Please answer the question immediately. 请立即回答问题。", "page": 53}, {"id": "11-18", "list": 11, "number": 18, "english": "currently", "phonetic": "/ˈkɜːrəntli/", "chinese": "adv. 当前", "example": "He is currently studying at university. 他目前正在大学学习。", "page": 53}, {"id": "11-19", "list": 11, "number": 19, "english": "therefore", "phonetic": "/ˈðerfɔːr/", "chinese": "adv. 因此", "example": "It was raining, therefore we stayed inside. 下雨了，因此我们待在了室内。", "page": 53}, {"id": "11-20", "list": 11, "number": 20, "english": "otherwise", "phonetic": "/ˈʌðərwaɪz/", "chinese": "adv. 否则", "example": "Hurry up, otherwise we will be late. 快点，否则我们要迟到了。", "page": 53}, {"id": "11-21", "list": 11, "number": 21, "english": "architect", "phonetic": "/ˈɑːrkɪtekt/", "chinese": "n. 建筑师", "example": "The architect designed the building. 建筑师设计了这座建筑。", "page": 54}, {"id": "11-22", "list": 11, "number": 22, "english": "electrician", "phonetic": "/ɪˌlekˈtrɪʃn/", "chinese": "n. 电工", "example": "We need an electrician to fix the lights. 我们需要一名电工来修灯。", "page": 54}, {"id": "11-23", "list": 11, "number": 23, "english": "environment", "phonetic": "/ɪnˈvaɪrənmənt/", "chinese": "n. 环境", "example": "We must protect the environment. 我们必须保护环境。", "page": 54}, {"id": "11-24", "list": 11, "number": 24, "english": "farm", "phonetic": "/fɑːrm/", "chinese": "n. 农场", "example": "There are many animals on the farm. 农场里有很多动物。", "page": 54}, {"id": "11-25", "list": 11, "number": 25, "english": "farmer", "phonetic": "/ˈfɑːrmər/", "chinese": "n. 农民", "example": "The farmer grows corn and vegetables. 这位农民种植玉米和蔬菜。", "page": 54}, {"id": "11-26", "list": 11, "number": 26, "english": "power plant", "phonetic": "/ˈpaʊər plænt/", "chinese": "n. 发电厂", "example": "This power plant provides our electricity. 这家发电厂为我们供电。", "page": 54}, {"id": "11-27", "list": 11, "number": 27, "english": "careers adviser", "phonetic": "/kəˈrɪrz ədˈvaɪzər/", "chinese": "n. 职业顾问", "example": "The careers adviser gave me good advice. 职业顾问给了我很好的建议。", "page": 54}, {"id": "11-28", "list": 11, "number": 28, "english": "grade", "phonetic": "/ɡreɪd/", "chinese": "n. 成绩", "example": "She got a good grade on the test. 她在考试中取得了好成绩。", "page": 54}, {"id": "11-29", "list": 11, "number": 29, "english": "medical school", "phonetic": "/ˈmedɪkl skuːl/", "chinese": "n. 医学院", "example": "My brother wants to attend medical school. 我哥哥想上医学院。", "page": 54}, {"id": "11-30", "list": 11, "number": 30, "english": "work hard", "phonetic": "/ˈwɜːrk hɑːrd/", "chinese": "phr. 努力工作", "example": "If you work hard, you will succeed. 如果你努力工作，你就会成功。", "page": 54}, {"id": "11-31", "list": 11, "number": 31, "english": "experienced", "phonetic": "/ɪkˈspɪriənst/", "chinese": "adj. 有经验的", "example": "She is an experienced teacher. 她是一位经验丰富的老师。", "page": 55}, {"id": "11-32", "list": 11, "number": 32, "english": "advice", "phonetic": "/ədˈvaɪs/", "chinese": "n. 建议", "example": "My father gave me some useful advice. 我父亲给了我一些有用的建议。", "page": 55}, {"id": "11-33", "list": 11, "number": 33, "english": "boring", "phonetic": "/ˈbɔːrɪŋ/", "chinese": "adj. 无聊的", "example": "The movie was long and boring. 那部电影又长又无聊。", "page": 55}, {"id": "11-34", "list": 11, "number": 34, "english": "earn", "phonetic": "/ɜːrn/", "chinese": "v. 赚取（钱）", "example": "He wants to earn money this summer. 他想这个夏天赚钱。", "page": 55}, {"id": "11-35", "list": 11, "number": 35, "english": "presentation", "phonetic": "/ˌpriːzenˈteɪʃn/", "chinese": "n. 演讲，展示", "example": "I gave a presentation about space. 我做了一个关于太空的演讲。", "page": 55}, {"id": "11-36", "list": 11, "number": 36, "english": "challenge", "phonetic": "/ˈtʃælɪndʒ/", "chinese": "v. 向...挑战", "example": "He challenged his friend to a race. 他向他的朋友发起赛跑挑战。", "page": 55}, {"id": "11-37", "list": 11, "number": 37, "english": "classmate", "phonetic": "/ˈklæsmeɪt/", "chinese": "n. 同学", "example": "My classmate sits next to me. 我的同学坐在我旁边。", "page": 55}, {"id": "11-38", "list": 11, "number": 38, "english": "news", "phonetic": "/nuːz/", "chinese": "n. 新闻", "example": "My father watches the evening news. 我父亲看晚间新闻。", "page": 55}, {"id": "11-39", "list": 11, "number": 39, "english": "invitation", "phonetic": "/ˌɪnvɪˈteɪʃn/", "chinese": "n. 邀请", "example": "I received an invitation to a party. 我收到了一个派对的邀请。", "page": 55}, {"id": "11-40", "list": 11, "number": 40, "english": "save", "phonetic": "/seɪv/", "chinese": "v. 拯救", "example": "The firefighter worked to save the cat. 消防员努力去救那只猫。", "page": 55}, {"id": "11-41", "list": 11, "number": 41, "english": "speech", "phonetic": "/spiːtʃ/", "chinese": "n. 演说", "example": "The principal gave a short speech. 校长做了一个简短的演说。", "page": 56}, {"id": "11-42", "list": 11, "number": 42, "english": "fatal", "phonetic": "/ˈfeɪtl/", "chinese": "adj. 致命的；灾难性的", "example": "The car accident was fatal. 那场车祸是致命的。", "page": 56}, {"id": "11-43", "list": 11, "number": 43, "english": "effect", "phonetic": "/ɪˈfekt/", "chinese": "n. 效果；影响", "example": "The medicine had a good effect. 这种药有好的效果。", "page": 56}, {"id": "11-44", "list": 11, "number": 44, "english": "adult", "phonetic": "/əˈdʌlt/", "chinese": "n. 成年人", "example": "Children must be with an adult. 孩子们必须有成年人陪同。", "page": 56}, {"id": "11-45", "list": 11, "number": 45, "english": "liquid", "phonetic": "/ˈlɪkwɪd/", "chinese": "n. 液体", "example": "Water is a clear, colorless liquid. 水是一种清澈无色的液体。", "page": 56}, {"id": "11-46", "list": 11, "number": 46, "english": "encourage", "phonetic": "/ɪnˈkɜːrɪdʒ/", "chinese": "v. 鼓励；激励", "example": "My parents always encourage me. 我的父母总是鼓励我。", "page": 56}, {"id": "11-47", "list": 11, "number": 47, "english": "generation", "phonetic": "/ˌdʒenəˈreɪʃn/", "chinese": "n. 一代", "example": "He is the best actor of his generation. 他是他那一代人中最好的演员。", "page": 56}, {"id": "11-48", "list": 11, "number": 48, "english": "power", "phonetic": "/ˈpaʊər/", "chinese": "n. 力量；权力", "example": "Knowledge gives you power. 知识赋予你力量。", "page": 56}, {"id": "12-1", "list": 12, "number": 1, "english": "hard", "phonetic": "/hɑːrd/", "chinese": "adj. 困难的；努力的", "example": "This math problem is very hard. 这道数学题很难。", "page": 57}, {"id": "12-2", "list": 12, "number": 2, "english": "help", "phonetic": "/help/", "chinese": "v. 帮助", "example": "Can you help me with my homework? 你能帮我做作业吗？", "page": 57}, {"id": "12-3", "list": 12, "number": 3, "english": "job", "phonetic": "/dʒɑːb/", "chinese": "n. 工作", "example": "My father has a new job. 我父亲有一份新工作。", "page": 57}, {"id": "12-4", "list": 12, "number": 4, "english": "kind", "phonetic": "/kaɪnd/", "chinese": "adj. 友善的", "example": "She is a very kind teacher. 她是一位非常友善的老师。", "page": 57}, {"id": "12-5", "list": 12, "number": 5, "english": "polite", "phonetic": "/pəˈlaɪt/", "chinese": "adj. 有礼貌的", "example": "Please be polite to your elders. 请对长辈有礼貌。", "page": 57}, {"id": "12-6", "list": 12, "number": 6, "english": "strong", "phonetic": "/strɔːŋ/", "chinese": "adj. 强壮的", "example": "He is strong enough to lift it. 他很强壮，能举起它。", "page": 57}, {"id": "12-7", "list": 12, "number": 7, "english": "choose", "phonetic": "/tʃuːz/", "chinese": "v. 选择", "example": "You can choose any book you like. 你可以选择任何你喜欢的书。", "page": 57}, {"id": "12-8", "list": 12, "number": 8, "english": "decide", "phonetic": "/dɪˈsaɪd/", "chinese": "v. 决定", "example": "We must decide before lunch time. 我们必须在午饭前做出决定。", "page": 57}, {"id": "12-9", "list": 12, "number": 9, "english": "option", "phonetic": "/ˈɑːpʃn/", "chinese": "n. 选择", "example": "We have two options for lunch. 我们有两个午餐选择。", "page": 57}, {"id": "12-10", "list": 12, "number": 10, "english": "future", "phonetic": "/ˈfjuːtʃər/", "chinese": "n. 未来", "example": "What do you want to do in the future? 你未来想做什么？", "page": 57}, {"id": "12-11", "list": 12, "number": 11, "english": "friendly", "phonetic": "/ˈfrendli/", "chinese": "adj. 友好的", "example": "The new student is very friendly. 新来的学生非常友好。", "page": 58}, {"id": "12-12", "list": 12, "number": 12, "english": "course", "phonetic": "/kɔːrs/", "chinese": "n. 课程", "example": "I am taking an English course. 我正在修一门英语课程。", "page": 58}, {"id": "12-13", "list": 12, "number": 13, "english": "subject", "phonetic": "/ˈsʌbdʒɪkt/", "chinese": "n. 科目", "example": "My favorite subject is science. 我最喜欢的科目是科学。", "page": 58}, {"id": "12-14", "list": 12, "number": 14, "english": "learn", "phonetic": "/lɜːrn/", "chinese": "v. 学习", "example": "We learn new words every day. 我们每天学习新单词。", "page": 58}, {"id": "12-15", "list": 12, "number": 15, "english": "pitch", "phonetic": "/pɪtʃ/", "chinese": "n. 球场", "example": "The football pitch is very big. 这个足球场非常大。", "page": 58}, {"id": "12-16", "list": 12, "number": 16, "english": "easy", "phonetic": "/ˈiːzi/", "chinese": "adj. 容易的", "example": "This question is easy to answer. 这个问题很容易回答。", "page": 58}, {"id": "12-17", "list": 12, "number": 17, "english": "worse", "phonetic": "/wɜːrs/", "chinese": "adj./adv. 更差的/地", "example": "His cold is worse today. 他的感冒今天更严重了。", "page": 58}, {"id": "12-18", "list": 12, "number": 18, "english": "expand", "phonetic": "/ɪkˈspænd/", "chinese": "v. 扩大；膨胀", "example": "We need to expand the size of the image. 我们需要扩大图像的尺寸。", "page": 58}, {"id": "12-19", "list": 12, "number": 19, "english": "degree", "phonetic": "/dɪˈɡriː/", "chinese": "n. 学位", "example": "He has a university degree. 他拥有大学学位。", "page": 58}, {"id": "12-20", "list": 12, "number": 20, "english": "soon", "phonetic": "/suːn/", "chinese": "adv. 不久；马上", "example": "The bus will arrive soon. 公交车马上就要到了。", "page": 58}, {"id": "12-21", "list": 12, "number": 21, "english": "offer", "phonetic": "/ˈɔːfər/", "chinese": "n. 通知书；提议。", "example": "He received a job offer yesterday. 他昨天收到了一份工作录用通知", "page": 59}, {"id": "12-22", "list": 12, "number": 22, "english": "sight", "phonetic": "/saɪt/", "chinese": "n. 景观；视力", "example": "The Grand Canyon is a beautiful sight. 大峡谷是一处美丽的景观。", "page": 59}, {"id": "12-23", "list": 12, "number": 23, "english": "advantage", "phonetic": "/ədˈvæntɪdʒ/", "chinese": "n. 优点", "example": "One advantage of biking is exercise. 骑自行车的一个优点是锻炼身体。", "page": 59}, {"id": "12-24", "list": 12, "number": 24, "english": "disadvantage", "phonetic": "/ˌdɪsədˈvæntɪdʒ/", "chinese": "n. 缺点", "example": "A disadvantage is the bad weather. 一个缺点是天气不好。", "page": 59}, {"id": "12-25", "list": 12, "number": 25, "english": "amount", "phonetic": "/əˈmaʊnt/", "chinese": "n. 数量", "example": "A large amount of snow fell. 下了大量的雪。", "page": 59}, {"id": "12-26", "list": 12, "number": 26, "english": "slip", "phonetic": "/slɪp/", "chinese": "v. 滑倒", "example": "Be careful not to slip on the ice. 小心别在冰上滑倒。", "page": 59}, {"id": "12-27", "list": 12, "number": 27, "english": "mistake", "phonetic": "/mɪˈsteɪk/", "chinese": "n. 错误", "example": "I made a spelling mistake. 我犯了一个拼写错误。", "page": 59}, {"id": "12-28", "list": 12, "number": 28, "english": "service", "phonetic": "/ˈsɜːrvɪs/", "chinese": "n. 服务", "example": "The hotel provides excellent service. 这家酒店提供优质的服务。", "page": 59}, {"id": "12-29", "list": 12, "number": 29, "english": "distracted", "phonetic": "/dɪˈstræktɪd/", "chinese": "adj. 分心的", "example": "He was distracted by the noise. 他被噪音分心了。", "page": 59}, {"id": "12-30", "list": 12, "number": 30, "english": "transportation", "phonetic": "/ˌtrænspɔːrˈteɪʃn/", "chinese": "n. 交通运输", "example": "The city has good public transportation. 这个城市有良好的公共交通。", "page": 59}, {"id": "12-31", "list": 12, "number": 31, "english": "shuttle", "phonetic": "/ˈʃʌtl/", "chinese": "n. 穿梭班车", "example": "A free shuttle takes you downtown. 免费班车带您去市中心。", "page": 60}, {"id": "12-32", "list": 12, "number": 32, "english": "hardly", "phonetic": "/ˈhɑːrdli/", "chinese": "adv. 几乎不", "example": "I can hardly see in the dark. 我在黑暗中几乎看不见。", "page": 60}, {"id": "12-33", "list": 12, "number": 33, "english": "perform", "phonetic": "/pərˈfɔːrm/", "chinese": "v. 表演；执行", "example": "We will perform a play tomorrow. 我们明天将表演一出戏剧。", "page": 60}, {"id": "12-34", "list": 12, "number": 34, "english": "special", "phonetic": "/ˈspeʃl/", "chinese": "adj. 特殊的", "example": "Today is a special day for us. 今天对我们来说是个特殊的日子。", "page": 60}, {"id": "12-35", "list": 12, "number": 35, "english": "leaf", "phonetic": "/liːf/", "chinese": "n.叶子", "example": "A green leaf fell from the tree. 一片绿叶从树上落下。", "page": 60}, {"id": "12-36", "list": 12, "number": 36, "english": "lock", "phonetic": "/lɑːk/", "chinese": "v.锁、固定", "example": "Please lock the door when you leave. 离开时请锁好门。", "page": 60}, {"id": "12-37", "list": 12, "number": 37, "english": "famous", "phonetic": "/ˈfeɪməs/", "chinese": "adj.著名的", "example": "He is a famous basketball player. 他是一位著名的篮球运动员。", "page": 60}, {"id": "12-38", "list": 12, "number": 38, "english": "electrical", "phonetic": "/ɪˈlektrɪkl/", "chinese": "adj.电的", "example": "Please check the electrical wires. 请检查一下电线。", "page": 60}, {"id": "12-39", "list": 12, "number": 39, "english": "along", "phonetic": "/əˈlɔːŋ/", "chinese": "prep.沿着", "example": "We walked along the river bank. 我们沿着河岸散步。", "page": 60}, {"id": "12-40", "list": 12, "number": 40, "english": "within", "phonetic": "/wɪˈðɪn/", "chinese": "prep.在一段时间内", "example": "Please reply within three days. 请在三天内回复。", "page": 60}, {"id": "12-41", "list": 12, "number": 41, "english": "difference", "phonetic": "/ˈdɪfrəns/", "chinese": "n.差异", "example": "Can you tell the difference? 你能分辨出区别吗？", "page": 61}, {"id": "12-42", "list": 12, "number": 42, "english": "against", "phonetic": "/əˈɡenst/", "chinese": "prep. 反对；与…相反", "example": "We played against a strong team. 我们对阵了一支强队。", "page": 61}, {"id": "12-43", "list": 12, "number": 43, "english": "secret", "phonetic": "/ˈsiːkrət/", "chinese": "n. 秘密", "example": "Can you keep a little secret? 你能保守一个小秘密吗？", "page": 61}, {"id": "12-44", "list": 12, "number": 44, "english": "signal", "phonetic": "/ˈsɪɡnəl/", "chinese": "n. 信号", "example": "Wait for the green traffic signal. 等待绿色的交通信号灯。", "page": 61}, {"id": "12-45", "list": 12, "number": 45, "english": "creature", "phonetic": "/ˈkriːtʃər/", "chinese": "n. 生物", "example": "The deep sea has strange creatures. 深海里有奇怪的生物。", "page": 61}, {"id": "12-46", "list": 12, "number": 46, "english": "system", "phonetic": "/ˈsɪstəm/", "chinese": "n. 系统", "example": "Our school uses a new computer system. 我们学校使用新的计算机系统。", "page": 61}, {"id": "12-47", "list": 12, "number": 47, "english": "allow", "phonetic": "/əˈlaʊ/", "chinese": "v. 允许；准许", "example": "My parents allow me to watch TV. 我的父母允许我看电视。", "page": 61}, {"id": "12-48", "list": 12, "number": 48, "english": "drop", "phonetic": "/drɑːp/", "chinese": "n. 滴；微量", "example": "A drop of rain fell on my hand. 一滴雨落在我的手上。", "page": 61}, {"id": "13-1", "list": 13, "number": 1, "english": "choice", "phonetic": "/tʃɔɪs/", "chinese": "n. 选择", "example": "I have no other choice but to stay. 我除了留下别无选择。", "page": 62}, {"id": "13-2", "list": 13, "number": 2, "english": "consider", "phonetic": "/kənˈsɪdər/", "chinese": "v. 考虑", "example": "We need to consider his suggestion carefully. 我们需要仔细考虑他的建议。", "page": 62}, {"id": "13-3", "list": 13, "number": 3, "english": "require", "phonetic": "/rɪˈkwaɪər/", "chinese": "v. 要求", "example": "The job requires patience and skills. 这份工作要求耐心和技能。", "page": 62}, {"id": "13-4", "list": 13, "number": 4, "english": "major", "phonetic": "/ˈmeɪdʒər/", "chinese": "adj. 主要的", "example": "The major problem is lack of water. 主要问题是缺水。", "page": 62}, {"id": "13-5", "list": 13, "number": 5, "english": "solar", "phonetic": "/ˈsoʊlər/", "chinese": "adj. 太阳的，日光的", "example": "Solar energy is clean and renewable. 太阳能清洁且可再生。", "page": 62}, {"id": "13-6", "list": 13, "number": 6, "english": "panel", "phonetic": "/ˈpænl/", "chinese": "n. 板子", "example": "He put a wooden panel on the wall. 他在墙上装了一块木板。", "page": 62}, {"id": "13-7", "list": 13, "number": 7, "english": "grammar", "phonetic": "/ˈɡræmər/", "chinese": "n. 语法", "example": "You should pay attention to your grammar. 你应该注意自己的语法。", "page": 62}, {"id": "13-8", "list": 13, "number": 8, "english": "instructor", "phonetic": "/ɪnˈstrʌktər/", "chinese": "n. 指导者，辅导员", "example": "Our swimming instructor is very professional. 我们的游泳指导者非常专业。", "page": 62}, {"id": "13-9", "list": 13, "number": 9, "english": "manner", "phonetic": "/ˈmænər/", "chinese": "n. 礼貌，举止", "example": "He has good manners in public. 他在公共场合举止得体。", "page": 62}, {"id": "13-10", "list": 13, "number": 10, "english": "helpful", "phonetic": "/ˈhelpfəl/", "chinese": "adj. 乐于助人的，有用的", "example": "This book is very helpful for beginners. 这本书对初学者很有用。", "page": 62}, {"id": "13-11", "list": 13, "number": 11, "english": "staff", "phonetic": "/stæf/", "chinese": "n. 工作人员", "example": "The hotel staff are very kind. 这家酒店的工作人员很友善。", "page": 63}, {"id": "13-12", "list": 13, "number": 12, "english": "grass", "phonetic": "/ ræs/ ɡ", "chinese": "n. 草", "example": "The grass in the park is green. 公园里的草是绿色的。", "page": 63}, {"id": "13-13", "list": 13, "number": 13, "english": "hill", "phonetic": "/hɪl/", "chinese": "n. 小山", "example": "There is a small house on the hill. 小山上有一座小房子。", "page": 63}, {"id": "13-14", "list": 13, "number": 14, "english": "village", "phonetic": "/ˈvɪlɪdʒ/", "chinese": "n. 村庄", "example": "He was born in a quiet village. 他出生在一个宁静的村庄。", "page": 63}, {"id": "13-15", "list": 13, "number": 15, "english": "ceiling", "phonetic": "/ˈsiːlɪŋ/", "chinese": "n. 天花板", "example": "A lamp is hanging from the ceiling. 一盏灯从天花板垂下来。", "page": 63}, {"id": "13-16", "list": 13, "number": 16, "english": "furniture", "phonetic": "/ˈfɝːnɪtʃər/", "chinese": "n. 家具", "example": "This room has no expensive furniture. 这个房间没有昂贵的家具。", "page": 63}, {"id": "13-17", "list": 13, "number": 17, "english": "wood", "phonetic": "/wʊd/", "chinese": "n. 木材", "example": "The table is made of solid wood. 这张桌子是实木做的。", "page": 63}, {"id": "13-18", "list": 13, "number": 18, "english": "psychologist", "phonetic": "/saɪˈk ːlədʒɪst/ ɑ", "chinese": "n. 心理学家", "example": "The psychologist will help you solve the problem. 这位心理学家会帮你解决问题。", "page": 63}, {"id": "13-19", "list": 13, "number": 19, "english": "jet", "phonetic": "/dʒet/", "chinese": "n. 喷气式飞机", "example": "A jet flew over our house just now. 一架喷气式飞机刚刚从我们家上空飞过。", "page": 63}, {"id": "13-20", "list": 13, "number": 20, "english": "decision", "phonetic": "/dɪˈsɪʒn/", "chinese": "n. 决定", "example": "Her decision surprised everyone. 她的决定让所有人都很惊讶。", "page": 63}, {"id": "13-21", "list": 13, "number": 21, "english": "collect", "phonetic": "/kəˈlekt/", "chinese": "v. 收集", "example": "She likes to collect stamps in her free time. 她喜欢在空闲时间收集邮票。", "page": 64}, {"id": "13-22", "list": 13, "number": 22, "english": "floating", "phonetic": "/ˈfloʊtɪŋ/", "chinese": "adj. 漂浮的", "example": "There is a floating leaf on the river. 河面上有一片漂浮的叶子。", "page": 64}, {"id": "13-23", "list": 13, "number": 23, "english": "get rid of", "phonetic": "", "chinese": "phr. 摆脱；处理掉", "example": "We need to get rid of these old clothes. 我们需要处理掉这些旧衣服。", "page": 64}, {"id": "13-24", "list": 13, "number": 24, "english": "recycle", "phonetic": "/ˌriːˈsaɪkl/", "chinese": "v. 回收利用", "example": "We should recycle plastic bottles. 我们应该回收利用塑料瓶。", "page": 64}, {"id": "13-25", "list": 13, "number": 25, "english": "net", "phonetic": "/net/", "chinese": "n. 网", "example": "The fisherman caught fish with a net. 渔夫用网捕鱼。", "page": 64}, {"id": "13-26", "list": 13, "number": 26, "english": "benefit", "phonetic": "/ˈbenɪfɪt/", "chinese": "n. 益处", "example": "Eating vegetables has many benefits. 吃蔬菜有很多益处。", "page": 64}, {"id": "13-27", "list": 13, "number": 27, "english": "funding", "phonetic": "/ˈfʌndɪŋ/", "chinese": "n. 资金", "example": "The project needs more funding to go on. 这个项目需要更多资金才能继续。", "page": 64}, {"id": "13-28", "list": 13, "number": 28, "english": "fertilizer", "phonetic": "/ˈfɜːrtəlaɪzər/", "chinese": "n. 肥料", "example": "Farmers use fertilizer to help plants grow. 农民用肥料帮助植物生长。", "page": 64}, {"id": "13-29", "list": 13, "number": 29, "english": "balloon", "phonetic": "/bəˈluːn/", "chinese": "n. 气球", "example": "The child is holding a red balloon. 那个小孩手里拿着一个红色气球。", "page": 64}, {"id": "13-30", "list": 13, "number": 30, "english": "roller coaster", "phonetic": "", "chinese": "n. 过山车", "example": "The roller coaster in the park is very exciting. 公园里的过山车非常刺激。", "page": 64}, {"id": "13-31", "list": 13, "number": 31, "english": "scary", "phonetic": "/ˈskeri/", "chinese": "adj. 可怕的", "example": "That horror movie is too scary for me. 那部恐怖片对我来说太可怕了。", "page": 65}, {"id": "13-32", "list": 13, "number": 32, "english": "sunscreen", "phonetic": "/ˈsʌnskriːn/", "chinese": "n. 防晒霜", "example": "You should wear sunscreen on sunny days. 晴天你应该涂防晒霜。", "page": 65}, {"id": "13-33", "list": 13, "number": 33, "english": "umbrella", "phonetic": "/ʌmˈbrelə/", "chinese": "n. 雨伞", "example": "Don’t forget to take an umbrella with you. 别忘了随身带一把雨伞。", "page": 65}, {"id": "13-34", "list": 13, "number": 34, "english": "last", "phonetic": "/læst/", "chinese": "v. 持续", "example": "The meeting will last for two hours. 这场会议将持续两个小时。", "page": 65}, {"id": "13-35", "list": 13, "number": 35, "english": "useful", "phonetic": "/ˈjuːsfəl/", "chinese": "adj. 有用的", "example": "A dictionary is a useful tool for learning English. 词典是学习英语的有用工具。", "page": 65}, {"id": "13-36", "list": 13, "number": 36, "english": "result", "phonetic": "/rɪˈzʌlt/", "chinese": "n. 结果", "example": "The result of the exam will come out tomorrow. 考试结果明天会出来。", "page": 65}, {"id": "13-37", "list": 13, "number": 37, "english": "period", "phonetic": "/ˈpɪriəd/", "chinese": "n. 时期，阶段", "example": "This was a difficult period in his life. 这是他人生中的一段艰难时期。", "page": 65}, {"id": "13-38", "list": 13, "number": 38, "english": "worry", "phonetic": "/ˈwɜːri/", "chinese": "v. 担心", "example": "Don’t worry about your exam too much. 不要太担心你的考试。", "page": 65}, {"id": "13-39", "list": 13, "number": 39, "english": "prepare", "phonetic": "/prɪˈper/", "chinese": "v. 准备", "example": "She is busy preparing for the party. 她正忙着为派对做准备。", "page": 65}, {"id": "13-40", "list": 13, "number": 40, "english": "memory", "phonetic": "/ˈmeməri/", "chinese": "n. 记忆，回忆", "example": "This photo brings back good memories. 这张照片勾起了美好的回忆。", "page": 65}, {"id": "13-41", "list": 13, "number": 41, "english": "embarrassing", "phonetic": "/ɪmˈbærəsɪŋ/", "chinese": "adj. 让人尴尬的", "example": "He made an embarrassing mistake last weekend. 他上周犯了一个尴尬的错误。", "page": 66}, {"id": "13-42", "list": 13, "number": 42, "english": "figure out", "phonetic": "", "chinese": "phr. 理解；想出", "example": "I can’t figure out this math problem. 我想不出这道数学题的答案。", "page": 66}, {"id": "13-43", "list": 13, "number": 43, "english": "sound", "phonetic": "/saʊnd/", "chinese": "n. 声音", "example": "We heard a strange sound in the forest. 我们在森林里听到了一种奇怪的声音。", "page": 66}, {"id": "13-44", "list": 13, "number": 44, "english": "situation", "phonetic": "/ˌsɪtʃuˈeɪʃn/", "chinese": "n. 情况；形势", "example": "We need to change plans according to the situation. 我们需要根据形势改变计划。", "page": 66}, {"id": "13-45", "list": 13, "number": 45, "english": "brain", "phonetic": "/breɪn/", "chinese": "n. 大脑", "example": "Reading can exercise your brain. 阅读可以锻炼你的大脑。", "page": 66}, {"id": "13-46", "list": 13, "number": 46, "english": "edge", "phonetic": "/edʒ/", "chinese": "n. 边缘", "example": "He didn't dare look over the edge. 他不敢从边缘向下看。", "page": 66}, {"id": "13-47", "list": 13, "number": 47, "english": "pattern", "phonetic": "/ˈpætərn/", "chinese": "n. 图案；模式", "example": "I like the pattern on your shirt. 我喜欢你衣服上的图案。", "page": 66}, {"id": "14-1", "list": 14, "number": 1, "english": "window", "phonetic": "/ˈwɪndoʊ/", "chinese": "n. 窗户", "example": "She opened the window to let in fresh air. 她打开窗户让新鲜空气进来。", "page": 67}, {"id": "14-2", "list": 14, "number": 2, "english": "faraway", "phonetic": "/ˈfɑːrəweɪ/", "chinese": "adj. 遥远的", "example": "We saw a faraway mountain in the distance. 我们看到远处有一座遥远的山。", "page": 67}, {"id": "14-3", "list": 14, "number": 3, "english": "mosquito", "phonetic": "/məˈskiːtoʊ/", "chinese": "n. 蚊子", "example": "A mosquito bit me on the arm last night. 昨晚一只蚊子叮了我的胳膊。", "page": 67}, {"id": "14-4", "list": 14, "number": 4, "english": "pleasant", "phonetic": "/ˈpleznt/", "chinese": "adj. 令人愉快的，舒适的", "example": "We had a pleasant afternoon in the park. 我们在公园里度过了一个愉快的下午。", "page": 67}, {"id": "14-5", "list": 14, "number": 5, "english": "cheap", "phonetic": "/tʃiːp/", "chinese": "adj. 便宜的", "example": "This shirt is very cheap and good quality. 这件衬衫很便宜，质量也很好。", "page": 67}, {"id": "14-6", "list": 14, "number": 6, "english": "expensive", "phonetic": "/ɪkˈspensɪv/", "chinese": "adj. 昂贵的", "example": "The watch is too expensive for me to buy. 这块手表太贵了，我买不起。", "page": 67}, {"id": "14-7", "list": 14, "number": 7, "english": "near", "phonetic": "/nɪr/", "chinese": "prep. 近", "example": "My home is near the supermarket. 我家离超市很近。", "page": 67}, {"id": "14-8", "list": 14, "number": 8, "english": "noisy", "phonetic": "/ˈnɔɪzi/", "chinese": "adj. 嘈杂的", "example": "The street is very noisy during rush hour. 高峰时期这条街很嘈杂。", "page": 67}, {"id": "14-9", "list": 14, "number": 9, "english": "quiet", "phonetic": "/ˈkwaɪət/", "chinese": "adj. 安静的", "example": "She likes to read books in a quiet room. 她喜欢在安静的房间里看书。", "page": 67}, {"id": "14-10", "list": 14, "number": 10, "english": "armchair", "phonetic": "/ˈ ːrmtʃer/ ɑ", "chinese": "n. 扶手椅", "example": "He is sitting comfortably in the armchair. 他舒适地坐在扶手椅上。", "page": 67}, {"id": "14-11", "list": 14, "number": 11, "english": "bookcase", "phonetic": "/ˈbʊkkeɪs/", "chinese": "n. 书柜", "example": "There are many storybooks in the bookcase. 书柜里有很多故事书。", "page": 68}, {"id": "14-12", "list": 14, "number": 12, "english": "chair", "phonetic": "/tʃer/", "chinese": "n. 椅子", "example": "Please sit on that chair and wait for a moment. 请坐在那把椅子上稍等片刻。", "page": 68}, {"id": "14-13", "list": 14, "number": 13, "english": "desk", "phonetic": "/desk/", "chinese": "n. 书桌", "example": "He keeps his stationery on the desk. 他把文具放在书桌上。", "page": 68}, {"id": "14-14", "list": 14, "number": 14, "english": "lamp", "phonetic": "/læmp/", "chinese": "n. 灯", "example": "She turned on the lamp to read the newspaper. 她打开灯看报纸。", "page": 68}, {"id": "14-15", "list": 14, "number": 15, "english": "leather", "phonetic": "/ˈleðər/", "chinese": "adj. 皮革的", "example": "He has a leather bag for work. 他有一个皮质的工作包。", "page": 68}, {"id": "14-16", "list": 14, "number": 16, "english": "chemical", "phonetic": "/ˈkemɪk(ə)l/", "chinese": "adj. 化学的", "example": "Chemical weapons are banned. 禁止使用化学武器。", "page": 68}, {"id": "14-17", "list": 14, "number": 17, "english": "plastic", "phonetic": "/ˈplæstɪk/", "chinese": "adj. 塑料的", "example": "We should reduce the use of plastic products. 我们应该减少塑料制品的使用。", "page": 68}, {"id": "14-18", "list": 14, "number": 18, "english": "uncomfortable", "phonetic": "/ʌnˈkʌmfərtəbl/", "chinese": "adj. 不舒适的", "example": "The hard chair made me feel uncomfortable. 这把硬椅子让我觉得很不舒适。", "page": 68}, {"id": "14-19", "list": 14, "number": 19, "english": "wooden", "phonetic": "/ˈwʊdn/", "chinese": "adj. 木制的", "example": "My grandfather made a wooden box for me. 爷爷给我做了一个木盒子。", "page": 68}, {"id": "14-20", "list": 14, "number": 20, "english": "bottom", "phonetic": "/ˈbɑːtəm/", "chinese": "n. 底部", "example": "There is a small hole at the bottom of the bottle. 瓶子底部有一个小洞。", "page": 68}, {"id": "14-21", "list": 14, "number": 21, "english": "opinion", "phonetic": "/əˈpɪnjən/", "chinese": "n. 观点", "example": "Everyone has the right to express their own opinion. 每个人都有表达自己观点的权利。", "page": 69}, {"id": "14-22", "list": 14, "number": 22, "english": "whale", "phonetic": "/weɪl/", "chinese": "n. 鲸鱼", "example": "The blue whale is the largest animal in the world. 蓝鲸是世界上最大的动物。", "page": 69}, {"id": "14-23", "list": 14, "number": 23, "english": "crocodile", "phonetic": "/ˈkrɒkədaɪl/", "chinese": "n. 鳄鱼", "example": "We saw a crocodile lying on the riverbank. 我们看到一只鳄鱼趴在河岸上。", "page": 69}, {"id": "14-24", "list": 14, "number": 24, "english": "dam", "phonetic": "/dæm/", "chinese": "n. 水坝", "example": "The dam was built to control the flood. 这座水坝是为了防洪而建的。", "page": 69}, {"id": "14-25", "list": 14, "number": 25, "english": "tennis", "phonetic": "/ˈtenɪs/", "chinese": "n. 网球", "example": "He plays tennis with his friends every weekend. 他每周末都和朋友们打网球。", "page": 69}, {"id": "14-26", "list": 14, "number": 26, "english": "even", "phonetic": "/ˈiːvn/", "chinese": "adj. 平均的", "example": "The team has an even score in this game. 这支队伍在这场比赛中得分持平。", "page": 69}, {"id": "14-27", "list": 14, "number": 27, "english": "term", "phonetic": "/tɜːrm/", "chinese": "n. 术语", "example": "This is a special term in the field of physics. 这是物理学领域的一个专业术语。", "page": 69}, {"id": "14-28", "list": 14, "number": 28, "english": "row", "phonetic": "/roʊ/", "chinese": "n. 排；行", "example": "We sat in the third row of the cinema. 我们坐在电影院的第三排。", "page": 69}, {"id": "14-29", "list": 14, "number": 29, "english": "modern", "phonetic": "/ˈmɑːdərn/", "chinese": "adj. 现代的", "example": "This city has many modern buildings. 这座城市有很多现代化的建筑。", "page": 69}, {"id": "14-30", "list": 14, "number": 30, "english": "poet", "phonetic": "/ˈpoʊət/", "chinese": "n. 诗人", "example": "Li Bai was a famous poet in ancient China. 李白是中国古代一位著名的诗人。", "page": 69}, {"id": "14-31", "list": 14, "number": 31, "english": "exist", "phonetic": "/ɪɡˈzɪst/", "chinese": "v. 存在", "example": "Does life exist on other planets? 其他星球上存在生命吗？", "page": 70}, {"id": "14-32", "list": 14, "number": 32, "english": "familiar", "phonetic": "/fəˈmɪliər/", "chinese": "adj. 熟悉的", "example": "This song sounds very familiar to me. 这首歌我听起来很熟悉。", "page": 70}, {"id": "14-33", "list": 14, "number": 33, "english": "species", "phonetic": "/ˈspiːʃiːz/", "chinese": "n. 物种", "example": "This rare species is protected by the law. 这种珍稀物种受法律保护。", "page": 70}, {"id": "14-34", "list": 14, "number": 34, "english": "endangered", "phonetic": "/ɪnˈdeɪndʒərd/", "chinese": "adj. 濒危的", "example": "We should protect endangered animals. 我们应该保护濒危动物。", "page": 70}, {"id": "14-35", "list": 14, "number": 35, "english": "combine", "phonetic": "/kəmˈbaɪn/", "chinese": "v. 结合", "example": "We can combine theory with practice in study. 我们在学习中可以把理论和实践结合起来。", "page": 70}, {"id": "14-36", "list": 14, "number": 36, "english": "relative", "phonetic": "/ˈrelətɪv/", "chinese": "adj. 相关的", "example": "This article discusses facts relative to the problem. 这篇文章讨论了与该问题相关的事实。", "page": 70}, {"id": "14-37", "list": 14, "number": 37, "english": "believe", "phonetic": "/bɪˈliːv/", "chinese": "v. 相信，认为", "example": "I believe that he will come to the party on time. 我相信他会准时来参加派对。", "page": 70}, {"id": "14-38", "list": 14, "number": 38, "english": "mind", "phonetic": "/maɪnd/", "chinese": "n. 大脑，思想", "example": "Reading can broaden your mind. 阅读可以开阔你的眼界和思想。", "page": 70}, {"id": "14-39", "list": 14, "number": 39, "english": "ability", "phonetic": "/əˈbɪləti/", "chinese": "n. 能力", "example": "A woman of her ability will easily find a job. 有她那样才能的女性找工作不难。", "page": 70}, {"id": "14-40", "list": 14, "number": 40, "english": "trick", "phonetic": "/trɪk/", "chinese": "n. 诡计，把戏", "example": "The boy played a trick on his little sister. 这个男孩捉弄了他的小妹妹。", "page": 70}, {"id": "14-41", "list": 14, "number": 41, "english": "personal", "phonetic": "/ˈpɜːrsənl/", "chinese": "adj. 个人的", "example": "Please don’t ask others about their personal affairs. 请不要打听别人的私事。", "page": 71}, {"id": "14-42", "list": 14, "number": 42, "english": "impossible", "phonetic": "/ɪmˈpɑːsəbl/", "chinese": "adj. 不可能的", "example": "It’s impossible to finish the work in one hour. 在一个小时内完成这项工作是不可能的。", "page": 71}, {"id": "14-43", "list": 14, "number": 43, "english": "illusion", "phonetic": "/ɪˈluːʒn/", "chinese": "n. 幻觉；错觉", "example": "The mirage is just an optical illusion. 海市蜃楼只是一种光学错觉。", "page": 71}, {"id": "14-44", "list": 14, "number": 44, "english": "shadow", "phonetic": "/ˈʃædoʊ/", "chinese": "n. 影子；阴影", "example": "The tree cast a long shadow on the ground. 树在地上投下了长长的影子。", "page": 71}, {"id": "14-45", "list": 14, "number": 45, "english": "shape", "phonetic": "/ʃeɪp/", "chinese": "n. 形状；外形", "example": "The cloud has a strange shape like a rabbit. 那朵云的形状很奇怪，像一只兔子。", "page": 71}, {"id": "14-46", "list": 14, "number": 46, "english": "wheel", "phonetic": "/wiːl/", "chinese": "n. 车轮；方向盘", "example": "The car has a flat wheel and needs to be repaired. 这辆车有一个轮胎瘪了，需要修理。", "page": 71}, {"id": "14-47", "list": 14, "number": 47, "english": "movement", "phonetic": "/ˈmuːvmənt/", "chinese": "n. 运动；活动", "example": "The movement of the planets follows certain rules. 行星的运行遵循一定的规律。", "page": 71}, {"id": "14-48", "list": 14, "number": 48, "english": "confused", "phonetic": "/kənˈfjuːzd/", "chinese": "adj. 困惑的；混乱的", "example": "She was confused by the difficult math problem. 她被这道难解的数学题弄糊涂了。", "page": 71}, {"id": "15-1", "list": 15, "number": 1, "english": "evaluate", "phonetic": "/ɪˈvæljueɪt/", "chinese": "v. 评估（价值）", "example": "We need to evaluate the cost of this project first. 我们需要先评估这个项目的成本。", "page": 72}, {"id": "15-2", "list": 15, "number": 2, "english": "beautiful", "phonetic": "/ˈbjuːtɪfəl/", "chinese": "adj. 美丽的", "example": "She has a beautiful garden in front of her house. 她家门前有一个美丽的花园。", "page": 72}, {"id": "15-3", "list": 15, "number": 3, "english": "pretty", "phonetic": "/ˈprɪti/", "chinese": "adv. 相当，很", "example": "This movie is pretty interesting for kids. 这部电影对孩子们来说相当有趣。", "page": 72}, {"id": "15-4", "list": 15, "number": 4, "english": "colour", "phonetic": "/ˈkʌlər/", "chinese": "n. 颜色", "example": "What is your favourite colour? 你最喜欢的颜色是什么？", "page": 72}, {"id": "15-5", "list": 15, "number": 5, "english": "paint", "phonetic": "/peɪnt/", "chinese": "n. 油漆", "example": "We need to buy some white paint for the wall. 我们需要买一些白色油漆刷墙。", "page": 72}, {"id": "15-6", "list": 15, "number": 6, "english": "style", "phonetic": "/staɪl/", "chinese": "n. 风格", "example": "Her dress has a classic and elegant style. 她的裙子有着经典优雅的风格。", "page": 72}, {"id": "15-7", "list": 15, "number": 7, "english": "laptop", "phonetic": "/ˈlæptɑːp/", "chinese": "n. 笔记本电脑", "example": "She used to work at her laptop until four in the morning. 4 她以前经常在笔记本电脑前工作到凌晨 点钟。", "page": 72}, {"id": "15-8", "list": 15, "number": 8, "english": "prefer", "phonetic": "/prɪˈfɜːr/", "chinese": "v. 更喜欢", "example": "I prefer tea to coffee in the morning. 早上我更喜欢喝茶而不是咖啡。", "page": 72}, {"id": "15-9", "list": 15, "number": 9, "english": "spacious", "phonetic": "/ˈspeɪʃəs/", "chinese": "adj. 宽敞的", "example": "The new apartment is bright and spacious. 这套新公寓明亮又宽敞。", "page": 72}, {"id": "15-10", "list": 15, "number": 10, "english": "care and attention", "phonetic": "", "chinese": "phr. 关爱与关注", "example": "Every child needs enough care and attention from parents. 每个孩子都需要父母足够的关爱与关注。", "page": 72}, {"id": "15-11", "list": 15, "number": 11, "english": "dessert", "phonetic": "/dɪˈzɜːrt/", "chinese": "n. 甜点", "example": "I’d like a piece of cake as dessert. 我想要一块蛋糕当甜点。", "page": 73}, {"id": "15-12", "list": 15, "number": 12, "english": "luxury", "phonetic": "/ˈlʌkʃəri/", "chinese": "n. 奢侈品", "example": "This brand of watch is considered a luxury. 这个品牌的手表被视为奢侈品。", "page": 73}, {"id": "15-13", "list": 15, "number": 13, "english": "stand", "phonetic": "/stænd/", "chinese": "v. 站立", "example": "Please stand up when the teacher comes in. 老师进来时请起立。", "page": 73}, {"id": "15-14", "list": 15, "number": 14, "english": "melon", "phonetic": "/ˈmelən/", "chinese": "n. 瓜，甜瓜", "example": "This melon is sweet and juicy. 这个甜瓜香甜多汁。", "page": 73}, {"id": "15-15", "list": 15, "number": 15, "english": "coconut", "phonetic": "/ˈkoʊkənʌt/", "chinese": "n. 椰子", "example": "We drank fresh coconut water on the beach. 我们在沙滩上喝了新鲜的椰子水。", "page": 73}, {"id": "15-16", "list": 15, "number": 16, "english": "incorrect", "phonetic": "/ˌɪnkəˈrekt/", "chinese": "adj. 错误的", "example": "Your answer to this question is incorrect. 你这道题的答案是错误的。", "page": 73}, {"id": "15-17", "list": 15, "number": 17, "english": "theater", "phonetic": "/ˈθiːətər/", "chinese": "n. 剧院，电影院", "example": "We are going to the theater to watch a play tonight. 我们今晚要去剧院看一场话剧。", "page": 73}, {"id": "15-18", "list": 15, "number": 18, "english": "complex", "phonetic": "/ˈkɑːmpleks/", "chinese": "adj. 复杂的", "example": "This is a complex problem that needs careful thinking. 这是一个需要仔细思考的复杂问题。", "page": 73}, {"id": "15-19", "list": 15, "number": 19, "english": "background", "phonetic": "/ˈbækɡraʊnd/", "chinese": "n. 背景", "example": "The teacher asked us to write about our family background. 老师让我们写一下自己的家庭背景。", "page": 73}, {"id": "15-20", "list": 15, "number": 20, "english": "bright", "phonetic": "/braɪt/", "chinese": "adj. 明亮的", "example": "The sun is shining and the room is very bright. 阳光灿烂，房间里非常明亮。", "page": 73}, {"id": "15-21", "list": 15, "number": 21, "english": "mood", "phonetic": "/muːd/", "chinese": "n. 心情", "example": "Listening to music can improve my mood. 听音乐可以改善我的心情。", "page": 74}, {"id": "15-22", "list": 15, "number": 22, "english": "lazy", "phonetic": "/ˈleɪzi/", "chinese": "adj. 懒惰的", "example": "Don’t be lazy; finish your homework first. 别偷懒，先把作业写完。", "page": 74}, {"id": "15-23", "list": 15, "number": 23, "english": "extra", "phonetic": "/ˈekstrə/", "chinese": "adj. 额外的", "example": "The company gives extra pay for overtime work. 这家公司为加班工作支付额外报酬。", "page": 74}, {"id": "15-24", "list": 15, "number": 24, "english": "differ", "phonetic": "/ˈdɪfər/", "chinese": "v. ... 和 不同", "example": "My opinion differs from yours on this matter. 在这件事上，我的观点和你的不同。", "page": 74}, {"id": "15-25", "list": 15, "number": 25, "english": "definitely", "phonetic": "/ˈdefɪnətli/", "chinese": "adv. 肯定地", "example": "I will definitely attend your birthday party. 我肯定会参加你的生日派对。", "page": 74}, {"id": "15-26", "list": 15, "number": 26, "english": "mural", "phonetic": "/ˈmjʊrəl/", "chinese": "n. 壁画", "example": "There is a beautiful mural on the wall of the subway station. 地铁站的墙上有一幅漂亮的壁画。", "page": 74}, {"id": "15-27", "list": 15, "number": 27, "english": "skill", "phonetic": "/skɪl/", "chinese": "n. 技能", "example": "Cooking is a useful life skill. 烹饪是一项实用的生活技能。", "page": 74}, {"id": "15-28", "list": 15, "number": 28, "english": "suggestion", "phonetic": "/səˈdʒestʃən/", "chinese": "n. 建议", "example": "Do you have any suggestion for our trip? 你对我们的旅行有什么建议吗？", "page": 74}, {"id": "15-29", "list": 15, "number": 29, "english": "zebra", "phonetic": "/ˈzebrə/", "chinese": "n. 斑马", "example": "We saw a group of zebras on the grassland. 我们在草原上看到了一群斑马。", "page": 74}, {"id": "15-30", "list": 15, "number": 30, "english": "giraffe", "phonetic": "/dʒəˈræf/", "chinese": "n. 长颈鹿", "example": "The giraffe has a very long neck to eat leaves. 长颈鹿有长长的脖子用来吃树叶。", "page": 74}, {"id": "15-31", "list": 15, "number": 31, "english": "furry", "phonetic": "/ˈfɜːri/", "chinese": "adj. 毛茸茸的", "example": "The little cat has a soft and furry coat. 这只小猫有着柔软毛茸茸的毛。", "page": 75}, {"id": "15-32", "list": 15, "number": 32, "english": "repeat", "phonetic": "/rɪˈpiːt/", "chinese": "v. 重复", "example": "Could you repeat that sentence? I didn’t hear it clearly. 你能重复一下那个句子吗？我没听清楚。", "page": 75}, {"id": "15-33", "list": 15, "number": 33, "english": "threaten", "phonetic": "/ˈθretn/", "chinese": "v. 威胁，恐吓", "example": "No one has the right to threaten others. 没有人有权利威胁恐吓他人。", "page": 75}, {"id": "15-34", "list": 15, "number": 34, "english": "possibility", "phonetic": "/ˌpɑːsəˈbɪləti/", "chinese": "n. 可能性", "example": "There is a possibility of rain tomorrow. 明天有下雨的可能性。", "page": 75}, {"id": "15-35", "list": 15, "number": 35, "english": "border", "phonetic": "/ˈbɔːrdər/", "chinese": "n. 边境", "example": "The river forms a natural border between the two countries. 这条河构成了两国之间的天然边境。", "page": 75}, {"id": "15-36", "list": 15, "number": 36, "english": "carefully", "phonetic": "/ˈkerfəli/", "chinese": "adv. 小心地；仔细地", "example": "She carefully put the fragile vase on the shelf. 她小心翼翼地把易碎的花瓶放在架子上。", "page": 75}, {"id": "15-37", "list": 15, "number": 37, "english": "weigh", "phonetic": "/weɪ/", "chinese": "v. 称重量", "example": "Please weigh this package for me. 请帮我称一下这个包裹的重量。", "page": 75}, {"id": "15-38", "list": 15, "number": 38, "english": "skin", "phonetic": "/skɪn/", "chinese": "n. 皮肤", "example": "We should protect our skin from the sun in summer. 夏天我们应该保护皮肤免受日晒。", "page": 75}, {"id": "15-39", "list": 15, "number": 39, "english": "freeze", "phonetic": "/friːz/", "chinese": "v. 冰冻，冻结", "example": "Water will freeze when the temperature is below zero. 温度低于零度时水会结冰。", "page": 75}, {"id": "15-40", "list": 15, "number": 40, "english": "careful", "phonetic": "/ˈkerfl/", "chinese": "adj. 小心的", "example": "Be careful when you cross the busy street. 穿过繁忙的街道时要小心。", "page": 75}, {"id": "15-41", "list": 15, "number": 41, "english": "on one’s own", "phonetic": "", "chinese": "phr. 靠某人自己", "example": "She finished the difficult task on her own. 她靠自己完成了这项艰巨的任务。", "page": 76}, {"id": "15-42", "list": 15, "number": 42, "english": "enter", "phonetic": "/ˈentər/", "chinese": "v. 进入", "example": "You need a ticket to enter the museum. 进入博物馆需要门票。", "page": 76}, {"id": "15-43", "list": 15, "number": 43, "english": "ocean", "phonetic": "/ˈoʊʃən/", "chinese": "n. 海洋", "example": "The Pacific Ocean is the largest ocean in the world. 太平洋是世界上最大的海洋。", "page": 76}, {"id": "15-44", "list": 15, "number": 44, "english": "penguin", "phonetic": "/ˈpeŋɡwɪn/", "chinese": "n. 企鹅", "example": "Penguins live mainly in the Southern Hemisphere. 企鹅主要生活在南半球。", "page": 76}, {"id": "15-45", "list": 15, "number": 45, "english": "cover", "phonetic": "/ˈkʌvər/", "chinese": "v. 覆盖；涵盖", "example": "The snow covers the whole village. 大雪覆盖了整个村庄。", "page": 76}, {"id": "15-46", "list": 15, "number": 46, "english": "Antarctica", "phonetic": "/ænˈtɑːrktɪkə/", "chinese": "n. 南极洲", "example": "Very few people have been to Antarctica. 很少有人去过南极洲。", "page": 76}, {"id": "15-47", "list": 15, "number": 47, "english": "hatch", "phonetic": "/hætʃ/", "chinese": "v. 孵化", "example": "The little birds will hatch from the eggs in a few days. 几天后小鸟就会从蛋里孵化出来。", "page": 76}, {"id": "15-48", "list": 15, "number": 48, "english": "hilarious", "phonetic": "/hɪˈleriəs/", "chinese": "adj. 极有趣的；非常滑稽的", "example": "The comedy show was hilarious; we laughed all the time. 这场喜剧表演非常滑稽，我们笑个不停。", "page": 76}, {"id": "16-1", "list": 16, "number": 1, "english": "ordinary", "phonetic": "/ˈɔːrdəneri/", "chinese": "adj. 普通的", "example": "He is just an ordinary student in our class. 他只是我们班一名普通的学生。", "page": 77}, {"id": "16-2", "list": 16, "number": 2, "english": "international", "phonetic": "/ˌɪntərˈnæʃnəl/", "chinese": "adj. 国际的", "example": "This is an international meeting about environmental protection. 这是一场关于环境保护的国际会议。", "page": 77}, {"id": "16-3", "list": 16, "number": 3, "english": "smell", "phonetic": "/smel/", "chinese": "v. 闻起来", "example": "The flowers smell sweet in the garden. 花园里的花闻起来很香。", "page": 77}, {"id": "16-4", "list": 16, "number": 4, "english": "taste", "phonetic": "/teɪst/", "chinese": "v. 尝起来", "example": "The soup tastes a little salty. 这碗汤尝起来有点咸。", "page": 77}, {"id": "16-5", "list": 16, "number": 5, "english": "meat", "phonetic": "/miːt/", "chinese": "n. 肉类", "example": "My father doesn’t eat meat for health reasons. 我爸爸因为健康原因不吃肉。", "page": 77}, {"id": "16-6", "list": 16, "number": 6, "english": "rice", "phonetic": "/raɪs/", "chinese": "n. 米饭", "example": "I usually have a bowl of rice for lunch. 我午餐通常吃一碗米饭。", "page": 77}, {"id": "16-7", "list": 16, "number": 7, "english": "native", "phonetic": "/ˈneɪtɪv/", "chinese": "adj. n. 本土的； 本地人", "example": "Her native language is English. 她的母语是英语。", "page": 77}, {"id": "16-8", "list": 16, "number": 8, "english": "vegetable", "phonetic": "/ˈvedʒtəbl/", "chinese": "n. 蔬菜", "example": "We should eat more vegetables to keep healthy 我们应该多吃蔬菜来保持健康。", "page": 77}, {"id": "16-9", "list": 16, "number": 9, "english": "fast food", "phonetic": "", "chinese": "n. 快餐", "example": "Fast food is convenient but not very healthy. 快餐很方便，但不是很健康。", "page": 77}, {"id": "16-10", "list": 16, "number": 10, "english": "culture", "phonetic": "/ˈkʌltʃər/", "chinese": "n. 文化", "example": "We should respect different cultures around the world. 我们应该尊重世界各地不同的文化。", "page": 77}, {"id": "16-11", "list": 16, "number": 11, "english": "enjoy", "phonetic": "/ɪnˈdʒɔɪ/", "chinese": "v. 享受", "example": "I enjoy reading books in my spare time. 我喜欢在空闲时间看书。", "page": 78}, {"id": "16-12", "list": 16, "number": 12, "english": "fresh", "phonetic": "/freʃ/", "chinese": "adj. 新鲜的", "example": "The market sells fresh fruits and vegetables every day. 这个市场每天都卖新鲜的水果蔬菜。", "page": 78}, {"id": "16-13", "list": 16, "number": 13, "english": "meal", "phonetic": "/miːl/", "chinese": "n. 一餐", "example": "We had a delicious meal at that restaurant last night. 昨晚我们在那家餐厅吃了一顿美味的大餐。", "page": 78}, {"id": "16-14", "list": 16, "number": 14, "english": "burger", "phonetic": "/ˈbɜːrɡər/", "chinese": "n. 汉堡", "example": "He ordered a beef burger and a cup of cola. 他点了一个牛肉汉堡和一杯可乐。", "page": 78}, {"id": "16-15", "list": 16, "number": 15, "english": "chips", "phonetic": "/tʃɪps/", "chinese": "n. 薯条", "example": "The kids like to eat chips with tomato sauce. 孩子们喜欢蘸着番茄酱吃薯条。", "page": 78}, {"id": "16-16", "list": 16, "number": 16, "english": "noodles", "phonetic": "/ˈnuːdlz/", "chinese": "n. 面条", "example": "I had a bowl of chicken noodles for breakfast. 我早餐吃了一碗鸡肉面。", "page": 78}, {"id": "16-17", "list": 16, "number": 17, "english": "pasta", "phonetic": "/ˈpæstə/", "chinese": "n. 意大利面食", "example": "My sister is good at cooking pasta with cheese. 我姐姐很擅长做芝士意大利面。", "page": 78}, {"id": "16-18", "list": 16, "number": 18, "english": "pizza", "phonetic": "/ˈpiːtsə/", "chinese": "n. 披萨", "example": "We shared a large pizza with our friends. 我们和朋友们分享了一个大披萨。", "page": 78}, {"id": "16-19", "list": 16, "number": 19, "english": "energetic", "phonetic": "/ˌenərˈdʒetɪk/", "chinese": "adj. 有活力的", "example": "She is an energetic girl who likes playing sports. 她是一个热爱运动、精力充沛的女孩。", "page": 78}, {"id": "16-20", "list": 16, "number": 20, "english": "spell", "phonetic": "/spel/", "chinese": "v. 拼写", "example": "Can you spell this English word correctly? 你能正确拼写这个英语单词吗？", "page": 78}, {"id": "16-21", "list": 16, "number": 21, "english": "platform", "phonetic": "/ˈplætfɔːrm/", "chinese": "n. 平台", "example": "We are waiting for the train on platform 3. 3 我们正在 号站台等火车。", "page": 79}, {"id": "16-22", "list": 16, "number": 22, "english": "waterfall", "phonetic": "/ˈwɔːtərfɔːl/", "chinese": "n. 瀑布", "example": "The waterfall in this mountain is very spectacular. 这座山里的瀑布非常壮观。", "page": 79}, {"id": "16-23", "list": 16, "number": 23, "english": "coastal", "phonetic": "/ˈkoʊstl/", "chinese": "adj. 沿海的", "example": "Many tourists like to visit coastal cities in summer. 夏天很多游客喜欢去沿海城市旅游。", "page": 79}, {"id": "16-24", "list": 16, "number": 24, "english": "affect", "phonetic": "/əˈfekt/", "chinese": "v. 影响", "example": "Bad weather can affect our travel plans. 糟糕的天气会影响我们的旅行计划。", "page": 79}, {"id": "16-25", "list": 16, "number": 25, "english": "landowner", "phonetic": "/ˈlændoʊnər/", "chinese": "n. 土地所有者", "example": "The landowner agreed to rent his field to the farmer. 土地所有者同意把田地租给这位农民。", "page": 79}, {"id": "16-26", "list": 16, "number": 26, "english": "gene", "phonetic": "/dʒiːn/", "chinese": "n. 基因", "example": "Some diseases are related to gene inheritance. 有些疾病和基因遗传有关。", "page": 79}, {"id": "16-27", "list": 16, "number": 27, "english": "virtual", "phonetic": "/ˈvɜːrtʃuəl/", "chinese": "adj. 虚拟的", "example": "This is a virtual keyboard. 这是一个虚拟键盘。", "page": 79}, {"id": "16-28", "list": 16, "number": 28, "english": "reason", "phonetic": "/ˈriːzn/", "chinese": "n. 理由", "example": "Do you have any reason for being late today? 你今天迟到有什么理由吗？", "page": 79}, {"id": "16-29", "list": 16, "number": 29, "english": "cafeteria", "phonetic": "/ˌkæfəˈtɪriə/", "chinese": "n. 自助餐厅", "example": "We often have lunch in the school cafeteria. 我们经常在学校自助餐厅吃午饭。", "page": 79}, {"id": "16-30", "list": 16, "number": 30, "english": "specific", "phonetic": "/spəˈsɪfɪk/", "chinese": "adj. 具体的；特定的", "example": "Please give me a specific time for our meeting. 请给我一个我们开会的具体时间。", "page": 79}, {"id": "16-31", "list": 16, "number": 31, "english": "trend", "phonetic": "/trend/", "chinese": "n. 趋势", "example": "Online shopping is a popular trend nowadays. 网购是如今的流行趋势。", "page": 80}, {"id": "16-32", "list": 16, "number": 32, "english": "access", "phonetic": "/ˈækses/", "chinese": "v. 使用；进入", "example": "Students can access the school library for free. 学生可以免费使用学校图书馆。", "page": 80}, {"id": "16-33", "list": 16, "number": 33, "english": "issue", "phonetic": "/ˈɪʃuː/", "chinese": "n. 问题", "example": "We need to discuss this issue at the next meeting. 我们需要在下次会议上讨论这个问题。", "page": 80}, {"id": "16-34", "list": 16, "number": 34, "english": "fear", "phonetic": "/fɪr/", "chinese": "v./n. 害怕；恐惧", "example": "All his employees fear him. 他的所有雇员都害怕他", "page": 80}, {"id": "16-35", "list": 16, "number": 35, "english": "relationship", "phonetic": "/rɪˈleɪʃnʃɪp/", "chinese": "n. 联系", "example": "The relationship between the two countries is getting better. 两国之间的关系正在好转。", "page": 80}, {"id": "16-36", "list": 16, "number": 36, "english": "sense of humor", "phonetic": "", "chinese": "phr. 幽默感", "example": "Everyone likes him because he has a good sense of humor. 大家都喜欢他，因为他很有幽默感。", "page": 80}, {"id": "16-37", "list": 16, "number": 37, "english": "in fact", "phonetic": "", "chinese": "phr. 事实上", "example": "In fact, he doesn’t know the truth at all. 事实上，他根本不知道真相。", "page": 80}, {"id": "16-38", "list": 16, "number": 38, "english": "laugh", "phonetic": "/læf/", "chinese": "v. 大笑", "example": "The funny story made us laugh loudly. 这个有趣的故事让我们哈哈大笑。", "page": 80}, {"id": "16-39", "list": 16, "number": 39, "english": "joke", "phonetic": "/dʒoʊk/", "chinese": "n. 笑话", "example": "He told us a joke and we all laughed. 他给我们讲了一个笑话，我们都笑了。", "page": 80}, {"id": "16-40", "list": 16, "number": 40, "english": "place", "phonetic": "/pleɪs/", "chinese": "v. 放置", "example": "Please place your bag on the chair beside you. 请把你的包放在旁边的椅子上。", "page": 80}, {"id": "16-41", "list": 16, "number": 41, "english": "behavior", "phonetic": "/bɪˈheɪvjər/", "chinese": "n. 行为", "example": "His good behavior won the praise of the teacher. 他的良好行为得到了老师的表扬。", "page": 81}, {"id": "16-42", "list": 16, "number": 42, "english": "emotion", "phonetic": "/ɪˈmoʊʃn/", "chinese": "n. 情感；情绪", "example": "Music can express different kinds of emotions. 音乐可以表达各种各样的情感。", "page": 81}, {"id": "16-43", "list": 16, "number": 43, "english": "parrot", "phonetic": "/ˈpærət/", "chinese": "n. 鹦鹉", "example": "The parrot can imitate human speech. 这只鹦鹉能模仿人类说话。", "page": 81}, {"id": "16-44", "list": 16, "number": 44, "english": "area", "phonetic": "/ˈeriə/", "chinese": "n. 区域；领域", "example": "This area is famous for its beautiful scenery. 这个地区以优美的风景闻名。", "page": 81}, {"id": "16-45", "list": 16, "number": 45, "english": "tail", "phonetic": "/teɪl/", "chinese": "n. 尾巴", "example": "The dog ran up, wagging its tail. 那条狗摇着尾巴跑上前去。", "page": 81}, {"id": "16-46", "list": 16, "number": 46, "english": "birth", "phonetic": "/bɜːrθ/", "chinese": "n. 出生，分娩", "example": "Her parents held a party on her tenth birth anniversary. 她父母在她十周岁生日那天办了一场派对。", "page": 81}, {"id": "16-47", "list": 16, "number": 47, "english": "promise", "phonetic": "/ˈprɑːmɪs/", "chinese": "v. 承诺", "example": "I promise to help you with your English study. 我承诺会帮你补习英语。", "page": 81}, {"id": "16-48", "list": 16, "number": 48, "english": "fin", "phonetic": "/fɪn/", "chinese": "n. 鱼鳍", "example": "Without a fin, a shark can no longer swim. 没有鱼鳍，鲨鱼便无法再游泳。", "page": 81}, {"id": "16-49", "list": 16, "number": 49, "english": "town", "phonetic": "/taʊn/", "chinese": "n. 小镇", "example": "The town was founded in 1610. 1610 该城镇兴建于 年。", "page": 81}, {"id": "17-1", "list": 17, "number": 1, "english": "salad", "phonetic": "/ˈsæləd/", "chinese": "n. 沙拉", "example": "I ordered a salad for lunch. 我午餐点了一份沙拉。", "page": 82}, {"id": "17-2", "list": 17, "number": 2, "english": "sandwich", "phonetic": "/ˈsænwɪtʃ/", "chinese": "n. 三明治", "example": "He made a ham and cheese sandwich. 他做了一个火腿奶酪三明治。", "page": 82}, {"id": "17-3", "list": 17, "number": 3, "english": "taco", "phonetic": "/ˈtɑːkoʊ/", "chinese": "n. 墨西哥卷饼", "example": "We had tacos at the new Mexican restaurant. 我们在新开的墨西哥餐厅吃了卷饼。", "page": 82}, {"id": "17-4", "list": 17, "number": 4, "english": "grow", "phonetic": "/ɡroʊ/", "chinese": "v. 生长；种植", "example": "These plants grow along the river. 这些植物沿着河生长。", "page": 82}, {"id": "17-5", "list": 17, "number": 5, "english": "perfect", "phonetic": "/ˈpɜːrfɪkt/", "chinese": "adj. 完美的", "example": "The weather was perfect for a picnic. 那天的天气非常适合野餐。", "page": 82}, {"id": "17-6", "list": 17, "number": 6, "english": "gift", "phonetic": "/ɡɪft/", "chinese": "n. 礼物", "example": "Here's a gift for you. 这是给你的礼物。", "page": 82}, {"id": "17-7", "list": 17, "number": 7, "english": "probably", "phonetic": "/ˈprɑːbəbli/", "chinese": "adv. 可能", "example": "It will probably rain this afternoon. 今天下午可能会下雨。", "page": 82}, {"id": "17-8", "list": 17, "number": 8, "english": "average", "phonetic": "/ˈævərɪdʒ/", "chinese": "adj. 平均的", "example": "The average temperature in July is 30°C. 七月的平均气温是30摄氏度。", "page": 82}, {"id": "17-9", "list": 17, "number": 9, "english": "available", "phonetic": "/əˈveɪləbl/", "chinese": "adj. 可获得的", "example": "This opportunity is only available to students. 这个机会只有学生可获得。", "page": 82}, {"id": "17-10", "list": 17, "number": 10, "english": "past", "phonetic": "/pæst/", "chinese": "n./adj. 过去（的）", "example": "We cannot change the past. 我们无法改变过去。", "page": 82}, {"id": "17-11", "list": 17, "number": 11, "english": "change", "phonetic": "/tʃeɪndʒ/", "chinese": "v./n. 改变", "example": "You need to change your password regularly. 你需要定期更改密码。", "page": 83}, {"id": "17-12", "list": 17, "number": 12, "english": "percent", "phonetic": "/pərˈsent/", "chinese": "n. 百分比", "example": "About sixty percent of the students agreed. 大约百分之六十的学生表示同意。", "page": 83}, {"id": "17-13", "list": 17, "number": 13, "english": "response", "phonetic": "/rɪˈspɑːns/", "chinese": "n. 反应；答复", "example": "We haven’t received a response to our email yet. 我们还没有收到对邮件的回复。", "page": 83}, {"id": "17-14", "list": 17, "number": 14, "english": "diet", "phonetic": "/ˈdaɪət/", "chinese": "n. 饮食", "example": "A balanced diet is important for good health. 均衡的饮食对健康很重要。", "page": 83}, {"id": "17-15", "list": 17, "number": 15, "english": "ingredient", "phonetic": "/ɪnˈɡriːdiənt/", "chinese": "n. 原料", "example": "One ingredient in this dish is herbs. 这道菜的一个原料是香草。", "page": 83}, {"id": "17-16", "list": 17, "number": 16, "english": "resident", "phonetic": "/ˈrezɪdənt/", "chinese": "n. 居民", "example": "The new policy affects all residents of the city. 这项新政策影响了全市所有居民。", "page": 83}, {"id": "17-17", "list": 17, "number": 17, "english": "sustainable", "phonetic": "/səˈsteɪnəbl/", "chinese": "adj. 可持续的", "example": "We need to develop sustainable sources of energy. 我们需要开发可持续的能源。", "page": 83}, {"id": "17-18", "list": 17, "number": 18, "english": "produce", "phonetic": "/prəˈduːs/", "chinese": "v. 生产；产生", "example": "The machine produces a lot of noise. 这台机器产生很大噪音。", "page": 83}, {"id": "17-19", "list": 17, "number": 19, "english": "debate", "phonetic": "/dɪˈbeɪt/", "chinese": "n./v. 辩论", "example": "We will debate the issue tomorrow. 我们明天将辩论这个问题。", "page": 83}, {"id": "17-20", "list": 17, "number": 20, "english": "continue", "phonetic": "/kənˈtɪnjuː/", "chinese": "v. 继续", "example": "The rain is expected to continue until tonight. 预计雨会一直下到今晚。", "page": 83}, {"id": "17-21", "list": 17, "number": 21, "english": "development", "phonetic": "/dɪˈveləpmənt/", "chinese": "n. 发展", "example": "The development of technology is rapid. 科技的发展很快。", "page": 84}, {"id": "17-22", "list": 17, "number": 22, "english": "focus", "phonetic": "/ˈfoʊkəs/", "chinese": "v. 专注于", "example": "You need to focus on your studies. 你需要专注于你的学习。", "page": 84}, {"id": "17-23", "list": 17, "number": 23, "english": "join", "phonetic": "/dʒɔɪn/", "chinese": "v. 加入", "example": "He decided to join the local football club. 他决定加入当地的足球俱乐部。", "page": 84}, {"id": "17-24", "list": 17, "number": 24, "english": "necessary", "phonetic": "/ˈnesəseri/", "chinese": "adj. 必要的", "example": "It is necessary to book tickets in advance. 有必要提前订票。", "page": 84}, {"id": "17-25", "list": 17, "number": 25, "english": "opportunity", "phonetic": "/ˌɑːpərˈtuːnəti/", "chinese": "n. 机会", "example": "This job is a great opportunity for me. 这份工作对我来说是一个绝佳的机会。", "page": 84}, {"id": "17-26", "list": 17, "number": 26, "english": "provide", "phonetic": "/prəˈvaɪd/", "chinese": "v. 提供", "example": "The hotel provides free Wi-Fi. 这家酒店提供免费无线网络。", "page": 84}, {"id": "17-27", "list": 17, "number": 27, "english": "reduce", "phonetic": "/rɪˈduːs/", "chinese": "v. 减少", "example": "We should try to reduce plastic waste. 我们应该努力减少塑料垃圾。", "page": 84}, {"id": "17-28", "list": 17, "number": 28, "english": "argument", "phonetic": "/ˈɑːrɡjumənt/", "chinese": "n. 争论；理由", "example": "They had an argument about money. 他们为钱吵了一架。", "page": 84}, {"id": "17-29", "list": 17, "number": 29, "english": "invest", "phonetic": "/ɪnˈvest/", "chinese": "v. 投入（时间、资源）", "example": "You should invest more time in English. 你应该在英语上花更多时间。", "page": 84}, {"id": "17-30", "list": 17, "number": 30, "english": "elementary", "phonetic": "/ˌelɪˈmentri/", "chinese": "adj. 初级的", "example": "She teaches at an elementary school. 她在一所小学教书。", "page": 84}, {"id": "17-31", "list": 17, "number": 31, "english": "divide", "phonetic": "/dɪˈvaɪd/", "chinese": "v. 分开，分离", "example": "Please divide the cake into eight pieces. 请把蛋糕分成八块。", "page": 85}, {"id": "17-32", "list": 17, "number": 32, "english": "branch", "phonetic": "/bræntʃ/", "chinese": "n. 分支；树枝", "example": "A bird landed on a branch. 一只鸟落在了树枝上。", "page": 85}, {"id": "17-33", "list": 17, "number": 33, "english": "stage", "phonetic": "/steɪdʒ/", "chinese": "n. 阶段；台阶", "example": "The project is still in the early stages. 这个项目仍处于早期阶段。", "page": 85}, {"id": "17-34", "list": 17, "number": 34, "english": "mention", "phonetic": "/ˈmenʃn/", "chinese": "v. 提到", "example": "Did she mention where she was going? 她有没有提到她要去哪里？", "page": 85}, {"id": "17-35", "list": 17, "number": 35, "english": "central", "phonetic": "/ˈsentrəl/", "chinese": "adj. 中心的", "example": "The hotel is in a central location. 这家酒店位于中心位置。", "page": 85}, {"id": "17-36", "list": 17, "number": 36, "english": "finish", "phonetic": "/ˈfɪnɪʃ/", "chinese": "v. 完成", "example": "I need to finish this report by Friday. 我需要在周五前完成这份报告。", "page": 85}, {"id": "17-37", "list": 17, "number": 37, "english": "complete", "phonetic": "/kəmˈpliːt/", "chinese": "adj. 完全的/ v. 完成", "example": "When will you complete the task? 你什么时候能完成任务？", "page": 85}, {"id": "17-38", "list": 17, "number": 38, "english": "wide", "phonetic": "/waɪd/", "chinese": "adj. 宽的", "example": "The river is very wide here. 这条河在这里非常宽。", "page": 85}, {"id": "17-39", "list": 17, "number": 39, "english": "remain", "phonetic": "/rɪˈmeɪn/", "chinese": "v. 保持", "example": "Please remain seated until the plane has stopped. 请在飞机停稳前保持坐好。", "page": 85}, {"id": "17-40", "list": 17, "number": 40, "english": "solution", "phonetic": "/səˈluːʃn/", "chinese": "n. 解决方法", "example": "We need to find a solution. 我们需要找到解决方法。", "page": 85}, {"id": "17-41", "list": 17, "number": 41, "english": "light", "phonetic": "/laɪt/", "chinese": "adj. 轻的", "example": "This suitcase is very light. 这个行李箱很轻。", "page": 86}, {"id": "17-42", "list": 17, "number": 42, "english": "dome", "phonetic": "/doʊm/", "chinese": "n. 圆屋顶", "example": "The dome of the cathedral is a famous landmark. 大教堂的圆顶是一个著名的地标。", "page": 86}, {"id": "17-43", "list": 17, "number": 43, "english": "invent", "phonetic": "/ɪnˈvent/", "chinese": "v. 发明", "example": "Who invented the telephone? 电话是谁发明的？", "page": 86}, {"id": "17-44", "list": 17, "number": 44, "english": "incredible", "phonetic": "/ɪnˈkredəbl/", "chinese": "adj. 难以置信的", "example": "The view from the top was incredible. 从山顶看到的景色令人难以置信。", "page": 86}, {"id": "17-45", "list": 17, "number": 45, "english": "forecast", "phonetic": "/ˈfɔːrkæst/", "chinese": "n. 预测", "example": "The weather forecast says it will be sunny tomorrow. 天气预报说明天会是晴天。", "page": 86}, {"id": "17-46", "list": 17, "number": 46, "english": "large", "phonetic": "/lɑːrdʒ/", "chinese": "adj. 巨大的", "example": "They live in a large house in the countryside. 他们住在乡下的一栋大房子里。", "page": 86}, {"id": "17-47", "list": 17, "number": 47, "english": "float", "phonetic": "/floʊt/", "chinese": "v. 漂浮", "example": "Leaves were floating on the surface of the water. 树叶漂浮在水面上。", "page": 86}, {"id": "18-1", "list": 18, "number": 1, "english": "flavor", "phonetic": "/ˈfleɪvər/", "chinese": "n. 味道", "example": "This ice cream has a strong vanilla flavor. 这款冰淇淋有很浓的香草味。", "page": 87}, {"id": "18-2", "list": 18, "number": 2, "english": "pre-made", "phonetic": "/ˌpriː ˈmeɪd/", "chinese": "adj. 预制的", "example": "He bought a pre-made salad. 他买了一份预制的沙拉。", "page": 87}, {"id": "18-3", "list": 18, "number": 3, "english": "method", "phonetic": "/ˈmeθəd/", "chinese": "n. 方法", "example": "This is the most effective method I know. 这是我知道的最有效的方法。", "page": 87}, {"id": "18-4", "list": 18, "number": 4, "english": "consume", "phonetic": "/kənˈsuːm/", "chinese": "v. 消费", "example": "The new model consumes much less fuel. 这款新型号消耗的燃料少得多。", "page": 87}, {"id": "18-5", "list": 18, "number": 5, "english": "include", "phonetic": "/ɪnˈkluːd/", "chinese": "v. 包含", "example": "The price includes breakfast. 这个价格包含了早餐。", "page": 87}, {"id": "18-6", "list": 18, "number": 6, "english": "common", "phonetic": "/ˈkɑːmən/", "chinese": "adj. 常见的", "example": "It's a common mistake among beginners. 这是初学者常犯的错误。", "page": 87}, {"id": "18-7", "list": 18, "number": 7, "english": "typical", "phonetic": "/ˈtɪpɪkl/", "chinese": "adj. 典型的", "example": "This is a typical example. 这是一个典型范例。", "page": 87}, {"id": "18-8", "list": 18, "number": 8, "english": "highway", "phonetic": "/ˈhaɪweɪ/", "chinese": "n. 高速公路", "example": "There was an accident on the highway. 高速公路上发生了一起事故。", "page": 87}, {"id": "18-9", "list": 18, "number": 9, "english": "port", "phonetic": "/pɔːrt/", "chinese": "n. 港口", "example": "The ship arrived at the port early in the morning. 船在清晨抵达了港口。", "page": 87}, {"id": "18-10", "list": 18, "number": 10, "english": "transport", "phonetic": "/ˈtrænspɔːrt/", "chinese": "v. 运输", "example": "These goods will be transported by air. 这些货物将通过空运运输。", "page": 87}, {"id": "18-11", "list": 18, "number": 11, "english": "bus", "phonetic": "/bʌs/", "chinese": "n. 公共汽车", "example": "You can take the bus. 你可以乘坐公共汽车。", "page": 88}, {"id": "18-12", "list": 18, "number": 12, "english": "journey", "phonetic": "/ˈdʒɜːrni/", "chinese": "n. 旅程", "example": "The journey takes about two hours. 这段旅程大约需要两个小时。", "page": 88}, {"id": "18-13", "list": 18, "number": 13, "english": "metro", "phonetic": "/ˈmetroʊ/", "chinese": "n. 地铁", "example": "The metro is clean and runs on time. 地铁很干净，运行准时。", "page": 88}, {"id": "18-14", "list": 18, "number": 14, "english": "passenger", "phonetic": "/ˈpæsɪndʒər/", "chinese": "n. 乘客", "example": "All passengers must wear seat belts. 所有乘客都必须系好安全带。", "page": 88}, {"id": "18-15", "list": 18, "number": 15, "english": "taxi", "phonetic": "/ˈtæksi/", "chinese": "n. 出租车", "example": "We hailed a taxi outside the hotel. 我们在酒店外叫了一辆出租车。", "page": 88}, {"id": "18-16", "list": 18, "number": 16, "english": "ticket", "phonetic": "/ˈtɪkɪt/", "chinese": "n. 票", "example": "Have you bought your train ticket yet? 你买好火车票了吗？", "page": 88}, {"id": "18-17", "list": 18, "number": 17, "english": "train", "phonetic": "/treɪn/", "chinese": "n. 火车", "example": "The train to Beijing leaves at 3 p.m. 开往北京的火车下午3点发车。", "page": 88}, {"id": "18-18", "list": 18, "number": 18, "english": "travel", "phonetic": "/ˈtrævl/", "chinese": "v. 旅行", "example": "I love to travel and experience different cultures. 我喜欢旅行，体验不同的文化。", "page": 88}, {"id": "18-19", "list": 18, "number": 19, "english": "contactless", "phonetic": "/ˈkɑːntæktləs/", "chinese": "adj. 非接触式的", "example": "Shops now accept contactless payments. 现在商店接受非接触式支付。", "page": 88}, {"id": "18-20", "list": 18, "number": 20, "english": "survey", "phonetic": "/ˈsɜːrveɪ/", "chinese": "n. 问卷，调查", "example": "Please fill out this survey. 请填写这份问卷。", "page": 88}, {"id": "18-21", "list": 18, "number": 21, "english": "academically", "phonetic": "/ˌækəˈdemɪkli/", "chinese": "adv. 在学术上", "example": "She has always performed well academically. 她在学业上一直表现很好。", "page": 89}, {"id": "18-22", "list": 18, "number": 22, "english": "chance", "phonetic": "/tʃæns/", "chinese": "n. 机会", "example": "This is your chance to prove yourself. 这是你证明自己的机会。", "page": 89}, {"id": "18-23", "list": 18, "number": 23, "english": "unfair", "phonetic": "/ˌʌnˈfer/", "chinese": "adj. 不公平的", "example": "It's unfair that he got all the credit. 他得到了所有的功劳，这不公平。", "page": 89}, {"id": "18-24", "list": 18, "number": 24, "english": "violent", "phonetic": "/ˈvaɪələnt/", "chinese": "adj. 暴力的", "example": "The movie contains some violent scenes. 这部电影包含一些暴力场面。", "page": 89}, {"id": "18-25", "list": 18, "number": 25, "english": "responsibility", "phonetic": "/rɪˌspɑːnsəˈbɪləti/", "chinese": "n. 责任", "example": "It's your responsibility to finish the project. 完成这个项目是你的责任。", "page": 89}, {"id": "18-26", "list": 18, "number": 26, "english": "vote", "phonetic": "/voʊt/", "chinese": "v. 投票", "example": "All citizens over 18 have the right to vote. 所有18岁以上的公民都有投票权。", "page": 89}, {"id": "18-27", "list": 18, "number": 27, "english": "compromise", "phonetic": "/ˈkɑːmprəmaɪz/", "chinese": "n. 妥协", "example": "They finally reached a compromise. 他们最终达成了妥协。", "page": 89}, {"id": "18-28", "list": 18, "number": 28, "english": "lack", "phonetic": "/læk/", "chinese": "n. 缺乏", "example": "There is a lack of clean water in the region. 这个地区缺乏干净的水。", "page": 89}, {"id": "18-29", "list": 18, "number": 29, "english": "competitive", "phonetic": "/kəmˈpetətɪv/", "chinese": "adj. 有竞争力的", "example": "We need to offer competitive prices. 我们需要提供有竞争力的价格。", "page": 89}, {"id": "18-30", "list": 18, "number": 30, "english": "media", "phonetic": "/ˈmiːdiə/", "chinese": "n. 媒体(复数)", "example": "The news was widely reported in the media. 这条新闻被媒体广泛报道。", "page": 89}, {"id": "18-31", "list": 18, "number": 31, "english": "driverless", "phonetic": "/ˈdraɪvərləs/", "chinese": "adj. 无人驾驶的", "example": "Many companies are testing driverless cars. 许多公司正在测试无人驾驶汽车。", "page": 90}, {"id": "18-32", "list": 18, "number": 32, "english": "cheat", "phonetic": "/tʃiːt/", "chinese": "v. 作弊", "example": "The student cheated in the exam. 这位学生考试作弊。", "page": 90}, {"id": "18-33", "list": 18, "number": 33, "english": "volcano", "phonetic": "/vɑːlˈkeɪnoʊ/", "chinese": "n.火山", "example": "Do you know the name of the volcano? 你知道那座火山的名字吗？", "page": 90}, {"id": "18-34", "list": 18, "number": 34, "english": "at least", "phonetic": "/æt liːst/", "chinese": "至少", "example": "You should sleep for at least eight hours a day. 你每天至少应该睡八个小时。", "page": 90}, {"id": "18-35", "list": 18, "number": 35, "english": "hurricane", "phonetic": "/ˈhɜːrəkeɪn/", "chinese": "n. 飓风", "example": "The hurricane caused widespread damage. 飓风造成了广泛的破坏。", "page": 90}, {"id": "18-36", "list": 18, "number": 36, "english": "financial", "phonetic": "/faɪˈnænʃl/", "chinese": "adj. 金融的，财政的", "example": "The company is facing some financial difficulties. 公司正面临一些财务困难。", "page": 90}, {"id": "18-37", "list": 18, "number": 37, "english": "blame", "phonetic": "/bleɪm/", "chinese": "v. 责备", "example": "You can't blame him for this. 这件事你不能怪他。", "page": 90}, {"id": "18-38", "list": 18, "number": 38, "english": "deliver", "phonetic": "/dɪˈlɪvər/", "chinese": "v. 传递", "example": "The package will be delivered tomorrow. 包裹将于明天送达。", "page": 90}, {"id": "18-39", "list": 18, "number": 39, "english": "unusual", "phonetic": "/ʌnˈjuːʒuəl/", "chinese": "adj. 不寻常的", "example": "It's unusual for him to be late. 他迟到是不寻常的。", "page": 90}, {"id": "18-40", "list": 18, "number": 40, "english": "warning", "phonetic": "/ˈwɔːrnɪŋ/", "chinese": "n. 警告", "example": "The government issued a storm warning. 政府发布了风暴警告。", "page": 90}, {"id": "18-41", "list": 18, "number": 41, "english": "local", "phonetic": "/ˈloʊkl/", "chinese": "adj. 当地的", "example": "We enjoy going to the local market. 我们喜欢去当地的市场。", "page": 91}, {"id": "18-42", "list": 18, "number": 42, "english": "explode", "phonetic": "/ɪkˈsploʊd/", "chinese": "v. 爆炸", "example": "The old boiler could explode at any time. 那个旧锅炉随时可能爆炸。", "page": 91}, {"id": "18-43", "list": 18, "number": 43, "english": "hailstone", "phonetic": "/ˈheɪlstoʊn/", "chinese": "n. 冰雹", "example": "A hailstone hit the county. 一场冰雹袭击了这个县。", "page": 91}, {"id": "18-44", "list": 18, "number": 44, "english": "frequent", "phonetic": "/ˈfriːkwənt/", "chinese": "adj. 频繁的；经常的", "example": "He is a frequent visitor to the library. 他是图书馆的常客。", "page": 91}, {"id": "18-45", "list": 18, "number": 45, "english": "tornado", "phonetic": "/tɔːrˈneɪdoʊ/", "chinese": "n. 龙卷风", "example": "The small town was hit by a tornado. 小镇遭受了龙卷风袭击。", "page": 91}, {"id": "18-46", "list": 18, "number": 46, "english": "store", "phonetic": "/stɔːr/", "chinese": "n. 商店，店铺", "example": "There's a grocery store around the corner. 拐角处有一家杂货店。", "page": 91}, {"id": "18-47", "list": 18, "number": 47, "english": "drought", "phonetic": "/draʊt/", "chinese": "n. 干旱", "example": "The long drought has affected crop yields. 长期的干旱影响了农作物收成。", "page": 91}, {"id": "18-48", "list": 18, "number": 48, "english": "receive", "phonetic": "/rɪˈsiːv/", "chinese": "v. 收到", "example": "Did you receive my email? 你收到我的电子邮件了吗？", "page": 91}, {"id": "19-1", "list": 19, "number": 1, "english": "pie chart", "phonetic": "/ˈpaɪ ˌtʃɑːrt/", "chinese": "phr. 饼状图", "example": "The teacher drew a pie chart on the board. 老师在黑板上画了一个饼状图。", "page": 92}, {"id": "19-2", "list": 19, "number": 2, "english": "physical", "phonetic": "/ˈfɪzɪkl/", "chinese": "adj. 身体上的；物理上的", "example": "It was a physical change, not chemical. 这是一个物理变化，不是化学变化。", "page": 92}, {"id": "19-3", "list": 19, "number": 3, "english": "look after", "phonetic": "/ˈlʊk ˌæftər/", "chinese": "v. 照顾；负责", "example": "Can you look after my little sister? 你能照顾一下我妹妹吗？", "page": 92}, {"id": "19-4", "list": 19, "number": 4, "english": "pay-as-you-go", "phonetic": "/ˈpeɪ əz juː ˈɡoʊ/", "chinese": "adj. 即付即用的", "example": "He bought a pay-as-you-go phone card. 他买了一张即付即用的电话卡。", "page": 92}, {"id": "19-5", "list": 19, "number": 5, "english": "tap", "phonetic": "/tæp/", "chinese": "v. 轻触", "example": "Please tap the screen to continue. 请轻触屏幕以继续。", "page": 92}, {"id": "19-6", "list": 19, "number": 6, "english": "accident", "phonetic": "/ˈæksɪdənt/", "chinese": "n. 事故", "example": "We must try to prevent road accidents. 我们必须努力防止交通事故。", "page": 92}, {"id": "19-7", "list": 19, "number": 7, "english": "countryside", "phonetic": "/ˈkʌntrisaɪd/", "chinese": "n. 乡村", "example": "They love walking in the peaceful countryside. 他们喜欢在宁静的乡村散步。", "page": 92}, {"id": "19-8", "list": 19, "number": 8, "english": "pavement", "phonetic": "/ˈpeɪvmənt/", "chinese": "n. 人行道", "example": "Do not ride your bike on the pavement. 不要在人行道上骑自行车。", "page": 92}, {"id": "19-9", "list": 19, "number": 9, "english": "petrol", "phonetic": "/ˈpetrəl/", "chinese": "n. 汽油", "example": "Our car needs more petrol now. 我们的车现在需要加油了。", "page": 92}, {"id": "19-10", "list": 19, "number": 10, "english": "share", "phonetic": "/ʃer/", "chinese": "v. 分享", "example": "We should share our ideas in class. 我们应该在课堂上分享想法。", "page": 92}, {"id": "19-11", "list": 19, "number": 11, "english": "ferry", "phonetic": "/ˈferi/", "chinese": "n. 渡轮", "example": "We crossed the river on a large ferry. 我们乘坐一艘大渡轮过河。", "page": 93}, {"id": "19-12", "list": 19, "number": 12, "english": "gridlock", "phonetic": "/ˈɡrɪdlɑːk/", "chinese": "n. 交通瘫痪", "example": "The accident caused a total gridlock. 事故导致了交通完全瘫痪。", "page": 93}, {"id": "19-13", "list": 19, "number": 13, "english": "motorbike", "phonetic": "/ˈmoʊtərbaɪk/", "chinese": "n. 摩托车", "example": "His new motorbike is very fast. 他的新摩托车非常快。", "page": 93}, {"id": "19-14", "list": 19, "number": 14, "english": "build", "phonetic": "/bɪld/", "chinese": "v. 建造", "example": "They plan to build a new library. 他们计划建造一座新图书馆。", "page": 93}, {"id": "19-15", "list": 19, "number": 15, "english": "product", "phonetic": "/ˈprɑːdʌkt/", "chinese": "n. 产品", "example": "This is a very popular product. 这是一款非常受欢迎的产品。", "page": 93}, {"id": "19-16", "list": 19, "number": 16, "english": "drive", "phonetic": "/draɪv/", "chinese": "v. 驾驶", "example": "My father will drive us there. 我父亲会开车送我们去那儿。", "page": 93}, {"id": "19-17", "list": 19, "number": 17, "english": "public", "phonetic": "/ˈpʌblɪk/", "chinese": "adj. 公共的", "example": "Please be quiet in public places. 在公共场所请保持安静。", "page": 93}, {"id": "19-18", "list": 19, "number": 18, "english": "safe", "phonetic": "/seɪf/", "chinese": "adj. 安全的", "example": "It is not safe to swim alone. 独自游泳是不安全的。", "page": 93}, {"id": "19-19", "list": 19, "number": 19, "english": "uniform", "phonetic": "/ˈjuːnɪfɔːrm/", "chinese": "n. 制服", "example": "All students must wear school uniform. 所有学生必须穿校服。", "page": 93}, {"id": "19-20", "list": 19, "number": 20, "english": "disaster", "phonetic": "/dɪˈzæstər/", "chinese": "n. 灾难", "example": "The flood was a natural disaster. 那场洪水是一场自然灾害。", "page": 93}, {"id": "19-21", "list": 19, "number": 21, "english": "talent", "phonetic": "/ˈtælənt/", "chinese": "n. 天赋", "example": "She has a talent for playing the piano. 她有弹钢琴的天赋。", "page": 94}, {"id": "19-22", "list": 19, "number": 22, "english": "electric", "phonetic": "/ɪˈlektrɪk/", "chinese": "adj. 电动的；电的", "example": "Be careful with electric wires. 小心电线。", "page": 94}, {"id": "19-23", "list": 19, "number": 23, "english": "attack", "phonetic": "/əˈtæk/", "chinese": "v./n.攻击", "example": "It was a sudden attack at night. 那是夜间的一次突然袭击。", "page": 94}, {"id": "19-24", "list": 19, "number": 24, "english": "astronaut", "phonetic": "/ˈæstrənɔːt/", "chinese": "n. 宇航员", "example": "The astronaut gave a talk at our school. 那位宇航员在我们学校做了讲座。", "page": 94}, {"id": "19-25", "list": 19, "number": 25, "english": "patience", "phonetic": "/ˈpeɪʃns/", "chinese": "n. 耐心", "example": "Learning English requires patience. 学习英语需要耐心。", "page": 94}, {"id": "19-26", "list": 19, "number": 26, "english": "previous", "phonetic": "/ˈpriːviəs/", "chinese": "adj. 之前的", "example": "My previous school was very small. 我之前就读的学校非常小。", "page": 94}, {"id": "19-27", "list": 19, "number": 27, "english": "entertainment", "phonetic": "/ˌentərˈteɪnmənt/", "chinese": "n. 娱乐", "example": "Watching movies is a form of entertainment. 看电影是一种娱乐形式。", "page": 94}, {"id": "19-28", "list": 19, "number": 28, "english": "live", "phonetic": "/laɪv/", "chinese": "adj. 现场的", "example": "We watched a live football match. 我们观看了一场现场足球赛。", "page": 94}, {"id": "19-29", "list": 19, "number": 29, "english": "weak", "phonetic": "/wiːk/", "chinese": "adj. 弱的", "example": "He felt weak after his illness. 他病后感到很虚弱。", "page": 94}, {"id": "19-30", "list": 19, "number": 30, "english": "adventure", "phonetic": "/ədˈventʃər/", "chinese": "n. 冒险", "example": "The book tells a story of great adventure. 这本书讲述了一个伟大的冒险故事。", "page": 94}, {"id": "19-31", "list": 19, "number": 31, "english": "unforgettable", "phonetic": "/ˌʌnfərˈɡetəbl/", "chinese": "adj. 难忘的", "example": "It was an unforgettable summer holiday. 那是一个难忘的暑假。", "page": 95}, {"id": "19-32", "list": 19, "number": 32, "english": "coral", "phonetic": "/ˈkɔːrəl/", "chinese": "n. 珊瑚", "example": "We saw colorful coral while diving. 我们潜水时看到了五彩的珊瑚。", "page": 95}, {"id": "19-33", "list": 19, "number": 33, "english": "barrier", "phonetic": "/ˈbæriər/", "chinese": "n. 屏障；障碍物", "example": "The Great Wall was a great barrier. 长城曾是一道巨大的屏障。", "page": 95}, {"id": "19-34", "list": 19, "number": 34, "english": "nearby", "phonetic": "/ˌnɪrˈbaɪ/", "chinese": "adj. 附近的", "example": "There is a supermarket nearby. 附近有一家超市。", "page": 95}, {"id": "19-35", "list": 19, "number": 35, "english": "owner", "phonetic": "/ˈoʊnər/", "chinese": "n. 主人，拥有者", "example": "The owner of the shop is very kind. 这家商店的店主非常友善。", "page": 95}, {"id": "19-36", "list": 19, "number": 36, "english": "imagine", "phonetic": "/ɪˈmædʒɪn/", "chinese": "v. 想象，设想", "example": "Can you imagine life without phones? 你能想象没有手机的生活吗？", "page": 95}, {"id": "19-37", "list": 19, "number": 37, "english": "in detail", "phonetic": "/ɪn ˈdiːteɪl/", "chinese": "详细地", "example": "He explained the rules in detail. 他详细地解释了规则。", "page": 95}, {"id": "19-38", "list": 19, "number": 38, "english": "further", "phonetic": "/ˈfɜːrðər/", "chinese": "adj. 更进一步的", "example": "We need further discussion about this. 我们需要就此进行进一步讨论。", "page": 95}, {"id": "19-39", "list": 19, "number": 39, "english": "definitely", "phonetic": "/ˈdefɪnətli/", "chinese": "adv. 毫无疑问地，确切地", "example": "I will definitely come to your party. 我肯定会来参加你的派对。", "page": 95}, {"id": "19-40", "list": 19, "number": 40, "english": "tusk", "phonetic": "/tʌsk/", "chinese": "n. （象、野猪等的）长牙", "example": "An elephant has two long tusks. 大象有两根长长的象牙。", "page": 95}, {"id": "19-41", "list": 19, "number": 41, "english": "climb", "phonetic": "/klaɪm/", "chinese": "v. 爬", "example": "We will climb the mountain tomorrow. 我们明天要去爬山。", "page": 96}, {"id": "19-42", "list": 19, "number": 42, "english": "hunt", "phonetic": "/hʌnt/", "chinese": "v. 捕猎", "example": "Some animals hunt at night. 一些动物在夜间捕猎。", "page": 96}, {"id": "19-43", "list": 19, "number": 43, "english": "meanwhile", "phonetic": "/ˈmiːnwaɪl/", "chinese": "adv. 与此同时", "example": "She was cooking. Meanwhile, I set the table. 她在做饭，与此同时，我在摆桌子。", "page": 96}, {"id": "19-44", "list": 19, "number": 44, "english": "rise", "phonetic": "/raɪz/", "chinese": "v. 升起", "example": "The sun rises earlier in summer. 夏天太阳升起得更早。", "page": 96}, {"id": "19-45", "list": 19, "number": 45, "english": "daily", "phonetic": "/ˈdeɪli/", "chinese": "adj. 日常的", "example": "Drinking milk is my daily habit. 喝牛奶是我的日常习惯。", "page": 96}, {"id": "19-46", "list": 19, "number": 46, "english": "female", "phonetic": "/ˈfiːmeɪl/", "chinese": "adj. 雌性的；女性的", "example": "A female panda is called a sow. 雌性熊猫被称为 sow。", "page": 96}, {"id": "19-47", "list": 19, "number": 47, "english": "male", "phonetic": "/meɪl/", "chinese": "adj. 雄性的；男性的", "example": "The male lion has a big mane. 雄狮有浓密的鬃毛。", "page": 96}, {"id": "19-48", "list": 19, "number": 48, "english": "muddy", "phonetic": "/ˈmʌdi/", "chinese": "adj. 泥泞的", "example": "The path became muddy after the rain. 雨后小路变得泥泞。", "page": 96}, {"id": "19-49", "list": 19, "number": 49, "english": "active", "phonetic": "/ˈæktɪv/", "chinese": "adj. 主动的，活跃的", "example": "She is very active in class discussions. 她在课堂讨论中非常活跃。", "page": 96}, {"id": "19-50", "list": 19, "number": 50, "english": "passive", "phonetic": "/ˈpæsɪv/", "chinese": "adj. 被动的，消极的", "example": "He has a passive attitude towards this trip. 他对这次旅行持消极态度。", "page": 96}, {"id": "20-1", "list": 20, "number": 1, "english": "smog", "phonetic": "/smɑːɡ/", "chinese": "n. 雾霾", "example": "There is heavy smog in the city today. 今天城市里有严重的雾霾。", "page": 97}, {"id": "20-2", "list": 20, "number": 2, "english": "buzz", "phonetic": "/bʌz/", "chinese": "v. 震动（嗡嗡响）", "example": "A bee buzzed around the flowers. 一只蜜蜂绕着花嗡嗡响。", "page": 97}, {"id": "20-3", "list": 20, "number": 3, "english": "scheme", "phonetic": "/skiːm/", "chinese": "n. 方案，计划", "example": "They started a new clean-air scheme. 他们启动了一项新的清洁空气计划。", "page": 97}, {"id": "20-4", "list": 20, "number": 4, "english": "commute", "phonetic": "/kəˈmjuːt/", "chinese": "n./v. 通勤", "example": "She commutes to work by subway. 她乘地铁通勤上班。", "page": 97}, {"id": "20-5", "list": 20, "number": 5, "english": "route", "phonetic": "/ruːt/", "chinese": "n. 路线", "example": "This is the quickest route to school. 这是去学校最快的路线。", "page": 97}, {"id": "20-6", "list": 20, "number": 6, "english": "distance", "phonetic": "/ˈdɪstəns/", "chinese": "n. 距离", "example": "The distance from home is short. 这里离家的距离很短。", "page": 97}, {"id": "20-7", "list": 20, "number": 7, "english": "avoid", "phonetic": "/əˈvɔɪd/", "chinese": "v. 避免", "example": "We should avoid busy roads at night. 我们应该在晚上避开繁忙的道路。", "page": 97}, {"id": "20-8", "list": 20, "number": 8, "english": "efficient", "phonetic": "/ɪˈfɪʃnt/", "chinese": "adj. 高效的", "example": "This is an efficient way to study. 这是一种高效的学习方法。", "page": 97}, {"id": "20-9", "list": 20, "number": 9, "english": "convenient", "phonetic": "/kənˈviːniənt/", "chinese": "adj. 方便的", "example": "Online shopping is very convenient. 网上购物非常方便。", "page": 97}, {"id": "20-10", "list": 20, "number": 10, "english": "guide", "phonetic": "/ɡaɪd/", "chinese": "n./v. 指南；引导", "example": "This book is a useful travel guide. 这本书是有用的旅行指南。", "page": 97}, {"id": "20-11", "list": 20, "number": 11, "english": "motorway", "phonetic": "/ˈmoʊtərweɪ/", "chinese": "n. 高速公路", "example": "We saw many cars on the motorway. 我们在高速公路上看到许多汽车。", "page": 98}, {"id": "20-12", "list": 20, "number": 12, "english": "fare", "phonetic": "/fer/", "chinese": "n. 票价", "example": "The train fare is quite expensive. 火车票价相当贵。", "page": 98}, {"id": "20-13", "list": 20, "number": 13, "english": "delay", "phonetic": "/dɪˈleɪ/", "chinese": "n./v. 延误", "example": "The bad weather caused a delay. 恶劣天气造成了延误。", "page": 98}, {"id": "20-14", "list": 20, "number": 14, "english": "luggage", "phonetic": "/ˈlʌɡɪdʒ/", "chinese": "n. 行李", "example": "Please check your luggage carefully. 请仔细检查您的行李。", "page": 98}, {"id": "20-15", "list": 20, "number": 15, "english": "trip", "phonetic": "/trɪp/", "chinese": "n. 旅行，旅程", "example": "We had a wonderful class trip. 我们有一次很棒的班级旅行。", "page": 98}, {"id": "20-16", "list": 20, "number": 16, "english": "station", "phonetic": "/ˈsteɪʃn/", "chinese": "n. 车站", "example": "We waited at the bus station. 我们在公交车站等待。", "page": 98}, {"id": "20-17", "list": 20, "number": 17, "english": "rush hour", "phonetic": "/ˈrʌʃ ˌaʊər/", "chinese": "n. 交通高峰时间", "example": "The rush hour traffic is always bad. 高峰时段的交通总是很糟。", "page": 98}, {"id": "20-18", "list": 20, "number": 18, "english": "shipping", "phonetic": "/ˈʃɪpɪŋ/", "chinese": "n. 航运；运输", "example": "The shipping of goods takes time. 货物的运输需要时间。", "page": 98}, {"id": "20-19", "list": 20, "number": 19, "english": "dormitory", "phonetic": "/ˈdɔːrmətɔːri/", "chinese": "n. 宿舍", "example": "My dormitory is next to the library. 我的宿舍在图书馆旁边。", "page": 98}, {"id": "20-20", "list": 20, "number": 20, "english": "pedestrian", "phonetic": "/pəˈdestriən/", "chinese": "n. 行人", "example": "Pedestrians must follow the traffic lights. 行人必须遵守交通信号灯。", "page": 98}, {"id": "20-21", "list": 20, "number": 21, "english": "powerful", "phonetic": "/ˈpaʊərfl/", "chinese": "adj. 强大的", "example": "They have a very powerful team. 他们有一支非常强大的团队。", "page": 99}, {"id": "20-22", "list": 20, "number": 22, "english": "jealous", "phonetic": "/ˈdʒeləs/", "chinese": "adj. 嫉妒的", "example": "He felt jealous of his friend's new bike. 他嫉妒朋友的新自行车。", "page": 99}, {"id": "20-23", "list": 20, "number": 23, "english": "collapse", "phonetic": "/kəˈlæps/", "chinese": "v. 坍塌；崩溃", "example": "The old wall might collapse soon. 那堵旧墙可能很快就会倒塌。", "page": 99}, {"id": "20-24", "list": 20, "number": 24, "english": "set off", "phonetic": "/set ɔːf/", "chinese": "phr v. 引发；触发", "example": "Opening this door will set off the alarm. 打开这扇门会触发警铃。", "page": 99}, {"id": "20-25", "list": 20, "number": 25, "english": "remove", "phonetic": "/rɪˈmuːv/", "chinese": "v. 移除", "example": "Please remove your shoes at the door. 请在门口脱下鞋子。", "page": 99}, {"id": "20-26", "list": 20, "number": 26, "english": "weight", "phonetic": "/weɪt/", "chinese": "n. 重量", "example": "What is the weight of your schoolbag? 你书包的重量是多少？", "page": 99}, {"id": "20-27", "list": 20, "number": 27, "english": "myth", "phonetic": "/mɪθ/", "chinese": "n. 神话", "example": "This story is an old Greek myth. 这个故事是一个古老的希腊神话。", "page": 99}, {"id": "20-28", "list": 20, "number": 28, "english": "inventor", "phonetic": "/ɪnˈventər/", "chinese": "n. 发明家", "example": "Bell was the inventor of the telephone. 贝尔是电话的发明者。", "page": 99}, {"id": "20-29", "list": 20, "number": 29, "english": "fold", "phonetic": "/foʊld/", "chinese": "v. 折叠", "example": "Can you help me fold this map? 你能帮我折一下这张地图吗？", "page": 99}, {"id": "20-30", "list": 20, "number": 30, "english": "tunnel", "phonetic": "/ˈtʌnl/", "chinese": "n. 隧道", "example": "The train went through a dark tunnel. 火车穿过了一条黑暗的隧道。", "page": 99}, {"id": "20-31", "list": 20, "number": 31, "english": "council", "phonetic": "/ˈkaʊnsl/", "chinese": "n. 委员会", "example": "The student council organized the event. 学生会组织了这次活动。", "page": 100}, {"id": "20-32", "list": 20, "number": 32, "english": "wellness", "phonetic": "/ˈwelnəs/", "chinese": "n. 健康", "example": "Good sleep is important for wellness. 良好的睡眠对健康很重要。", "page": 100}, {"id": "20-33", "list": 20, "number": 33, "english": "process", "phonetic": "/ˈprɑːses/", "chinese": "n. 过程", "example": "Growing up is a natural process. 成长是一个自然的过程。", "page": 100}, {"id": "20-34", "list": 20, "number": 34, "english": "success", "phonetic": "/səkˈses/", "chinese": "n. 成功", "example": "Hard work leads to success. 努力会带来成功。", "page": 100}, {"id": "20-35", "list": 20, "number": 35, "english": "factory", "phonetic": "/ˈfæktri/", "chinese": "n. 工厂", "example": "That factory makes toy cars. 那家工厂生产玩具汽车。", "page": 100}, {"id": "20-36", "list": 20, "number": 36, "english": "operate", "phonetic": "/ˈɑːpəreɪt/", "chinese": "v. 操作", "example": "He learned to operate the machine. 他学会了操作那台机器。", "page": 100}, {"id": "20-37", "list": 20, "number": 37, "english": "act", "phonetic": "/ækt/", "chinese": "v. 表现，行动", "example": "We must act to protect the environment. 我们必须行动起来保护环境。", "page": 100}, {"id": "20-38", "list": 20, "number": 38, "english": "rough", "phonetic": "/rʌf/", "chinese": "adj. 粗糙的", "example": "The tree bark felt rough to touch. 树皮摸起来很粗糙。", "page": 100}, {"id": "20-39", "list": 20, "number": 39, "english": "mirror", "phonetic": "/ˈmɪrər/", "chinese": "n. 镜子", "example": "There is a large mirror in the hall. 大厅里有一面大镜子。", "page": 100}, {"id": "20-40", "list": 20, "number": 40, "english": "get dressed", "phonetic": "/get drest/", "chinese": "穿衣服", "example": "I usually get dressed at seven o'clock. 我通常七点钟穿衣服。", "page": 100}, {"id": "20-41", "list": 20, "number": 41, "english": "electricity", "phonetic": "/ɪˌlekˈtrɪsəti/", "chinese": "n. 电", "example": "The storm cut off our electricity supply. 暴风雨切断了我们的电力供应。", "page": 101}, {"id": "20-42", "list": 20, "number": 42, "english": "program", "phonetic": "/ˈproʊɡræm/", "chinese": "v. 编写程序", "example": "She can program simple computer games. 她会编写简单的电脑游戏。", "page": 101}, {"id": "20-43", "list": 20, "number": 43, "english": "pick up", "phonetic": "/pɪk ʌp/", "chinese": "拿起", "example": "Can you pick up that book for me? 你能帮我捡起那本书吗？", "page": 101}, {"id": "20-44", "list": 20, "number": 44, "english": "voice", "phonetic": "/vɔɪs/", "chinese": "n. 声音", "example": "Her voice sounds clear and sweet. 她的声音听起来清晰甜美。", "page": 101}, {"id": "20-45", "list": 20, "number": 45, "english": "elderly", "phonetic": "/ˈeldərli/", "chinese": "n. 老年人/adj. 年迈的", "example": "We should help the elderly in need. 我们应该帮助有需要的老年人。", "page": 101}, {"id": "20-46", "list": 20, "number": 46, "english": "stair", "phonetic": "/ster/", "chinese": "n. 楼梯", "example": "Be careful when you walk down the stairs. 下楼梯时要小心。", "page": 101}, {"id": "20-47", "list": 20, "number": 47, "english": "frog", "phonetic": "/frɑːɡ/", "chinese": "n. 青蛙", "example": "A little green frog sat on a leaf. 一只绿色的小青蛙坐在叶子上。", "page": 101}, {"id": "20-48", "list": 20, "number": 48, "english": "beg", "phonetic": "/beɡ/", "chinese": "v. 恳求，乞求", "example": "The child begged for one more cookie. 孩子恳求再给一块饼干。", "page": 101}, {"id": "20-49", "list": 20, "number": 49, "english": "sleeve", "phonetic": "/sliːv/", "chinese": "n. 袖子", "example": "He rolled up his sleeves to wash dishes. 他卷起袖子来洗碗。", "page": 101}, {"id": "20-50", "list": 20, "number": 50, "english": "drone", "phonetic": "/droʊn/", "chinese": "n. 无人机", "example": "They used a drone to film the scenery. 他们用无人机拍摄风景。", "page": 101}];
